/* Wissen › Wiederholung, KW 47/2026. Entwurf, fachlich prüfen. */
WDH_woche({"kw": "2026-W47", "von": "2026-11-16", "bis": "2026-11-22", "plan": {"mo": "w47-fs", "mi": "w47-ks"}, "einheiten": [{"id": "w47-fs", "titel": "Frozen Shoulder", "art": "kb", "kb": "SH04", "min": 12, "abschnitte": [{"t": "Kapselmuster auf einen Blick", "b": [{"bars": [["Außenrotation", 30, "stark eingeschränkt"], ["Abduktion", 55, "mittel"], ["Innenrotation", 75, "am wenigsten"]], "p": ["[[Kapselmuster nach Cyriax|cyriax]], schematisch als Anteil vom Normwert. Aktiv und passiv eingeschränkt."]}]}, {"t": "1. Was ist das eigentlich?", "b": [{"p": ["Eine Entzündung der Gelenkkapsel, die in eine Fibrose übergeht. Die Kapsel verdickt und schrumpft, vor allem im [[Rotatorenintervall|rotatorenintervall]] und am Lig. coracohumerale. Deshalb leidet die Außenrotation zuerst und am stärksten."]}, {"l": ["Häufigkeit: etwa 2–5 % der Bevölkerung, meist zwischen 40 und 65, Frauen öfter als Männer.", "Primär (idiopathisch) ohne erkennbaren Auslöser, sekundär nach Trauma, OP oder Ruhigstellung.", "Risikofaktoren: Diabetes mellitus (deutlich höheres Risiko, oft schwerer und länger), Schilddrüsenerkrankungen, [[Morbus Dupuytren|dupuytren]], Fettstoffwechselstörungen.", "Die Gegenseite ist in einem Teil der Fälle später auch dran. Dasselbe Gelenk zweimal ist selten."]}]}, {"t": "2. Die drei Phasen", "b": [{"tab": [["Freezing", "Schmerz steht im Vordergrund, Nachtschmerz. Ca. 2–9 Monate."], ["Frozen", "Schmerz lässt nach, Steifigkeit bleibt. Ca. 4–12 Monate."], ["Thawing", "Beweglichkeit kommt langsam zurück. Ca. 5–24 Monate."]], "p": ["Wichtig für die Aufklärung: Die Phasen gehen fließend ineinander über, und das alte „nach zwei Jahren ist alles weg“ stimmt so nicht. Ein relevanter Teil der Patienten hat auch nach Jahren noch [[leichte Restbeschwerden|langzeitverlauf]] oder ein Bewegungsdefizit, meistens aber ohne große Einschränkung im Alltag."]}]}, {"t": "3. Befund und Abgrenzung", "b": [{"p": ["Leitbefund ist die passiv eingeschränkte Außenrotation mit festem Endgefühl. Das Röntgen ist unauffällig, es dient dazu, anderes auszuschließen."]}, {"tab": [["Rotatorenmanschetten-Ruptur", "Aktiv eingeschränkt, passiv weitgehend frei"], ["Omarthrose", "Ähnliches Muster, aber Röntgen zeigt Gelenkspaltverschmälerung und Osteophyten, Krepitation"], ["[[Verhakte hintere Luxation|hintereluxation]]", "AR praktisch null, oft nach Sturz oder Krampfanfall. Wird gern übersehen."], ["Tendinosis calcarea", "Akuter, heftiger Schmerz, Kalk im Röntgen"], ["Subakromiales Schmerzsyndrom", "[[Painful Arc|painfularc]], passive AR meist frei"]], "merk": "Wenn die passive AR frei ist, ist es keine Frozen Shoulder."}]}, {"t": "4. Bildgebung: so sieht es aus", "b": [{"p": ["Bei der Frozen Shoulder ist das Röntgenbild normal. Bestätigt wird sie im MRT. Das Röntgen braucht man trotzdem, und zwar für die Differenzialdiagnosen."], "fig": [{"src": "fortbildung/bilder/2026-W47/fs-mrt-sagittal.webp", "t": "MRT schräg-sagittal, Frozen Shoulder.", "c": "Der Humeruskopf ist von lateral als Kreis zu sehen, oben rechts liegt das Coracoid. Der Pfeil zeigt auf das verdickte, dunkle Lig. coracohumerale. Das helle Fettdreieck im Rotatorenintervall darunter fehlt. Das ist eines der spezifischsten Zeichen."}, {"src": "fortbildung/bilder/2026-W47/fs-mrt-koronal.webp", "t": "MRT koronal, Frozen Shoulder.", "c": "Der Pfeil zeigt auf den Recessus axillaris. Die Kapsel ist dort verdickt und hell (Ödem), die Tasche eng statt locker entfaltet. Als Faustregel gilt eine Kapseldicke über 4 mm als auffällig."}, {"src": "fortbildung/bilder/2026-W47/fs-luxation.webp", "t": "Röntgen a.p., hintere Luxation.", "c": "Der Kopf ist stark innenrotiert und wirkt rund wie eine Glühbirne („Lightbulb Sign“). Der normale Halbmond aus Kopf und Pfanne fehlt. Sicher wird die Diagnose erst mit der axialen oder der Y-Aufnahme."}, {"src": "fortbildung/bilder/2026-W47/fs-kalk.webp", "t": "Röntgen a.p., Tendinosis calcarea.", "c": "Eine dichte, weiße Kalkwolke liegt über dem Tuberculum majus im Verlauf der Supraspinatussehne. Der Gelenkspalt ist normal."}]}, {"p": ["KI-erstellte Lehrbilder nach typischen Lehrbuchfällen, geprüft, keine echten Aufnahmen."]}]}, {"t": "5. Was hilft laut Studienlage?", "b": [{"l": ["Aufklärung ist Teil der Therapie. Der Verlauf ist lang, aber gutartig. Wer das weiß, hält besser durch.", "Kortison intraartikulär wirkt in den ersten Wochen besser als Physio allein, gerade in der schmerzhaften Phase. Kombiniert mit Physiotherapie schneidet es am besten ab. Der Vorteil wird nach einigen Monaten kleiner.", "Freezing-Phase: nicht gegen den Schmerz dehnen. Diercks und Stevens (2004) fanden, dass Patienten mit schonender Therapie im schmerzfreien Bereich („supervised neglect“) besser abschnitten als mit intensiver Dehnung und Mobilisation über die Schmerzgrenze.", "Frozen- und Thawing-Phase: Dosis steigern. Gelenkmobilisation, Kapseldehnung, Übungen für zuhause. Für die AR gibt es Hinweise, dass Gleitmobilisation nach dorsal mehr bringt als nach ventral (Johnson et al. 2007).", "[[Hydrodilatation|hydrodilatation]] ist eine Option bei hartnäckigen Fällen, mit kurzfristigem Nutzen.", "Operation: Die britische [[FROST-Studie|frost]] (Lancet 2020) verglich Narkosemobilisation, arthroskopische Kapsulotomie und frühe strukturierte Physio mit Kortison. Nach 12 Monaten gab es keinen klinisch relevanten Unterschied. Die Physio-Variante war die günstigste und hatte die wenigsten Risiken."]}]}, {"t": "6. Für den Praxisalltag", "b": [{"l": ["Erst die Phase bestimmen, dann dosieren. Faustregel: Schmerz größer als Steifigkeit heißt sanft, Steifigkeit größer als Schmerz heißt fordern.", "AR in 0° und 90° Abduktion messen und im Verlauf dokumentieren. Kleine Fortschritte motivieren.", "Bei Diabetikern mit längerem Verlauf rechnen und das offen sagen.", "Bei AR nahe null und Sturz in der Anamnese an die hintere Luxation denken und zurück zum Arzt schicken."]}]}], "quellen": ["Kelley MJ et al. Adhesive Capsulitis CPG. JOSPT 2013", "Diercks RL, Stevens M. J Shoulder Elbow Surg 2004", "Johnson AJ et al. JOSPT 2007", "Rangan A et al. FROST. Lancet 2020"], "fragen": [["Welche Bewegung ist bei der Frozen Shoulder typischerweise am stärksten eingeschränkt?", ["Innenrotation", "Abduktion", "Außenrotation", "Flexion"], 2, "Kapselmuster nach Cyriax: AR vor Abduktion vor IR. Grund ist die Schrumpfung im Rotatorenintervall und am Lig. coracohumerale."], ["Aktive Elevation stark eingeschränkt, passive Beweglichkeit fast frei. Woran denkst du zuerst?", ["Frozen Shoulder in der Frozen-Phase", "Rotatorenmanschetten-Ruptur", "Omarthrose", "Adhäsive Kapsulitis bei Diabetes"], 1, "Bei der Frozen Shoulder sind aktiv und passiv eingeschränkt. Passiv frei spricht für ein Problem der kontraktilen Strukturen, etwa eine Ruptur."], ["Welche Grunderkrankung erhöht das Risiko einer Frozen Shoulder deutlich?", ["Asthma", "Diabetes mellitus", "Arterielle Hypertonie", "Osteoporose"], 1, "Diabetiker erkranken deutlich häufiger, oft beidseitig und mit längerem Verlauf. Auch Schilddrüsenerkrankungen und Dupuytren sind Risikofaktoren."], ["Patient in der Freezing-Phase, starker Nachtschmerz. Was ist laut Diercks & Stevens sinnvoller?", ["Intensive Dehnung bis über die Schmerzgrenze", "Schonende Therapie im schmerzfreien Bereich", "Komplette Ruhigstellung", "Sofort Narkosemobilisation"], 1, "\"Supervised neglect\", also Bewegung im schmerzarmen Bereich plus Aufklärung, schnitt besser ab als intensive Physio über die Schmerzgrenze."], ["Was gilt für die intraartikuläre Kortisoninjektion?", ["Sie hat gar keinen Nutzen", "Sie wirkt vor allem kurzfristig, am besten zusammen mit Physio", "Sie heilt die Fibrose dauerhaft", "Sie ist nur in der Thawing-Phase sinnvoll"], 1, "Der Effekt ist in den ersten Wochen am größten, besonders in der schmerzhaften Phase. Mit Physio kombiniert schneidet sie am besten ab."], ["Welche Gleitrichtung zeigte bei Johnson et al. (2007) mehr Gewinn an Außenrotation?", ["Ventral", "Dorsal", "Kaudal", "Lateral"], 1, "Die dorsale Gleitmobilisation brachte deutlich mehr AR als die ventrale, obwohl das konvex-konkav-Denken eher ventral vermuten ließe."], ["Was zeigte die FROST-Studie nach 12 Monaten?", ["OP war klar überlegen", "Narkosemobilisation war klar überlegen", "Kein klinisch relevanter Unterschied zwischen OP, Narkosemobilisation und Physio mit Kortison", "Physio allein war schlechter als alles andere"], 2, "Alle drei Wege lagen nach einem Jahr klinisch gleichauf. Physio plus Kortison war am günstigsten und hatte die wenigsten Risiken."], ["AR fast null nach Sturz, Röntgen nur in einer Ebene gemacht. Woran musst du denken?", ["Frozen Shoulder, einfach weiter behandeln", "Verhakte hintere Schulterluxation", "Bizepssehnenreizung", "Impingement"], 1, "Die hintere Luxation wird gern übersehen und sieht klinisch ähnlich aus. Hier gehört der Patient zurück zum Arzt, mit Röntgen in zwei Ebenen bzw. axial."], ["Welches Bildgebungszeichen spricht am ehesten für eine Frozen Shoulder?", ["Kalkwolke über dem Tuberculum majus", "Verdicktes Lig. coracohumerale und fehlendes Fett im Rotatorenintervall im MRT", "Runder Humeruskopf im Röntgen a.p.", "Gelenkspaltverschmälerung mit Osteophyten"], 1, "Das Röntgen ist bei der Frozen Shoulder normal. Im MRT sind das verdickte Lig. coracohumerale, das verschwundene Fettdreieck und die verdickte Kapsel im Recessus axillaris typisch. Die anderen Antworten passen zu Kalkschulter, hinterer Luxation und Omarthrose."], ["Worauf zeigt der gelbe Pfeil in diesem schräg-sagittalen MRT?", ["Supraspinatussehne", "Lange Bizepssehne", "Verdicktes Lig. coracohumerale im Rotatorenintervall", "Labrum glenoidale"], 2, "Der Pfeil zeigt auf das verdickte Lig. coracohumerale direkt unter dem Coracoid (oben rechts im Bild). Das helle Fettdreieck im Rotatorenintervall fehlt. Das passt zur Frozen Shoulder und erklärt, warum die Außenrotation zuerst leidet.", "fortbildung/bilder/2026-W47/fs-mrt-sagittal.webp"], ["Welche Struktur ist in diesem koronalen MRT markiert, und was bedeutet der Befund?", ["Recessus axillaris mit verdickter, ödematöser Kapsel: Frozen Shoulder", "Supraspinatussehne mit Ruptur", "Bursa subacromialis mit Bursitis", "Gelenkerguss bei Arthrose"], 0, "Der Pfeil liegt unten im Recessus axillaris, der unteren Kapseltasche. Die Kapsel ist dort verdickt und hell, die Tasche eng. Ein typisches MRT-Zeichen der Frozen Shoulder, das zur eingeschränkten Abduktion passt.", "fortbildung/bilder/2026-W47/fs-mrt-koronal.webp"], ["Röntgen a.p. nach einem Sturz, die Außenrotation ist fast null. Was zeigt das Bild?", ["Normalbefund, typisch für Frozen Shoulder", "Hintere Schulterluxation (Lightbulb Sign)", "Vordere Schulterluxation", "Humeruskopffraktur"], 1, "Der Kopf ist stark innenrotiert und wirkt rund wie eine Glühbirne, der normale Halbmond aus Kopf und Pfanne fehlt. Verdacht auf hintere Luxation: Der Patient muss zurück zum Arzt, sicher wird die Diagnose mit axialer oder Y-Aufnahme.", "fortbildung/bilder/2026-W47/fs-luxation.webp"], ["Was zeigt der Pfeil in diesem Röntgenbild?", ["Osteophyt bei Omarthrose", "Abrissfragment des Tuberculum majus", "Kalkdepot in der Supraspinatussehne", "Acromion-Sporn"], 2, "Die dichte, ovale Verschattung über dem Tuberculum majus im Verlauf der Supraspinatussehne ist ein Kalkdepot (Tendinosis calcarea). Der Gelenkspalt ist normal, es gibt also keinen Hinweis auf Arthrose.", "fortbildung/bilder/2026-W47/fs-kalk.webp"]], "info": {"cyriax": {"t": "Kapselmuster", "x": ["Cyriax beschrieb für jedes Gelenk eine typische Reihenfolge, in der die Bewegungen eingeschränkt sind, wenn die ganze Kapsel betroffen ist. Gemeint ist eine passive Einschränkung im festen Verhältnis zueinander, nicht nur eine einzelne gestörte Richtung.", "Ein nicht kapsuläres Muster, also etwa nur eine Richtung betroffen, spricht eher für eine lokale Ursache wie einen eingeklemmten Gelenkkörper oder eine Bursitis. Das Muster ist ein Hinweis, kein Beweis."]}, "rotatorenintervall": {"t": "Rotatorenintervall", "x": ["Dreieckiger Kapselbereich zwischen dem Vorderrand des Supraspinatus und dem Oberrand des Subscapularis, mit der Basis am Coracoid. Darin liegen das Lig. coracohumerale, das Lig. glenohumerale superius und die lange Bizepssehne.", "Diese Strukturen werden bei Außenrotation mit hängendem Arm straff. Schrumpfen sie, ist deshalb vor allem die AR in 0° Abduktion blockiert."]}, "dupuytren": {"t": "Morbus Dupuytren", "x": ["Bindegewebige Verhärtung der Hohlhand mit Knoten und Strängen, die die Finger zunehmend in Beugung ziehen, oft am Ring- und Kleinfinger.", "Die Kapsel bei Frozen Shoulder zeigt unter dem Mikroskop ein ähnliches Bild mit vielen Myofibroblasten. Beide gelten als verwandte Fibrose-Erkrankungen. In der Anamnese lohnt deshalb ein kurzer Blick auf die Hände."], "q": "Bunker und Anthony, J Bone Joint Surg Br 1995"}, "langzeitverlauf": {"t": "Langzeitverlauf", "x": ["Eine Nachbeobachtung von 269 Schultern bei 223 Patienten im Mittel 4,4 Jahre nach Beginn: 59 % hatten eine normale oder fast normale Schulter, 41 % noch Beschwerden.", "Schwere Beschwerden mit Schmerz und Funktionsverlust blieben aber nur bei 6 %. Für die Aufklärung heißt das: gute Aussichten, aber kein Versprechen auf völlige Beschwerdefreiheit."], "q": "Hand C et al., J Shoulder Elbow Surg 2008"}, "hintereluxation": {"t": "Hintere Schulterluxation", "x": ["Nur etwa 2–5 % aller Schulterluxationen, aber bis zur Hälfte wird beim ersten Arztkontakt übersehen. Typische Auslöser sind Krampfanfall und Stromunfall, eine nächtliche Luxation ohne Unfall spricht für einen Anfall.", "Der Arm wird adduziert und innenrotiert gehalten, die AR geht schmerzbedingt nicht. Auf dem normalen a.p.-Bild ist sie leicht zu übersehen.", "Bei Verdacht nicht mobilisieren, sondern zum Arzt zurückschicken und eine axiale Aufnahme anregen."], "q": "StatPearls, Posterior Shoulder Dislocations"}, "painfularc": {"t": "Painful Arc", "x": ["Schmerz bei aktiver Abduktion etwa zwischen 60° und 120°, darunter und darüber weniger. In diesem Bereich steht die Engstelle unter dem Schulterdach am stärksten unter Druck.", "Allein wenig aussagekräftig. Zusammen mit Hawkins-Kennedy-Test und schwacher Außenrotation (Infraspinatus-Test) gehört er zum Cluster nach Park 2005. Schmerz erst ganz am Ende der Elevation deutet eher auf das AC-Gelenk."]}, "hydrodilatation": {"t": "Hydrodilatation", "x": ["Unter Ultraschall- oder Röntgenkontrolle wird eine größere Menge Flüssigkeit, meist Kochsalzlösung mit Kortison und Betäubungsmittel, unter Druck ins Gelenk gespritzt. Das dehnt die geschrumpfte Kapsel auf, manchmal reißt sie dabei ein.", "Eine Übersichtsarbeit sah die Kombination mit Kortison kurzfristig bei den konservativen Verfahren vorn, allerdings auf Basis von Reviews niedriger Qualität. Direkt danach mit Mobilisation und Übungen anschließen."]}, "frost": {"t": "UK FROST", "x": ["503 Erwachsene mit primärer Frozen Shoulder an 35 Kliniken des britischen Gesundheitsdienstes, Vergleich von drei Behandlungen über 12 Monate.", "Ernste Komplikationen: 8 nach Kapsulotomie, 2 nach Narkosemobilisation, keine bei Physio. Eine weitere Behandlung brauchten 15 % nach Physio, 7 % nach Narkosemobilisation, 4 % nach OP. Als bestes Kosten-Nutzen-Verhältnis bewerteten die Autoren die Narkosemobilisation."], "q": "Rangan A et al., Lancet 2020"}}}, {"id": "w47-ks", "titel": "Nicht-spezifischer Kreuzschmerz", "art": "kb", "kb": "WS01", "min": 12, "abschnitte": [{"t": "1. Was ist das eigentlich?", "b": [{"p": ["Kreuzschmerz ohne sicheren Hinweis auf eine spezifische Ursache wie Fraktur, Tumor, Entzündung, Infektion oder radikuläre Kompression. Das betrifft rund 85–90 % der Rückenschmerzen in der Grundversorgung. Gemeint ist ein Schmerzsyndrom, keine [[Strukturdiagnose|struktur]]."]}, {"l": ["Häufigkeit: Die Lebenszeitprävalenz liegt bei über 70 %. In Deutschland hatten 61 % der Erwachsenen in den letzten 12 Monaten Rückenschmerz, 15,5 % chronisch (RKI BURDEN 2020). Weltweit ist Kreuzschmerz die häufigste Ursache für Jahre mit Beeinträchtigung.", "Rückfälle sind häufig: In einem systematischen Review hatte etwa ein Drittel innerhalb eines Jahres nach Erholung eine neue Episode, in einer Kohorte mit monatlicher Nachfrage 69 %, davon 40 % mit Einschränkung im Alltag (da Silva 2017 und 2019). Die Zahl hängt davon ab, wie eng man fragt.", "Risikofaktoren für einen chronischen Verlauf sind vor allem psychosozial und beruflich, weniger strukturell: [[Angst-Vermeidungs-Überzeugungen|angst]], [[Katastrophisieren|katastroph]], depressive Stimmung, geringe Arbeitszufriedenheit, passives Krankheitsverhalten."]}]}, {"t": "2. Einteilung und Verlauf", "b": [{"tab": [["Akut", "unter 6 Wochen"], ["Subakut", "6–12 Wochen"], ["Chronisch", "über 12 Wochen"], ["Rezidivierend", "neue Episode nach mindestens 6 Monaten Beschwerdefreiheit"]], "p": ["Akuter Kreuzschmerz bessert sich bei den meisten innerhalb weniger Wochen deutlich: Im Mittel sinkt der Schmerz in den ersten 6 Wochen von 52 auf 23 von 100 und liegt nach einem Jahr bei 6 (Menezes Costa 2012). Ein Teil behält aber über Monate Beschwerden. Deshalb nach etwa 4 Wochen ohne Besserung die psychosozialen Risikofaktoren gezielt prüfen."]}]}, {"t": "3. Red Flags zuerst", "b": [{"tab": [["[[Cauda equina|cauda]]", "Reithosenanästhesie, Blasen- oder Mastdarmstörung, beidseitige Ausfälle: sofort Notaufnahme"], ["Fraktur", "relevantes Trauma, Osteoporose, längere Kortisoneinnahme, höheres Alter"], ["Tumor", "Krebs in der Vorgeschichte, ungewollter Gewichtsverlust, Nachtschmerz, Alter über 50"], ["Infektion", "Fieber, Immunsuppression, i.v.-Drogenkonsum, kürzlich Infektion oder Eingriff"], ["Radikulär", "fortschreitende Lähmung, ausgeprägtes neurologisches Defizit"], ["Axiale Spondyloarthritis", "Beginn vor 45, [[entzündlicher Rückenschmerz|entzuendlich]]: Morgensteifigkeit über 30 min, Besserung durch Bewegung, nächtliches Erwachen"]], "merk": "Ein einzelnes Warnzeichen ist selten beweisend. Entscheidend ist das Gesamtbild, bei Cauda-Zeichen aber immer sofort handeln."}]}, {"t": "4. Befund und Abgrenzung", "b": [{"p": ["Der Befund dient vor allem dazu, Warnzeichen und radikuläre Beteiligung zu erkennen und den Patienten funktionell einzuordnen. Eine Strukturdiagnose wie „Facettengelenk“ oder „ISG“ ist im Alltag kaum zuverlässig zu stellen."]}, {"tab": [["Radikulopathie", "Beinschmerz stärker als Rückenschmerz, dermatomale Ausstrahlung, positiver SLR bzw. gekreuzter SLR, Reflex- oder Kraftdefizit"], ["Spinalkanalstenose", "[[Claudicatio spinalis|claudicatio]], Besserung beim Vorneigen und Sitzen, meist älter"], ["Axiale SpA", "entzündliches Schmerzmuster, jüngere Patienten, eventuell Uveitis oder Psoriasis"], ["Osteoporotische Fraktur", "akuter Schmerz nach Bagatelltrauma, ältere Patientin, Klopfschmerz"], ["Viszeral", "Schmerz unabhängig von Bewegung und Haltung, z. B. Niere, Pankreas, Aortenaneurysma"]]}, {"l": ["[[STarT Back|startback]] (9 Fragen) teilt in niedriges, mittleres und hohes Risiko für einen ungünstigen Verlauf ein.", "Alternative zu STarT Back: Örebro-Kurzbogen, ab 50 Punkten erhöhtes Risiko. Spätestens nach 4 Wochen ohne ausreichende Besserung einen der beiden einsetzen.", "[[Oswestry Disability Index|odi]] oder [[Roland-Morris|rmdq]] zur Verlaufsmessung der Funktion. Spürbare Änderung: ODI 10 Punkte, RMDQ 5 Punkte, Schmerz (NRS) 2 Punkte oder 30 % (Ostelo 2008).", "Wiederholte Bewegungen prüfen: Bessert eine Richtung den Schmerz oder zieht er sich zur Mitte zurück (Richtungspräferenz), baut das Heimprogramm darauf auf."]}]}, {"t": "5. Bildgebung: weniger ist mehr", "b": [{"p": ["Ohne Red Flags soll in den ersten Wochen keine Bildgebung erfolgen. Viele Befunde sind auch bei Schmerzfreien häufig. In einer großen Übersicht ([[Brinjikji 2015|brinjikji]]) zeigten schon 20-Jährige ohne Schmerzen in etwa 30 % eine Bandscheibenvorwölbung, 80-Jährige in rund 84 %. Degenerative Veränderungen sind also eher Altersbefund als Ursache."], "fig": [{"src": "fortbildung/bilder/2026-W47/ks-mrt.webp", "t": "MRT sagittal.", "c": "Eine dehydrierte, dunklere Bandscheibe mit leichter Vorwölbung nach dorsal. So ein Befund ist häufig und erklärt den Schmerz allein nicht."}], "merk": "Befund ist nicht gleich Ursache. Unnötige Bilder machen Angst und können den Verlauf verschlechtern."}, {"p": ["KI-erstellte Lehrbilder nach typischen Lehrbuchfällen, geprüft, keine echten Aufnahmen."]}]}, {"t": "6. Was hilft laut Studienlage?", "b": [{"l": ["Aufklärung und Beruhigung: gute Prognose, aktiv bleiben, keine Bettruhe. [[Schmerz bedeutet nicht Schaden|schmerzedu]].", "Bewegungstherapie ist der Kern bei subakutem und chronischem Verlauf. Bei chronischem Kreuzschmerz senkt sie den Schmerz um etwa 15 von 100 Punkten gegenüber keiner Behandlung (Cochrane, Hayden 2021). Keine Übungsform ist klar überlegen, wichtiger sind Dosis, Regelmäßigkeit und was der Patient gern macht. Gruppenprogramme sind gut belegt.", "Cognitive Functional Therapy bei chronischem, einschränkendem Kreuzschmerz mit Bewegungsangst und Schonverhalten: In der RESTORE-Studie (Lancet 2023) mit bis zu 7 Terminen in 12 Wochen war die Funktion (RMDQ) 4,6 Punkte besser als bei üblicher Versorgung, über ein Jahr anhaltend.", "Vorbeugung: Übungen plus Edukation senken das Rückfallrisiko um etwa 45 %. Edukation allein, Gurte und Einlagen wirken nicht (Steffens 2016).", "Manuelle Therapie nur zusammen mit Übungen, nicht als alleinige Behandlung.", "Wärme kann bei akutem Schmerz kurzfristig helfen, kombiniert mit Aktivierung.", "Nicht empfohlen: TENS, Kinesiotape, therapeutischer Ultraschall, passive Maßnahmen allein.", "Bei Risikofaktoren und anhaltenden Beschwerden ab etwa 6 Wochen an eine [[multimodale Behandlung|multimodal]] denken ([[NVL|nvl]], seit Ende 2021 abgelaufen, Stand 2017).", "Neu 2026: [[NICE hat Teile seiner Leitlinie gestrichen|nice]]. Psychologische Therapie (KVT) im Paket und kombinierte körperlich-psychologische Programme stehen dort nicht mehr drin. Die deutsche NVL empfiehlt sie weiter, ist aber abgelaufen. Für die Praxis heißt das: Ängste und Überzeugungen weiter ansprechen, ein psychologisches Programm aber begründet und nicht automatisch nach STarT Back empfehlen."]}]}, {"t": "7. Für den Praxisalltag", "b": [{"l": ["In der ersten Einheit Red Flags abfragen und dokumentieren, auch wenn alles unauffällig ist.", "Sprache bewusst wählen: „Die Bandscheibe ist rausgesprungen“ oder „Ihr Rücken ist kaputt“ schürt Angst. Besser: „Der Rücken ist stark und belastbar.“", "STarT Back früh nutzen. Niedriges Risiko: wenige Termine, Aufklärung, Aktivierung. Hohes Risiko: engmaschiger, auf Ängste eingehen.", "Ziele an Aktivitäten festmachen, die dem Patienten wichtig sind, nicht am Schmerzwert allein.", "Bei Beinschmerz bis unter das Knie, Taubheit oder Schwäche radikulär untersuchen und im Verlauf neu prüfen."]}]}], "quellen": ["Nationale VersorgungsLeitlinie Nicht-spezifischer Kreuzschmerz, 2. Auflage 2017, nvl-007, gültig bis 30.12.2021 (abgelaufen, in Überarbeitung)", "NICE NG59, Aktualisierung 29.07.2026", "George SZ et al. JOSPT Low Back Pain CPG, Revision 2021", "WHO Guideline chronic primary low back pain 2023", "Hayden JA et al. Exercise therapy for chronic low back pain. Cochrane 2021", "Kent P et al. RESTORE. Lancet 2023", "Steffens D et al. JAMA Intern Med 2016", "Menezes Costa L et al. CMAJ 2012", "Ostelo RW et al. Spine 2008", "Brinjikji W et al. AJNR 2015", "Hill JC et al. STarT Back. Lancet 2011", "da Silva T et al. Risk of recurrence of low back pain. JOSPT 2017", "da Silva T et al. Recurrence of low back pain is common. J Physiother 2019", "RKI BURDEN 2020", "Hartvigsen J et al. Lancet Low Back Pain Series 2018"], "fragen": [["Was ist bei Kreuzschmerz ohne Red Flags in den ersten Wochen das richtige Vorgehen bei der Bildgebung?", ["Sofort MRT, um einen Vorfall auszuschließen", "Röntgen in zwei Ebenen als Basis", "Keine Bildgebung, aktivieren und aufklären", "CT, weil schneller als MRT"], 2, "Ohne Warnzeichen bringt frühe Bildgebung keinen Nutzen. Sie findet häufige Zufallsbefunde, kann Angst machen und führt zu mehr Behandlung ohne besseres Ergebnis."], ["Welche Kombination ist ein Warnzeichen für ein Cauda-equina-Syndrom?", ["Nachtschmerz und Morgensteifigkeit", "Reithosenanästhesie und Blasenstörung", "Ausstrahlung bis in die Wade", "Schmerz beim Husten"], 1, "Taubheit im Reithosenbereich mit Blasen- oder Mastdarmstörung ist ein Notfall. Der Patient muss sofort in die Notaufnahme."], ["Was zeigt der Pfeil in diesem MRT der LWS?", ["Wirbelkörperfraktur", "Wirbelgleiten (Spondylolisthese)", "Dehydrierte Bandscheibe mit leichter Vorwölbung", "Tumor im Spinalkanal"], 2, "Die markierte Bandscheibe ist dunkler (weniger Wasser) und wölbt sich leicht nach hinten vor. So ein Befund ist auch bei Schmerzfreien häufig.", "fortbildung/bilder/2026-W47/ks-mrt.webp"], ["Wie häufig sind Bandscheibenvorwölbungen bei schmerzfreien 50-Jährigen ungefähr?", ["Unter 10 %", "Etwa jeder Fünfte", "Rund die Hälfte und mehr", "Praktisch nie"], 2, "Laut Brinjikji 2015 steigt der Anteil mit dem Alter von etwa 30 % mit 20 Jahren auf über 80 % mit 80. Mit 50 hat gut die Hälfte eine Vorwölbung, ohne Schmerzen."], ["Was soll man Patienten mit akutem Kreuzschmerz zur Aktivität raten?", ["Ein paar Tage Bettruhe", "Aktiv bleiben und den Alltag möglichst weiterführen", "Nur liegen und Wärme", "Sport komplett meiden, bis der Schmerz weg ist"], 1, "Bettruhe verzögert die Erholung. Aktiv bleiben ist eine der am besten gestützten Empfehlungen."], ["Was gilt laut Leitlinien für manuelle Therapie bei Kreuzschmerz?", ["Als alleinige Therapie empfohlen", "Nur zusammen mit Bewegungstherapie", "Grundsätzlich kontraindiziert", "Nur bei Red Flags"], 1, "NICE und NVL sehen manuelle Therapie, wenn überhaupt, als Teil eines Pakets mit Übungen, nicht als Einzeltherapie."], ["Welche Maßnahme wird bei nicht-spezifischem Kreuzschmerz nicht empfohlen?", ["Gruppentraining", "Edukation", "TENS", "Graduierte Aktivierung"], 2, "TENS, Kinesiotape und therapeutischer Ultraschall zeigen keinen relevanten Nutzen und werden nicht empfohlen."], ["Wozu dient der STarT-Back-Fragebogen?", ["Red Flags erkennen", "Das Risiko für einen ungünstigen Verlauf einschätzen", "Den Bandscheibenvorfall lokalisieren", "Die Schmerzstärke messen"], 1, "STarT Back teilt in niedriges, mittleres und hohes Risiko für einen chronischen Verlauf ein. Danach richtet sich, wie intensiv man behandelt."], ["Was hat NICE am 29. Juli 2026 in der Leitlinie NG59 geändert?", ["Manuelle Therapie ganz gestrichen", "Psychologische Therapie als Standardempfehlung zurückgezogen", "Bildgebung bei jedem Patienten empfohlen", "Bettruhe wieder empfohlen"], 1, "Zwei Empfehlungen zu psychologischer Therapie und kombinierten Programmen wurden zurückgezogen. Übungen, Selbstmanagement und Risikoeinstufung bleiben."], ["Ab wann spricht man von chronischem Kreuzschmerz?", ["Nach 4 Wochen", "Nach 6 Wochen", "Nach 12 Wochen", "Nach 6 Monaten"], 2, "Akut unter 6 Wochen, subakut 6 bis 12 Wochen, chronisch ab 12 Wochen."], ["Wie viele hatten in einer Kohorte mit monatlicher Nachfrage innerhalb eines Jahres nach Erholung einen Rückfall?", ["Etwa 10 %", "Etwa 33 %", "Etwa 69 %", "Fast alle"], 2, "In der Kohorte von da Silva 2019 hatten 69 % innerhalb von 12 Monaten eine neue Episode, 40 % eine, die den Alltag einschränkte. Ein Review fand etwa 33 %; die Zahl hängt von der Definition ab."], ["Für wen ist Cognitive Functional Therapy laut RESTORE-Studie gedacht?", ["Akuter Kreuzschmerz in der ersten Woche", "Chronischer, einschränkender Kreuzschmerz mit Bewegungsangst und Schonverhalten", "Radikulopathie mit Lähmung", "Nur nach Bandscheiben-OP"], 1, "RESTORE (Lancet 2023): bis zu 7 Termine in 12 Wochen, Funktion (RMDQ) 4,6 Punkte besser als übliche Versorgung, über ein Jahr anhaltend."], ["Ab welcher Änderung des Oswestry Disability Index spricht man von einer spürbaren Verbesserung?", ["2 Punkte", "5 Punkte", "10 Punkte", "25 Punkte"], 2, "Nach Ostelo 2008: ODI 10 Punkte, RMDQ 5 Punkte, Schmerz (NRS) 2 Punkte oder 30 %."]], "info": {"struktur": {"t": "Strukturdiagnose", "x": ["Eine Diagnose, die den Schmerz einer bestimmten Struktur zuschreibt, etwa Bandscheibe, Facettengelenk oder ISG.", "Beim Kreuzschmerz gelingt das im Alltag selten zuverlässig: Klinische Tests und Bildbefunde passen oft nicht zum Schmerz. Deshalb spricht man von nicht-spezifischem Kreuzschmerz und behandelt nach Funktion, Verlauf und Risikofaktoren."]}, "angst": {"t": "Angst-Vermeidungs-Überzeugungen", "x": ["Die Annahme, dass Bewegung oder Belastung den Rücken schädigt und man sie deshalb meiden muss (englisch fear-avoidance beliefs).", "Im Fear-Avoidance-Modell führt das in einen Kreislauf: Schmerz, Angst, Schonung, weniger Belastbarkeit, mehr Beeinträchtigung. Gegenmittel sind Aufklärung und schrittweise Belastung genau der gefürchteten Bewegungen (graded exposure)."], "q": "Vlaeyen und Linton, Pain 2000 und 2012"}, "katastroph": {"t": "Katastrophisieren", "x": ["Eine gedankliche Neigung, Schmerz als bedrohlich und unkontrollierbar zu erleben: ständiges Grübeln darüber, Übertreiben der Gefahr und Hilflosigkeit.", "Messbar mit der Pain Catastrophizing Scale (13 Fragen). Hohe Werte sagen einen schlechteren Verlauf voraus und sind ein Grund, Ängste aktiv anzusprechen."]}, "cauda": {"t": "Cauda-equina-Syndrom", "x": ["Kompression der Nervenwurzeln unterhalb des Rückenmarks (ab etwa LWK 1/2), meist durch einen großen mittigen Bandscheibenvorfall.", "Frühe Zeichen: Taubheit im Reithosenbereich, Probleme beim Wasserlassen (z. B. Restharn, fehlender Harndrang), beidseitige Beinschmerzen oder Schwäche, nachlassende Sexualfunktion.", "Notfall: Je früher operiert wird, desto besser bleiben Blase und Darm erhalten. Auch bei unsicheren Zeichen noch am selben Tag in die Notaufnahme."]}, "entzuendlich": {"t": "Entzündlicher Rückenschmerz", "x": ["Typisch für die axiale Spondyloarthritis (Morbus Bechterew). Nach den ASAS-Kriterien sprechen mindestens 4 von 5 Merkmalen dafür: Beginn vor 40, schleichender Beginn, Besserung durch Bewegung, keine Besserung in Ruhe, nächtlicher Schmerz mit Besserung beim Aufstehen.", "Bei Rückenschmerz seit mindestens 3 Monaten mit Beginn vor 45 an eine rheumatologische Abklärung denken."]}, "claudicatio": {"t": "Claudicatio spinalis", "x": ["Schmerz, Schwere oder Taubheit in den Beinen beim Gehen und Stehen durch eine Enge im Spinalkanal. Vorneigen weitet den Kanal, deshalb bessert sich der Schmerz im Sitzen und beim Gehen mit Einkaufswagen oder Rollator.", "Abgrenzung zur Gefäß-Claudicatio: Dort reicht kurzes Stehenbleiben, die Fußpulse sind oft schwach, und Radfahren macht ebenfalls Beschwerden."]}, "startback": {"t": "STarT Back Tool", "x": ["9 Fragen zu Schmerz, Funktion und Psyche. Gesamtwert 0–3: niedriges Risiko. Ab 4 entscheiden die Fragen 5–9 (psychosozialer Teil): bis 3 mittleres, ab 4 hohes Risiko für einen ungünstigen Verlauf.", "Niedriges Risiko: wenige Termine, Aufklärung, Aktivierung. Mittleres: Physiotherapie mit Übungen. Hohes: engmaschiger, mit Fokus auf Ängste und Überzeugungen."], "q": "Hill et al., Arthritis Rheum 2008"}, "odi": {"t": "Oswestry Disability Index", "x": ["Fragebogen mit 10 Alltagsbereichen (z. B. Sitzen, Gehen, Heben, Schlafen), Ergebnis in Prozent. 0–20 % gilt als geringe, über 40 % als starke Beeinträchtigung.", "Gut für den Verlauf bei stärker eingeschränkten Patienten."]}, "rmdq": {"t": "Roland-Morris-Fragebogen", "x": ["24 Aussagen zum Alltag, die mit Ja oder Nein beantwortet werden, Wert 0–24. Eine Besserung um etwa 30 % gilt als klinisch relevant.", "Schnell auszufüllen und eher für leichtere bis mittlere Beschwerden geeignet."], "q": "Ostelo et al., Spine 2008"}, "brinjikji": {"t": "Brinjikji 2015", "x": ["Systematische Übersicht über 33 Studien mit rund 3100 Menschen ohne Rückenschmerz, die eine Bildgebung bekommen hatten.", "Bandscheibendegeneration fand sich bei 37 % der 20-Jährigen und 96 % der 80-Jährigen, eine Vorwölbung bei 30 % bzw. 84 %. Solche Befunde gehören zum normalen Altern."], "q": "Brinjikji W et al., AJNR 2015"}, "schmerzedu": {"t": "Schmerz bedeutet nicht Schaden", "x": ["Kernbotschaft der Schmerzedukation: Schmerz ist ein Schutzsignal des Nervensystems und zeigt nicht zuverlässig an, wie viel Gewebe geschädigt ist.", "Bei länger anhaltendem Schmerz wird das System empfindlicher, so dass schon normale Belastung wehtun kann. Wer das versteht, bewegt sich eher und hat weniger Angst."]}, "multimodal": {"t": "Multimodale Behandlung", "x": ["Mehrere Fachrichtungen arbeiten gleichzeitig und abgestimmt zusammen, mindestens Bewegungstherapie und psychologische Verfahren, oft mit Ärzten und Ergotherapie. Meist als Programm über mehrere Wochen in einer Schmerzklinik oder Tagesklinik.", "Laut NVL bei Risikofaktoren für einen chronischen Verlauf ab etwa 6 Wochen prüfen, spätestens nach 12 Wochen anhaltender Beschwerden. NICE hat kombinierte körperlich-psychologische Programme im Juli 2026 gestrichen."]}, "nvl": {"t": "NVL Nicht-spezifischer Kreuzschmerz", "x": ["Nationale VersorgungsLeitlinie von Bundesärztekammer, KBV und AWMF, 2. Auflage 2017 (nvl-007). Gültig bis 30.12.2021, seitdem abgelaufen und in Überarbeitung; eine Neuauflage gibt es noch nicht. Bis dahin bleibt sie die deutsche Referenz, ihre Empfehlungen sind als Stand 2017 zu lesen.", "Kernpunkte: keine frühe Bildgebung ohne Warnzeichen, aktivieren statt schonen, Bewegungstherapie, psychosoziale Risikofaktoren früh erfassen."], "q": "AWMF-Register nvl-007, geprüft 22.11.2026"}, "nice": {"t": "NICE-Änderung Juli 2026", "x": ["NICE ist das britische Leitlinieninstitut, NG59 seine Leitlinie zu Kreuzschmerz und Ischias. Am 29. Juli 2026 hat NICE nach einer Überprüfung der Studienlage zwei Empfehlungen gestrichen: kognitive Verhaltenstherapie als Teil eines Pakets mit Übungen (1.2.13) und kombinierte körperlich-psychologische Programme bei anhaltenden Beschwerden (1.2.14).", "Bisher sollte ein hoher STarT-Back-Wert genau zu so einem intensiveren Programm führen. Der Fragebogen darf weiter das Risiko einschätzen, gibt bei NICE aber keinen festen Weg mehr vor. Manuelle Therapie bleibt nur zusammen mit Übungen eine Option.", "In Deutschland empfiehlt die (abgelaufene) NVL bei Risikofaktoren weiter eine multimodale Behandlung mit psychologischen Anteilen."], "q": "NICE NG59, Update 29.07.2026"}}}, {"id": "w47-ach", "titel": "Achillessehnen-Tendinopathie", "art": "kb", "kb": "SG04", "min": 11, "abschnitte": [{"t": "1. Was ist das eigentlich?", "b": [{"p": ["Eine belastungsbedingte Störung der Sehne mit Schmerz und eingeschränkter Belastbarkeit. Entzündungszellen spielen kaum eine Rolle, deshalb heißt es [[Tendinopathie und nicht Tendinitis|kontinuum]]. Typisch sind ein gestörter Kollagenaufbau, mehr Grundsubstanz und einsprossende Gefäße und Nerven. Auslöser ist meist eine Laststeigerung, die die Sehne nicht mitmachen konnte."]}, {"l": ["Häufig bei Läuferinnen und Läufern, aber gut ein Drittel der Betroffenen ist kaum sportlich aktiv.", "Risikofaktoren: plötzliche Steigerung von Umfang oder Tempo, Wechsel von Schuh oder Untergrund, höheres Alter, Übergewicht, Diabetes, Fettstoffwechselstörungen.", "Medikamente: [[Fluorchinolone|fluorchinolone]] (z. B. Ciprofloxacin) und systemisches Kortison erhöhen das Risiko für Tendinopathie und Ruptur."]}]}, {"t": "2. Zwei Formen", "b": [{"tab": [["Mittelabschnitt (midportion)", "2–6 cm über dem Ansatz, oft spindelförmig verdickt, eher bei Läufern"], ["Insertional", "direkt am Calcaneus, oft mit [[Haglund-Exostose|haglund]] oder Bursitis retrocalcanea, eher bei Älteren und Übergewicht"]], "p": ["Die Unterscheidung ist wichtig, weil die Übungen anders dosiert werden. Bei der insertionalen Form drückt tiefe Dorsalextension die Sehne gegen den Calcaneus und reizt sie zusätzlich."]}]}, {"t": "3. Befund und Abgrenzung", "b": [{"p": ["Typisch: Anlaufschmerz morgens und zu Beginn der Belastung, wird beim Warmlaufen besser und danach wieder schlechter. Druckschmerz an der Sehne, beim Mittelabschnitt mit tastbarer Verdickung. Der [[Arc Sign|arcsign]] (die Verdickung wandert bei Plantarflexion mit) spricht für die Sehne selbst."]}, {"tab": [["Achillessehnenruptur", "plötzlicher Knall, tastbare Lücke, [[Thompson-Test|thompson]] positiv: sofort ärztlich"], ["Plantaris-Beteiligung", "Schmerz eher medial am Mittelabschnitt"], ["Bursitis retrocalcanea", "Schmerz zwischen Sehne und Calcaneus, Druck vor der Sehne"], ["Posteriores Impingement", "Schmerz bei forcierter Plantarflexion, oft Tänzer oder Fußballer"], ["Systemisch", "beidseitig ohne Überlastung: an Spondyloarthritis oder Fettstoffwechselstörung denken"]], "merk": "Ein Knall mit Kraftverlust ist keine Tendinopathie. Thompson-Test machen."}]}, {"t": "4. Bildgebung", "b": [{"p": ["Die Diagnose ist klinisch. Ultraschall bestätigt sie und zeigt im Doppler oft [[eingesprossene Gefäße|neovask]]. Der Befund passt aber nicht immer zur Schmerzstärke, und eine Normalisierung im Bild ist kein Therapieziel."], "fig": [{"src": "fortbildung/bilder/2026-W47/ach-us.webp", "t": "Ultraschall längs.", "c": "Spindelförmige Verdickung im Mittelabschnitt, dunkler (hypoechogen), die Faserstruktur ist aufgelockert. Rechts der Calcaneus, darunter das Kager-Fettpolster."}]}, {"p": ["KI-erstellte Lehrbilder nach typischen Lehrbuchfällen, geprüft, keine echten Aufnahmen."]}]}, {"t": "5. Was hilft laut Studienlage?", "b": [{"l": ["Belastung ist die Therapie. Ruhe allein heilt keine Tendinopathie, die Sehne braucht dosierte, steigende Last über mindestens 12 Wochen.", "Exzentrisch nach Alfredson: 3 × 15 mit gestrecktem und 3 × 15 mit gebeugtem Knie, zweimal täglich, 12 Wochen.", "[[Heavy Slow Resistance|hsr]] (Beyer 2015): drei Einheiten pro Woche, langsam und schwer. Gleich gutes Ergebnis wie Alfredson, aber zufriedenere Patienten und weniger Zeitaufwand.", "[[Schmerz-Monitoring nach Silbernagel|silbernagel]]: Schmerz bis 5/10 während der Übung ist erlaubt, wenn er bis zum nächsten Morgen abgeklungen ist und nicht von Woche zu Woche zunimmt. Laufen darf so oft weitergehen.", "Insertional: Übungen auf ebenem Boden, keine Dorsalextension über die Neutralstellung (Jonsson 2008).", "Stoßwelle als Ergänzung, vor allem bei der insertionalen Form. Keine Kortisoninjektion in die Sehne."]}]}, {"t": "6. Für den Praxisalltag", "b": [{"l": ["[[VISA-A|visaa]] (0–100) zu Beginn und alle paar Wochen. Das macht Fortschritte sichtbar, wenn der Schmerz noch schwankt.", "Erwartungen klären: Die meisten bessern sich über 3–6 Monate, ein Teil braucht länger. Rückschläge nach Laststeigerungen sind normal.", "Wadenkraft messen, z. B. [[einbeiniges Fersenheben bis zur Erschöpfung|fersenheben]] im Seitenvergleich. Defizite bleiben oft auch nach Schmerzfreiheit.", "Rückkehr zum Laufen schrittweise, Umfang vor Tempo, Hügel und Sprünge zuletzt."]}]}], "quellen": ["Martin RL et al. Midportion Achilles Tendinopathy CPG Revision. JOSPT 2018", "Alfredson H et al. Am J Sports Med 1998", "Beyer R et al. Am J Sports Med 2015", "Silbernagel KG et al. Am J Sports Med 2007", "Jonsson P et al. Br J Sports Med 2008"], "fragen": [["Wo liegt die Mittelabschnitts-Tendinopathie der Achillessehne typischerweise?", ["Direkt am Calcaneus", "2 bis 6 cm über dem Ansatz", "Am Muskel-Sehnen-Übergang des Soleus", "In der Plantarfaszie"], 1, "Der Mittelabschnitt 2 bis 6 cm über dem Ansatz ist am schlechtesten durchblutet und am häufigsten betroffen."], ["Was zeigt der Ultraschall?", ["Komplette Ruptur mit Lücke", "Spindelförmige, hypoechogene Verdickung im Mittelabschnitt", "Normale Sehne", "Bursitis retrocalcanea"], 1, "Die Sehne ist spindelförmig verdickt und dunkler, die Fasern sind aufgelockert. Das ist das typische Bild der Mittelabschnitts-Tendinopathie.", "fortbildung/bilder/2026-W47/ach-us.webp"], ["Wie ist das Alfredson-Protokoll dosiert?", ["3 × 10 einmal pro Woche", "3 × 15 gestreckt und 3 × 15 gebeugt, zweimal täglich, 12 Wochen", "1 × 30 täglich für 4 Wochen", "Nur isometrisch 5 × 45 s"], 1, "Alfredson: 180 Wiederholungen pro Tag, mit gestrecktem und gebeugtem Knie, über 12 Wochen."], ["Was zeigte Beyer 2015 für Heavy Slow Resistance im Vergleich zu Alfredson?", ["Deutlich schlechteres Ergebnis", "Gleich gutes Ergebnis, Patienten zufriedener", "Nur bei Insertionstendinopathie wirksam", "Mehr Rupturen"], 1, "Beide Programme wirkten ähnlich gut. HSR braucht weniger Einheiten pro Woche, und die Patienten waren zufriedener."], ["Wie viel Schmerz ist nach dem Modell von Silbernagel während der Übungen erlaubt?", ["Gar keiner", "Bis 5 von 10, wenn er bis zum nächsten Morgen abklingt", "Bis 8 von 10", "Egal, Hauptsache weiter"], 1, "Bis 5/10 ist in Ordnung, solange der Schmerz bis zum nächsten Morgen abgeklungen ist und nicht von Woche zu Woche steigt."], ["Was ist bei der insertionalen Tendinopathie bei Exzentrik anders?", ["Mit tiefer Dorsalextension von der Stufe", "Auf ebenem Boden, nicht über die Neutralstellung", "Nur gebeugtes Knie", "Gar keine Exzentrik"], 1, "Tiefe Dorsalextension drückt die Sehne gegen den Calcaneus. Deshalb auf ebenem Boden üben (Jonsson 2008)."], ["Welcher Test spricht für eine Achillessehnenruptur?", ["Positiver Thompson-Test", "Positiver Lachman-Test", "Painful Arc", "Positiver Tinel"], 0, "Beim Thompson-Test drückt man die Wade. Bleibt die Plantarflexion aus, ist die Sehne durchgerissen."], ["Welche Medikamente erhöhen das Risiko für Achillessehnenschäden?", ["Betablocker", "Fluorchinolone und Kortison", "Protonenpumpenhemmer", "Paracetamol"], 1, "Fluorchinolon-Antibiotika wie Ciprofloxacin und systemisches Kortison erhöhen das Risiko für Tendinopathie und Ruptur."], ["Mit welchem Fragebogen misst man den Verlauf bei Achillessehnen-Tendinopathie?", ["VISA-A", "DASH", "Oswestry", "BCTQ"], 0, "VISA-A von 0 bis 100. Er erfasst Schmerz, Funktion und Sportfähigkeit."], ["Was gehört nicht zur Behandlung der Achillessehnen-Tendinopathie?", ["Dosiertes Lasttraining", "Stoßwelle als Ergänzung", "Kortisoninjektion in die Sehne", "Schmerz-Monitoring"], 2, "Kortison direkt in die Sehne schwächt das Gewebe und erhöht das Rupturrisiko."]], "info": {"kontinuum": {"t": "Kontinuum-Modell", "x": ["Cook und Purdam beschreiben die Tendinopathie als Kontinuum in drei Stufen: reaktive Tendinopathie nach plötzlicher Überlastung, gestörte Heilung (tendon dysrepair) und degenerative Tendinopathie mit dauerhaft verändertem Gewebe.", "Die Stufen können sich in beide Richtungen verschieben. Eine reaktive Sehne braucht eher Lastreduktion, eine degenerative eher gezielten Aufbau. Für die Dosierung ist das nützlicher als die Frage, ob eine Entzündung vorliegt."], "q": "Cook und Purdam, Br J Sports Med 2009"}, "fluorchinolone": {"t": "Fluorchinolone und Sehnen", "x": ["Sehnenschäden können schon 48 Stunden nach Beginn der Einnahme auftreten, aber auch erst Monate nach dem Absetzen. Besonders gefährdet sind Menschen über 60, Patienten mit Kortison, eingeschränkter Nierenfunktion oder nach Organtransplantation.", "Bei neuen Sehnenschmerzen unter oder nach Antibiotika nachfragen. Ist es ein Fluorchinolon, soll die Einnahme sofort ärztlich beendet werden: Patienten direkt zum Arzt schicken und die Sehne bis dahin nicht hoch belasten."], "q": "Rote-Hand-Brief Fluorchinolone, BfArM 2019"}, "haglund": {"t": "Haglund-Exostose", "x": ["Knöcherne Vorwölbung am hinteren oberen Rand des Fersenbeins. Sie drückt auf die Bursa retrocalcanea und den Sehnenansatz, oft verstärkt durch die harte Fersenkappe im Schuh.", "Treten Exostose, Bursitis und Ansatztendinopathie zusammen auf, spricht man vom Haglund-Syndrom. Weiche oder ausgeschnittene Fersenkappen und eine leichte Fersenerhöhung entlasten."]}, "arcsign": {"t": "Arc Sign", "x": ["Man tastet die Verdickung und lässt den Patienten den Fuß aktiv beugen und strecken. Wandert sie mit, liegt sie in der Sehne selbst. Bleibt sie an Ort und Stelle, spricht das für eine Reizung des Gleitgewebes um die Sehne (Paratendinopathie).", "Ergänzend gibt es den Royal-London-Hospital-Test: Der Druckschmerz an der verdickten Stelle wird in Dorsalextension deutlich geringer."], "q": "Maffulli et al., Clin J Sport Med 2003"}, "thompson": {"t": "Thompson-Test", "x": ["Bauchlage, die Füße hängen über die Liegenkante. Die Wade wird kräftig zusammengedrückt. Normal bewegt sich der Fuß in Plantarflexion, bei Ruptur bleibt er stehen. Immer mit der Gegenseite vergleichen.", "Sensitivität etwa 96 %, Spezifität etwa 93 %. Aktive Plantarflexion ist kein Ausschluss, weil die langen Zehenbeuger und die Peronäen sie ersetzen können."], "q": "Maffulli N, Am J Sports Med 1998"}, "neovask": {"t": "Neovaskularisation", "x": ["Die gesunde Achillessehne ist im Doppler fast gefäßfrei. Bei der Tendinopathie wachsen kleine Gefäße von vorn aus dem Kager-Fettpolster in die verdickte Sehne ein, begleitet von Nervenfasern.", "Diese Nerven gelten als möglicher Grund für den Schmerz. Unter erfolgreicher Trainingstherapie gehen die Gefäße manchmal zurück, oft aber auch nicht, ohne dass das den Verlauf verschlechtert."]}, "hsr": {"t": "Heavy Slow Resistance", "x": ["Drei Übungen für Soleus und Gastrocnemius, je 3 Sekunden hoch und 3 Sekunden runter, 3-mal pro Woche über 12 Wochen.", "Die Last steigt über 12 Wochen von 15RM auf 6RM: Woche 1 3 × 15, Woche 2–3 3 × 12, Woche 4–5 3 × 10, Woche 6–8 4 × 8, Woche 9–12 4 × 6.", "In der Studie mit 58 Patienten absolvierte die HSR-Gruppe 92 % der geplanten Einheiten, die Alfredson-Gruppe 78 %."], "q": "Beyer R et al., Am J Sports Med 2015"}, "silbernagel": {"t": "Schmerz-Monitoring-Modell", "x": ["In der Studie von Silbernagel 2007 trainierten 38 Patienten 12 Wochen bis 6 Monate nach einem Stufenprogramm. Die Hälfte lief und sprang weiter nach den Schmerzregeln, die andere Hälfte pausierte die ersten 6 Wochen.", "Beide Gruppen besserten sich gleich gut. Weiter Sport zu treiben, schadete also nicht, solange die Regeln eingehalten wurden. Steigerungen wie Sprünge erst, wenn Morgensteifigkeit und Schmerz stabil bleiben."], "q": "Silbernagel KG et al., Am J Sports Med 2007"}, "visaa": {"t": "VISA-A", "x": ["Fragebogen mit 8 Fragen zu Morgensteifigkeit, Schmerz beim Dehnen, Gehen, Treppensteigen, Fersenheben, Hüpfen und Sport. 100 Punkte bedeuten keine Beschwerden. Es gibt eine geprüfte deutsche Fassung (VISA-A-G).", "Als kleinste klinisch relevante Veränderung (MCID) fand eine Studie nach 12 Wochen 14 Punkte."], "q": "JOSPT 2021"}, "fersenheben": {"t": "Heel-Rise-Test", "x": ["Einbeinig auf einem 10°-Keil stehen, Fingerspitzen locker an der Wand. Im Takt eines Metronoms (60 Schläge pro Minute, also 30 Wiederholungen pro Minute) so hoch wie möglich auf die Zehen.", "Abbruch, wenn der Patient den Takt nicht mehr hält, das Knie beugt oder die Höhe deutlich nachlässt. Notiert werden Wiederholungen und Seitenvergleich in Prozent, wer kann, misst auch Höhe oder Gesamtarbeit."]}}}, {"id": "w47-kts", "titel": "Karpaltunnelsyndrom: neue Leitlinie 2026", "art": "neu", "kb": "HG02", "min": 12, "abschnitte": [{"t": "1. Was ist das eigentlich?", "b": [{"p": ["Kompression des N. medianus im Karpaltunnel unter dem Retinaculum flexorum. Das häufigste Engpasssyndrom eines peripheren Nervs. Frauen sind deutlich häufiger betroffen, der Gipfel liegt im mittleren Lebensalter."]}, {"l": ["Risikofaktoren: Diabetes, Schilddrüsenunterfunktion, Schwangerschaft, Übergewicht, rheumatoide Arthritis, Dialyse.", "Beruflich: kraftvolles, wiederholtes Greifen und Vibration. Laut der Leitlinie 2026 haben Beschäftigte in körperlich fordernden Berufen deutlich häufiger ein KTS als Büroangestellte.", "Meist schleichender Beginn. [[Akute Verläufe|aktkts]] nach Trauma oder akuter Entzündung sind selten, aber dringlich."]}]}, {"t": "2. Typische Symptome", "b": [{"l": ["Kribbeln und Taubheit an Daumen, Zeige-, Mittelfinger und der radialen Hälfte des Ringfingers.", "Nachts und morgens am stärksten. Viele schütteln die Hand aus (Flick-Zeichen).", "Später Ungeschicklichkeit, Dinge fallen aus der Hand, Schwäche beim Pinzettengriff.", "Spätzeichen: [[Atrophie der Thenarmuskulatur|thenar]] (M. abductor pollicis brevis)."], "merk": "Ist der kleine Finger mit betroffen, eher an [[N. ulnaris|ulnaris]] oder eine zervikale Wurzel denken."}]}, {"t": "3. Diagnostik nach der Leitlinie 2026", "b": [{"p": ["Die aktualisierte Leitlinie von APTA Orthopedics und APTA Hand and Upper Extremity (Erickson et al., JOSPT 2026) ersetzt die Fassung von 2019. Sie bezieht sich auf die konservative Versorgung."]}, {"tab": [["Handdiagramm (Katz)", "Grad B"], ["Phalen, Tinel, Durkan", "je Grad B, aber keiner reicht allein"], ["[[CTS-6|cts6]]", "Grad B, empfohlene Kombination aus Anamnese und Befund"], ["[[Semmes-Weinstein-Monofilamente|monofil]]", "Grad A"], ["Statische Zwei-Punkte-Diskrimination", "Grad B"], ["Elektrophysiologie, Ultraschall", "nur wenn das Ergebnis die Behandlung ändert, z. B. für eine OP-Überweisung"]]}, {"tab": [["Zervikale Radikulopathie C6/C7", "Nacken- oder Armschmerz, Reflexe, Spurling, ULTT"], ["Pronator-teres-Syndrom", "Beschwerden am Unterarm, Sensibilität auch am Thenar, nachts weniger"], ["Polyneuropathie", "beidseitig, strumpf- oder handschuhförmig, Diabetes"], ["Rhizarthrose", "Schmerz am Daumensattelgelenk, Grind-Test, kein Kribbeln"]]}]}, {"t": "4. Bildgebung und Messen", "b": [{"p": ["Ultraschall zeigt einen vergrößerten N. medianus am Tunneleingang und Varianten wie einen geteilten Nerv. Eine Querschnittsfläche um 10 mm² und mehr spricht für ein KTS, die Grenzwerte schwanken je nach Studie."], "fig": [{"src": "fortbildung/bilder/2026-W47/kts-us.webp", "t": "Ultraschall quer am Tunneleingang.", "c": "Vergrößerter, dunkler N. medianus (gestrichelt) unter dem Retinaculum, darunter die Beugesehnen."}], "l": ["Verlauf: [[BCTQ-Symptomskala|bctq]] und [[(Quick)DASH|quickdash]] zu Beginn und mindestens einmal im Verlauf (Grad B).", "Lateraler Pinchgriff nicht zur Verlaufskontrolle (Grad A dagegen), Griffkraft nicht in den ersten drei Monaten nach OP (Grad B dagegen)."]}, {"p": ["KI-erstellte Lehrbilder nach typischen Lehrbuchfällen, geprüft, keine echten Aufnahmen."]}]}, {"t": "5. Was hilft laut Studienlage?", "b": [{"tab": [["Nachtschiene in Neutralstellung", "Grad B, kurz- und mittelfristig bei leichtem bis mittlerem KTS, auch bis zur OP"], ["Reicht die Nacht nicht", "Tagsüber oder dauerhaft tragen, Position anpassen, MCP mit ruhigstellen (Grad C)"], ["Manuelle Therapie (HWS, obere Extremität)", "Grad C, kurzfristig"], ["Schiene plus Dehnprogramm", "Grad C, ohne Thenaratrophie und mit normaler Zwei-Punkte-Diskrimination"], ["[[Nervengleiten|nervengleiten]]", "keine Empfehlung, Studienlage widersprüchlich"], ["Kinesiotape, Laser, Stoßwelle (radial)", "je Grad C, kurzfristig"], ["[[Kortison-Iontophorese oder -Phonophorese|iontophorese]]", "Grad A dagegen"], ["Magnete", "Grad B dagegen"]], "merk": "Thenaratrophie, zunehmende Taubheit oder Schwäche gehören zur ärztlichen Abklärung, oft in Richtung OP."}]}, {"t": "6. Was neu ist gegenüber 2019", "b": [{"l": ["CTS-6 als empfohlene Testkombination.", "Monofilamente auf Grad A hochgestuft.", "Stoßwelle und Kinesiotape neu als Grad-C-Optionen.", "Neurodynamik nicht mehr routinemäßig, weil die Studien sich widersprechen.", "Genauere Angaben zur Schiene: Position, Tragezeit, Anpassungen."]}]}, {"t": "7. Für den Praxisalltag", "b": [{"l": ["Handdiagramm ausfüllen lassen und Monofilament-Test dokumentieren, das ist schnell und gut belegt.", "Schiene konkret erklären: nachts, Handgelenk gerade, mindestens einige Wochen. Viele tragen sie zu kurz.", "Ergonomie besprechen: Handgelenk beim Greifen und Tippen möglichst neutral, Pausen bei Vibration.", "Bei Schwangeren: Schiene und Aufklärung, nach der Geburt neu beurteilen (Grad C).", "Bei fehlender Besserung nach 6–8 Wochen oder Ausfallzeichen zurück zum Arzt."]}]}], "quellen": ["Erickson M et al. Carpal Tunnel Syndrome: Clinical Practice Guideline Revision 2026. JOSPT", "Zusammenfassung: physiotutors.com, KTS-Leitlinie 2026", "Graham B et al. CTS-6. J Hand Surg 2006"], "fragen": [["Welche Finger sind beim KTS typischerweise betroffen?", ["Kleiner Finger und ulnarer Ringfinger", "Daumen, Zeige-, Mittelfinger und radialer Ringfinger", "Nur der Daumen", "Alle fünf Finger gleich"], 1, "Das ist das sensible Gebiet des N. medianus. Ist der kleine Finger dabei, eher an den N. ulnaris oder eine Wurzel denken."], ["Welche Aussage zu Phalen, Tinel und Durkan stimmt laut Leitlinie 2026?", ["Jeder Test allein sichert die Diagnose", "Keiner reicht allein, um ein KTS zu bestätigen oder auszuschließen", "Nur Tinel ist brauchbar", "Die Tests werden nicht mehr empfohlen"], 1, "Alle drei haben Grad B, aber keiner ist allein genau genug. Deshalb empfiehlt die Leitlinie die CTS-6-Kombination."], ["Welche Untersuchung der Sensibilität hat in der Leitlinie 2026 Grad A?", ["Zwei-Punkte-Diskrimination", "Semmes-Weinstein-Monofilamente", "Spitz-stumpf", "Vibration mit Stimmgabel"], 1, "Monofilamente wurden auf Grad A hochgestuft. Die statische Zwei-Punkte-Diskrimination hat Grad B."], ["Was zeigt der Ultraschall?", ["Normaler N. medianus", "Vergrößerter, hypoechogener N. medianus am Tunneleingang", "Ganglion", "Sehnenscheidenentzündung"], 1, "Der Nerv ist vergrößert und dunkel. Eine Querschnittsfläche um 10 mm² und mehr spricht für ein KTS.", "fortbildung/bilder/2026-W47/kts-us.webp"], ["Welche Schiene empfiehlt die Leitlinie?", ["Handgelenk in 30° Extension tagsüber", "Nachtschiene mit Handgelenk nahe der Neutralstellung", "Daumenschiene", "Keine Schiene"], 1, "Grad B: Nachtschiene in Neutralstellung, kurz- und mittelfristig wirksam bei leichtem bis mittlerem KTS."], ["Was sagt die Leitlinie 2026 zu Nervengleitübungen?", ["Grad A empfohlen", "Keine klare Empfehlung, die Studienlage ist widersprüchlich", "Grad A dagegen", "Nur nach OP"], 1, "Isoliertes Sehnen- und Nervengleiten bekommt keine Empfehlung, weil sich die Studien widersprechen."], ["Wovon rät die Leitlinie mit Grad A ab?", ["Nachtschiene", "Kortison-Iontophorese und -Phonophorese", "Manuelle Therapie", "Edukation"], 1, "Für Kortison über die Haut fehlt der Nachweis, dass es ankommt und wirkt. Deshalb Grad A dagegen."], ["Welche Messgrößen empfiehlt die Leitlinie für den Verlauf?", ["Lateraler Pinchgriff", "BCTQ-Symptomskala und (Quick)DASH", "Nur Griffkraft", "Röntgen"], 1, "BCTQ-SSS und DASH bzw. QuickDASH mit Grad B. Vom lateralen Pinchgriff rät sie mit Grad A ab."], ["Was ist ein Grund für eine ärztliche Abklärung mit Blick auf eine OP?", ["Nächtliches Kribbeln", "Thenaratrophie", "Positiver Phalen", "Ausschütteln der Hand"], 1, "Thenaratrophie, zunehmende Taubheit oder Schwäche zeigen eine fortgeschrittene Kompression an."], ["Welche Behandlung ist neu als Grad-C-Option dazugekommen?", ["Magnetfeldtherapie", "Radiale Stoßwelle", "Kortison-Phonophorese", "Bettruhe"], 1, "Stoßwelle und Kinesiotape sind neu mit Grad C. Bei der Stoßwelle wird die radiale Form bevorzugt."]], "info": {"aktkts": {"t": "Akutes Karpaltunnelsyndrom", "x": ["Entsteht innerhalb von Stunden, meist nach distaler Radiusfraktur, Luxation, Blutung (z. B. unter Gerinnungshemmern) oder Infektion. Der Druck im Tunnel steigt schnell.", "Zeichen: rasch zunehmende Taubheit im Medianusgebiet, starker, kaum lindernder Schmerz, Schwellung. Hier hilft keine Schiene, sondern nur die rasche operative Entlastung. Deshalb noch am selben Tag ärztlich vorstellen."]}, "thenar": {"t": "Thenaratrophie prüfen", "x": ["Im Seitenvergleich sieht man eine Abflachung des Daumenballens, am besten von radial betrachtet.", "Kraft des M. abductor pollicis brevis testen: Daumen senkrecht zur Handfläche nach vorn abspreizen lassen, gegen Widerstand. Andere Daumenmuskeln werden teils vom N. ulnaris versorgt, dieser Test isoliert den Medianus am besten.", "Atrophie spricht für fortgeschrittenen Axonschaden, die Erholung nach OP ist dann oft unvollständig."]}, "ulnaris": {"t": "Abgrenzung N. ulnaris", "x": ["Sensibel: Kleinfinger und ulnare Hälfte des Ringfingers. Engstellen sind der Sulcus ulnaris am Ellenbogen (häufig, Kribbeln bei langer Beugung) und die Guyon-Loge am Handgelenk.", "Motorisch: Atrophie am Spatium interosseum I und Hypothenar, positives Froment-Zeichen. Beim Sulcus-Syndrom ist meist auch der ulnare Handrücken taub, bei der Guyon-Loge nicht."]}, "cts6": {"t": "CTS-6", "x": ["Sechs Merkmale mit Punkten: Taubheit vor allem im Medianusgebiet 3,5, nächtliches Erwachen durch Taubheit 4, Thenaratrophie oder -schwäche 5, Phalen positiv 5, Zwei-Punkte-Diskrimination über 5 mm 4,5, Tinel positiv 4.", "Summe 0 bis 26. Ab 12 Punkten liegt die Wahrscheinlichkeit für ein KTS bei über 80 %, die Elektrophysiologie bringt dann meist keine zusätzliche Sicherheit. Unter 5 Punkten ist ein KTS unwahrscheinlich, dazwischen ist das Ergebnis unklar."], "q": "Graham B et al., J Hand Surg 2006"}, "monofil": {"t": "Semmes-Weinstein-Monofilamente", "x": ["Nylonfäden mit genormter Biegekraft werden senkrecht auf die Fingerkuppe gedrückt, bis sie sich biegen. Der Patient hat die Augen zu und sagt, welcher Finger berührt wird.", "Der Faden 2.83 gilt als Grenze der normalen Berührungsempfindung. Wird er im Medianusgebiet nicht sicher gespürt, ist der Test auffällig. 3.61 steht für verminderte Berührung, ab 4.31 ist die Schutzsensibilität vermindert."]}, "bctq": {"t": "Boston Carpal Tunnel Questionnaire", "x": ["Zwei Teile: Symptomskala mit 11 Fragen und Funktionsskala mit 8 Fragen, jede Antwort 1 bis 5. Ausgewertet wird der Mittelwert je Skala, höher heißt schlechter.", "Für die Symptomskala gilt eine Änderung von etwa 1 Punkt als klinisch relevant. Für die Funktionsskala ist kein fester Wert etabliert."]}, "quickdash": {"t": "DASH und QuickDASH", "x": ["Fragebogen zu Beschwerden und Alltagsfunktion des ganzen Arms, nicht KTS-spezifisch. Der DASH hat 30 Fragen, die Kurzform QuickDASH 11.", "Ergebnis 0 bis 100, höher heißt mehr Einschränkung. Gut, um den Arm als Ganzes im Verlauf zu erfassen, neben der KTS-spezifischen BCTQ."]}, "nervengleiten": {"t": "Nervengleiten", "x": ["Übungen, bei denen Handgelenk, Finger, Ellenbogen und Kopf so kombiniert werden, dass der N. medianus im Gewebe hin und her gleitet, ohne stark gedehnt zu werden (Sliding). Davon abzugrenzen ist Tensioning, das den Nerv auf Spannung bringt.", "Die Leitlinie spricht weder dafür noch dagegen eine Empfehlung aus. Als Ergänzung bei gutem Ansprechen bleibt es möglich, aber nicht als Standard."]}, "iontophorese": {"t": "Ionto- und Phonophorese", "x": ["Bei der Iontophorese wird ein Medikament mit Gleichstrom durch die Haut gebracht, bei der Phonophorese mit Ultraschall.", "Für Kortison auf diesem Weg spricht sich die Leitlinie klar aus. Eine Kortisoninjektion durch den Arzt ist etwas anderes und wird hier nicht bewertet."]}}}, {"id": "w47-ga", "titel": "Gonarthrose", "art": "kb", "kb": "KN01", "min": 11, "abschnitte": [{"t": "1. Was ist das eigentlich?", "b": [{"p": ["Eine Erkrankung des ganzen Gelenks: Knorpel, subchondraler Knochen, Synovia, Menisken, Bänder und Muskulatur sind beteiligt. Es ist kein reiner Verschleiß, sondern ein Wechselspiel aus Belastung, Entzündung und Reparatur."]}, {"l": ["Die häufigste Gelenkerkrankung, mit dem Alter steigend, Frauen etwas häufiger.", "Risikofaktoren: Alter, Übergewicht, frühere Knieverletzung (z. B. VKB- oder Meniskusriss), Achsfehlstellung, schwache Quadrizepsmuskulatur, familiäre Belastung.", "Am häufigsten betroffen ist das [[mediale Kompartiment|medialkomp]], oft mit Varusstellung."]}]}, {"t": "2. Klinische Diagnose", "b": [{"p": ["Ab etwa 45 Jahren mit belastungsabhängigem Knieschmerz und höchstens 30 Minuten Morgensteifigkeit kann man die Diagnose klinisch stellen, ohne Bildgebung (NICE)."], "l": ["Anlaufschmerz, Belastungsschmerz, später auch Ruheschmerz.", "Krepitation, knöcherne Verdickung, eingeschränkte Flexion, später Streckdefizit.", "Phasen mit Reizerguss (aktivierte Arthrose) wechseln mit ruhigeren Phasen."], "merk": "[[Röntgenbefund und Schmerz passen oft schlecht zusammen|roentgenschmerz]]. Behandelt wird der Patient, nicht das Bild."}]}, {"t": "3. Befund und Abgrenzung", "b": [{"tab": [["Rheumatoide Arthritis", "mehrere Gelenke, symmetrisch, lange Morgensteifigkeit, Schwellung"], ["Gicht oder Pseudogicht", "akuter, heißer, stark geschwollener Gelenkbefall"], ["Septische Arthritis", "Fieber, akuter Erguss, starker Schmerz: Notfall"], ["Meniskusläsion", "jüngere Patienten, Blockade, Gelenkspaltschmerz nach Trauma"], ["Übertragener Hüftschmerz", "Koxarthrose kann ins Knie ausstrahlen, Hüfte mituntersuchen"]], "l": ["Messen: Beweglichkeit, Quadrizepskraft, [[30-Sekunden-Aufstehtest, 40-m-Gehtest|oarsitests]], [[KOOS oder WOMAC|koos]]."]}]}, {"t": "4. Röntgen und Kellgren-Lawrence", "b": [{"tab": [["Grad 1", "fragliche Osteophyten"], ["[[Grad 2|klgrad2]]", "sichere Osteophyten, Gelenkspalt kaum verändert"], ["Grad 3", "mehrere Osteophyten, deutliche Verschmälerung, Sklerose"], ["Grad 4", "große Osteophyten, aufgehobener Gelenkspalt, Deformität"]], "fig": [{"src": "fortbildung/bilder/2026-W47/ga-roe.webp", "t": "Röntgen a.p. im Stehen.", "c": "Medialer Gelenkspalt deutlich verschmälert, Osteophyten an den medialen Kanten, subchondrale Sklerose, leichte Varusstellung: Kellgren-Lawrence Grad 3."}], "p": ["[[Röntgen im Stehen|rosenberg]], weil der Gelenkspalt sonst breiter wirkt."]}, {"p": ["KI-erstellte Lehrbilder nach typischen Lehrbuchfällen, geprüft, keine echten Aufnahmen."]}]}, {"t": "5. Was hilft laut Studienlage?", "b": [{"l": ["Bewegungstherapie (Kraft, Ausdauer, neuromuskulär) ist die Grundlage, unabhängig vom Röntgengrad.", "Edukation und Selbstmanagement, zum Beispiel strukturiert wie im [[GLA:D-Programm|glad]].", "Gewicht reduzieren bei Übergewicht: schon etwa 5–10 % weniger Körpergewicht bessern Schmerz und Funktion spürbar.", "Hilfsmittel nach Bedarf, z. B. Gehstock auf der Gegenseite.", "[[Arthroskopische Lavage oder Débridement|arthroskopie]] bei Arthrose wird nicht empfohlen.", "Gut belegt sind Programme über 8–12 Wochen mit 2–3 Einheiten pro Woche."], "merk": "Übungen wirken bei leichter wie schwerer Arthrose. Auch vor einer Endoprothese lohnt sich Training."}]}, {"t": "6. Für den Praxisalltag", "b": [{"l": ["[[Leichter Schmerz während der Übung|schmerzmonitor]] ist in Ordnung, wenn er nach dem Training nicht deutlich zunimmt und bis zum nächsten Tag abklingt. Das nimmt vielen die Angst vor Belastung.", "„Abgenutzt“ und „Knochen auf Knochen“ vermeiden. Besser: Das Knie reagiert auf Training und Last.", "Bei aktivierter Arthrose mit Erguss Dosis senken, aber in Bewegung bleiben.", "Ein Heimprogramm mit 3–4 Übungen ist besser als eines mit zehn, die nicht gemacht werden."]}]}], "quellen": ["S3-Leitlinie Gonarthrose (AWMF), aktuelle Fassung", "NICE NG226 Osteoarthritis in over 16s, 2022", "Kellgren JH, Lawrence JS. Ann Rheum Dis 1957", "Skou ST, Roos EM. GLA:D. BMC Musculoskelet Disord 2017", "Bannuru RR et al. OARSI Guidelines. Osteoarthritis Cartilage 2019"], "fragen": [["Wann kann die Gonarthrose laut NICE klinisch ohne Bildgebung diagnostiziert werden?", ["Bei jedem Knieschmerz", "Ab ca. 45 Jahren, belastungsabhängiger Schmerz, Morgensteifigkeit höchstens 30 min", "Nur bei Erguss", "Nur bei Varusstellung"], 1, "Diese drei Kriterien reichen. Bildgebung braucht man nur bei untypischem Bild oder Verdacht auf etwas anderes."], ["Was zeigt das Röntgenbild?", ["Normales Kniegelenk", "Tibiakopffraktur", "Gonarthrose medial, Kellgren-Lawrence Grad 3", "Rheumatoide Arthritis mit gleichmäßiger Verschmälerung"], 2, "Der mediale Gelenkspalt ist deutlich verschmälert, dazu Osteophyten und Sklerose. Das entspricht Grad 3.", "fortbildung/bilder/2026-W47/ga-roe.webp"], ["Warum wird das Knie im Stehen geröntgt?", ["Wegen der besseren Bildqualität", "Weil der Gelenkspalt unter Last realistischer aussieht", "Wegen der geringeren Strahlendosis", "Das ist egal"], 1, "Ohne Last wirkt der Gelenkspalt breiter. Im Stehen sieht man die tatsächliche Verschmälerung."], ["Was kennzeichnet Kellgren-Lawrence Grad 2?", ["Fragliche Osteophyten", "Sichere Osteophyten, Gelenkspalt kaum verändert", "Aufgehobener Gelenkspalt", "Deformität"], 1, "Grad 2: sichere Osteophyten, der Gelenkspalt ist höchstens fraglich verschmälert."], ["Wie hängen Röntgengrad und Schmerz zusammen?", ["Eng: Je höher der Grad, desto mehr Schmerz", "Oft nur lose", "Gar nicht, Röntgen ist unnötig", "Nur bei Grad 4"], 1, "Viele mit deutlichen Röntgenzeichen haben wenig Schmerz, und umgekehrt. Therapie richtet sich nach Beschwerden und Funktion."], ["Was ist die Basis der Behandlung bei Gonarthrose?", ["Arthroskopische Lavage", "Bewegungstherapie mit Edukation", "Bettruhe bei Schmerz", "Nur Schmerzmittel"], 1, "Training und Edukation sind die Grundlage, bei jedem Schweregrad."], ["Ab welcher Gewichtsabnahme bessern sich Schmerz und Funktion bei Übergewicht spürbar?", ["Ab etwa 1 %", "Ab etwa 5 bis 10 %", "Erst ab 25 %", "Gewicht spielt keine Rolle"], 1, "Schon 5 bis 10 % weniger Körpergewicht entlasten das Knie spürbar."], ["Was wird bei Gonarthrose nicht empfohlen?", ["Krafttraining", "Arthroskopische Lavage oder Débridement", "Gehstock bei Bedarf", "Gewichtsreduktion"], 1, "Arthroskopische Eingriffe bringen bei Arthrose keinen Vorteil gegenüber konservativer Therapie."], ["Welche Dosierung ist für Übungsprogramme bei Gonarthrose gut belegt?", ["Einmal pro Monat", "2 bis 3 Einheiten pro Woche über 8 bis 12 Wochen", "Täglich 2 Stunden", "Nur eine Einheit"], 1, "Programme dieser Länge und Häufigkeit sind in den meisten Studien wirksam."], ["Auf welcher Seite trägt der Patient bei Gonarthrose rechts den Gehstock?", ["Rechts", "Links", "Egal", "Gar keinen"], 1, "Den Stock trägt man auf der Gegenseite, also links. So entlastet er das rechte Knie im Gangbild am besten."]], "info": {"medialkomp": {"t": "Warum meist medial?", "x": ["Beim Gehen läuft die Kraftlinie des Beins medial am Kniezentrum vorbei. Dadurch entsteht ein Adduktionsmoment, und das mediale Kompartiment trägt schon beim Gesunden den größeren Teil der Last.", "Eine Varusstellung verstärkt das, eine Valgusstellung verschiebt die Last nach lateral. Deshalb setzen Ansätze wie Gehstock auf der Gegenseite, Gewichtsabnahme oder Umstellungsosteotomie genau an dieser Lastverteilung an."]}, "roentgenschmerz": {"t": "Bild und Beschwerden", "x": ["Eine systematische Übersicht fand je nach Studie: Von Menschen mit Knieschmerz hatten 15–76 % eine Arthrose im Röntgen. Von denen mit Röntgenarthrose hatten 15–81 % Schmerzen.", "Schmerz hängt auch von Synovitis, Muskelkraft, Schlaf, Stimmung und Überzeugungen ab. Ein schlimmes Bild schließt gute Funktion nicht aus und umgekehrt."], "q": "Bedson J, Croft PR, BMC Musculoskelet Disord 2008"}, "oarsitests": {"t": "OARSI-Funktionstests", "x": ["Die OARSI empfiehlt bei Knie- und Hüftarthrose als Mindestset drei Leistungstests: 30-Sekunden-Aufstehtest (Zahl der Aufstehvorgänge vom Stuhl ohne Armhilfe), 40-m-Gehtest (4 × 10 m zügig, Zeit) und einen Treppentest.", "Ergänzend je nach Fragestellung Timed Up and Go und 6-Minuten-Gehtest. Die Tests zeigen Veränderungen oft greifbarer als Fragebögen."], "q": "Dobson F et al., Osteoarthritis Cartilage 2013"}, "koos": {"t": "KOOS und WOMAC", "x": ["Der WOMAC fragt Schmerz, Steifigkeit und Funktion ab, insgesamt 24 Fragen. Hohe Werte bedeuten mehr Beschwerden.", "Der KOOS hat 42 Fragen in fünf Skalen: Schmerz, Symptome, Alltag, Sport und Freizeit, Lebensqualität. Jede Skala läuft von 0 bis 100, hier ist 100 der beste Wert. Der WOMAC steckt vollständig im KOOS und lässt sich daraus berechnen."], "q": "Roos EM, Lohmander LS, Health Qual Life Outcomes 2003"}, "klgrad2": {"t": "Ab wann Arthrose im Röntgen?", "x": ["In Studien gilt meist Kellgren-Lawrence Grad 2 oder höher als sichere Röntgenarthrose. Ausschlaggebend ist der sichere Osteophyt.", "Die Einteilung beschreibt nur das Bild. Über Schmerz, Funktion und Therapie sagt der Grad wenig."]}, "rosenberg": {"t": "Belastete Aufnahme und Rosenberg", "x": ["Unter Körpergewicht zeigt sich, wie weit der Knorpel tatsächlich zusammengedrückt wird. Im Liegen wird die Verschmälerung unterschätzt.", "Die Rosenberg-Aufnahme wird im Stehen mit etwa 45° Kniebeugung von hinten nach vorn gemacht. Sie zeigt den hinteren Anteil der Kondylen, wo der Knorpel oft zuerst schwindet, und erkennt eine Spaltverschmälerung früher."]}, "glad": {"t": "GLA:D", "x": ["Good Life with osteoArthritis in Denmark: ein Programm aus Dänemark für Knie- und Hüftarthrose. Es besteht aus zwei Schulungseinheiten und zwölf betreuten Trainingseinheiten, zweimal pro Woche über sechs Wochen.", "Das Training ist neuromuskulär: Beinachse, Kontrolle und Kraft in funktionellen Positionen. Die Ergebnisse werden in einem Register erfasst."], "q": "Skou ST, Roos EM, BMC Musculoskelet Disord 2017"}, "arthroskopie": {"t": "Arthroskopie bei Arthrose", "x": ["Gelenkspülung und Glätten des Knorpels waren in Scheinoperations- und Vergleichsstudien nicht besser als Placebo oder Physiotherapie.", "Der G-BA hat am 27.11.2015 beschlossen, dass solche Eingriffe bei Gonarthrose nicht mehr zulasten der Krankenkassen erbracht werden. Ausnahmen: Trauma, akute Gelenkblockade oder eine eigene Meniskus-Indikation, bei der die Arthrose nur Begleiterkrankung ist."], "q": "G-BA, Beschluss 27.11.2015"}, "schmerzmonitor": {"t": "Schmerz-Monitoring-Modell", "x": ["Ursprünglich von Thomeé für vorderen Knieschmerz beschrieben, heute bei Arthrose und Tendinopathien verbreitet. Der Patient bewertet seinen Schmerz selbst auf einer Skala von 0 bis 10.", "Üblich: während der Übung bis etwa 5 erlaubt, am nächsten Morgen wieder auf Ausgangsniveau, und von Woche zu Woche keine Zunahme. Wird eine Regel verletzt, die Dosis senken statt aufhören."]}}}, {"id": "w47-gh", "titel": "Gewebeheilung: wann ist was belastbar?", "art": "grund", "min": 11, "abschnitte": [{"t": "Wie fest wird es wieder?", "b": [{"bars": [["Knochen", 100, "baut sich vollständig um"], ["Haut und Narbe", 75, "höchstens 70–80 % nach 1 Jahr"], ["Band", 60, "oft 50–70 % nach 1 Jahr"]], "p": ["Festigkeit des geheilten Gewebes im Vergleich zu vorher, grob nach Studienlage. Knochen ist das einzige Gewebe, das wirklich wieder wie neu wird."]}]}, {"t": "1. Was ist das eigentlich?", "b": [{"p": ["Fast jedes Gewebe heilt nach demselben Grundmuster: erst räumt eine Entzündung auf, dann wird neues, noch ungeordnetes Gewebe gebildet, dann wird es fester und ordnet sich nach der Belastung aus. Die Phasen gehen fließend ineinander über, und die Zeiten sind Richtwerte, keine Stoppuhr.", "Der Unterschied zwischen den Geweben liegt vor allem in der Durchblutung und im Stoffwechsel. Muskel und Haut sind gut versorgt und heilen schnell. Sehne, Band und Knorpel sind schlecht versorgt und brauchen Monate bis Jahre."]}, {"l": ["Kollagen Typ III kommt zuerst. Es ist dünn, ungeordnet und wenig belastbar.", "Kollagen Typ I ersetzt es nach und nach. Es ist dick, parallel ausgerichtet und trägt Zug.", "Die Ausrichtung entsteht durch Belastung ([[Mechanotransduktion|mechano]]). Ohne Reiz bleibt die Narbe ungeordnet und schwach."], "merk": "Schmerzfrei heißt nicht belastbar. Die Festigkeit hinkt dem Schmerz um Wochen bis Monate hinterher."}]}, {"t": "2. Die vier Phasen", "b": [{"tab": [["Entzündung", "Tag 0 bis etwa 5, bei Sehne und Kreuzband-Plastik bis 1–2 Wochen. Blutung, Gerinnsel, Abräumen. Schwellung, Wärme, Ruheschmerz."], ["Proliferation", "Etwa ab Tag 3 bis Woche 3–6. Neues Gewebe, Kollagen Typ III, viele Gefäße. Das Gewebe ist zerbrechlich."], ["Konsolidierung", "Etwa Woche 6 bis 10–12. Typ I nimmt zu, das Gewebe wird fester und ordnet sich."], ["Remodelling", "Ab etwa Woche 10–12 bis 1–2 Jahre. Umbau nach Belastung, die Festigkeit steigt langsam weiter."]], "p": ["Beim Knochen heißen die mittleren Phasen [[weicher und harter Kallus|kallus]]. Beim Muskel ist die Reparatur schon nach etwa 3 Wochen weit fortgeschritten."]}]}, {"t": "3. Die Gewebe im Vergleich", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W47/gh-zeitleiste.webp", "t": "Heilungsphasen im Vergleich, Zeitachse logarithmisch.", "c": "Jede Zeile zeigt ein Gewebe von Tag 1 bis 2 Jahre. Die Farben sind die Phasen, der schwarze Strich darunter zeigt, wann volle Belastung oder Sport realistisch wird. Muskel und Band sind nach Wochen wieder belastbar, Sehne, Meniskus und Kreuzband-Plastik erst nach Monaten. Schematische Darstellung aus Studien und Leitlinien, keine echten Messdaten."}]}, {"tab": [["Muskel", "Kurz schonen (unter 1 Woche), dann schmerzgeleitet. Rückkehr 1–6 Wochen, mit Sehnenbeteiligung 2–3 Monate und mehr."], ["Band", "[[Grad I|bandgrad]] 1–3 Wochen, Grad II 3–6, Grad III 6–12 Wochen. Am Sprunggelenk funktionell mit Orthese."], ["Sehne (Ruptur, Naht)", "Zuglast ab Woche 6–8 steigern, Sprung und Sprint ab Monat 4–6, Sport nach 6–12 Monaten."], ["Sehnen-Knochen-Übergang", "Bis Woche 6 geschützt, Kräftigung ab etwa Woche 12, Überkopf und Sport nach 6–12 Monaten."], ["Kreuzband-Plastik", "[[Transplantat am schwächsten|ligamentisierung]] in Woche 6–8. Laufen ab etwa Monat 3, Pivot-Sport frühestens nach 9 Monaten."], ["Knochen", "Spongiös oft nach etwa 6 Wochen stabil, kortikaler Schaft nach 10–12 Wochen. Freigabe vom Arzt."], ["Meniskusnaht", "Tiefe Beugung unter Last 3–4 Monate meiden, Laufen nach 3–4, Pivot-Sport nach 4–6 Monaten."], ["Peripherer Nerv", "Axone wachsen etwa 1 mm pro Tag."]], "merk": "Je schlechter durchblutet, desto länger: Muskel heilt in Wochen, Sehne und Band in Monaten, Knorpel kaum."}]}, {"t": "4. Was die Heilung bremst", "b": [{"tab": [["Rauchen", "Schlechtere Durchblutung, mehr [[Pseudarthrosen|pseudarthrose]] und Rerupturen"], ["Diabetes mellitus", "Langsamere Wund-, Sehnen- und Knochenheilung"], ["Alter", "Weniger Zellen, langsamerer Umbau"], ["Große Verletzung", "Großer Rotatorenmanschettenriss, Riss mit Sehnenbeteiligung im Muskel, Meniskusriss in der weißen Zone"], ["Schlechte Lage", "Kahnbein, [[Zone 2 am Metatarsale V|jones]]: schlecht durchblutet, heilt langsamer"]], "p": ["Bei Kindern geht alles deutlich schneller, vor allem beim Knochen."], "merk": "Die Zeiten aus der Tabelle gelten für gesunde Erwachsene. Bei Rauchern und Diabetikern eher das obere Ende annehmen."}]}, {"t": "5. Was hilft laut Studienlage?", "b": [{"l": ["Früh funktionell statt lange ruhigstellen: Nach Achillessehnenruptur mit früher Belastung in der Orthese waren die Ergebnisse in Studien ähnlich gut wie mit Gips, bei besserer Funktion im Verlauf (u. a. Willits 2010).", "Beim Außenbandriss am Sprunggelenk ist die funktionelle Behandlung der Ruhigstellung überlegen (Cochrane, Kerkhoffs 2002).", "Beim Muskel reicht eine kurze Ruhephase von wenigen Tagen. Danach fördert Bewegung die Ausrichtung der Fasern (Järvinen 2007).", "Nach VKB-Plastik senkte jeder Monat Wartezeit bis Monat 9 das Risiko einer neuen Knieverletzung um etwa die Hälfte ([[Grindem 2016|grindem]]).", "Sehnen brauchen Pausen: Nach harter Belastung ist die Kollagenbilanz für etwa 1–1,5 Tage negativ ([[Magnusson 2010|magnusson]]). Schwere Reize daher eher alle 2–3 Tage."], "merk": "Belastung ist der Bauplan der Heilung. Zu wenig lässt das Gewebe schwach, zu viel zu früh reißt es wieder auf."}]}, {"t": "6. Für den Praxisalltag", "b": [{"l": ["Beim Erstkontakt das Datum der OP oder Verletzung notieren. Dann weißt du bei jeder Behandlung, in welcher Phase das Gewebe steckt. Doku-Fix rechnet das mit der Heilungsuhr im Verlauf aus.", "In der Entzündungsphase schützen, aber bewegen, was erlaubt ist. Schwellung und Ruheschmerz sind normal.", "In der Proliferation nicht vom fehlenden Schmerz täuschen lassen. Das Gewebe ist jetzt am zerbrechlichsten, beim Kreuzband-Transplantat in Woche 6–8.", "Ab der Konsolidierung gezielt und steigernd belasten: Zug für Sehne und Band, Druck und Gewicht für Knochen.", "Zeit und [[Kriterien|rtskriterien]] zusammen nutzen: Rückkehr in den Sport erst, wenn beides stimmt.", "Belastungsfreigaben nach OP kommen vom Operateur. Im Zweifel nachfragen und das in der Doku festhalten."]}]}], "quellen": ["Järvinen TAH et al. Muscle injuries: optimising recovery. Best Pract Res Clin Rheumatol 2007", "Magnusson SP, Langberg H, Kjaer M. The pathogenesis of tendinopathy: balancing the response to loading. Nat Rev Rheumatol 2010", "Willits K et al. Operative versus nonoperative treatment of acute Achilles tendon ruptures. J Bone Joint Surg Am 2010", "Kerkhoffs GM et al. Immobilisation and functional treatment for acute lateral ankle ligament injuries in adults. Cochrane Database Syst Rev 2002", "Grindem H et al. Simple decision rules can reduce reinjury risk by 84% after ACL reconstruction. Br J Sports Med 2016", "Einhorn TA, Gerstenfeld LC. Fracture healing: mechanisms and interventions. Nat Rev Rheumatol 2015", "Frank CB. Ligament structure, physiology and function. J Musculoskelet Neuronal Interact 2004", "Levenson SM et al. The healing of rat skin wounds. Ann Surg 1965"], "fragen": [["Welches Kollagen bildet sich in der Proliferationsphase zuerst?", ["Typ I", "Typ III", "Typ II", "Typ IV"], 1, "Zuerst entsteht das dünne, ungeordnete Typ-III-Kollagen. Erst in der Konsolidierung übernimmt Typ I."], ["Wann ist ein Kreuzband-Transplantat nach der OP am schwächsten?", ["In Woche 1", "In Woche 6–8", "Nach 6 Monaten", "Nach 1 Jahr"], 1, "In Woche 6–8 ist das Transplantat durch Umbau und Einsprossen von Gefäßen am schwächsten, obwohl das Knie oft schon gut funktioniert."], ["Welche Zeile zeigt die Kreuzband-Plastik?", ["1", "2", "3", "4"], 1, "Zeile 2 hat die längste Entzündungsphase (bis Woche 2) und die späteste volle Belastung (Monat 9–12). Zeile 1 ist ein Band, 3 der Knochen, 4 der Muskel.", "fortbildung/bilder/2026-W47/gh-quiz.webp"], ["Wie lange sollte ein Muskelfaserriss laut Studienlage ruhiggestellt werden?", ["Wenige Tage, unter einer Woche", "2–3 Wochen", "6 Wochen", "Bis er schmerzfrei ist"], 0, "Eine kurze Ruhephase von wenigen Tagen reicht. Danach fördert frühe, schmerzgeleitete Bewegung die Ausrichtung der Fasern."], ["Ab wann sind Pivot-Sportarten nach VKB-Plastik frühestens sinnvoll?", ["Nach 3 Monaten", "Nach 6 Monaten", "Nach 9 Monaten und bestandenen Tests", "Sobald das Knie nicht mehr schwillt"], 2, "Bis Monat 9 senkte jeder Monat Wartezeit das Risiko einer neuen Verletzung um etwa die Hälfte (Grindem 2016). Dazu müssen die Tests bestanden sein."], ["Wie fest ist ein geheiltes Band nach einem Jahr ungefähr?", ["Wie vorher", "Etwa 50–70 % der alten Festigkeit", "Etwa 20 %", "Fester als vorher"], 1, "Ein Band erreicht oft nur 50–70 % der alten Festigkeit. Das erklärt die hohe Rückfallquote nach Sprunggelenkverletzungen."], ["Wie schnell wachsen Axone nach einer Nervenläsion ungefähr nach?", ["1 mm pro Tag", "1 cm pro Tag", "1 mm pro Woche", "1 cm pro Monat"], 0, "Die Faustregel ist etwa 1 mm pro Tag, also rund 2,5–3 cm im Monat. Daraus lässt sich die Wartezeit bis zum Zielmuskel grob schätzen."], ["Warum sollten schwere Sehnenreize eher alle 2–3 Tage gesetzt werden?", ["Weil die Sehne sonst verkalkt", "Weil die Kollagenbilanz nach harter Belastung etwa 1–1,5 Tage negativ ist", "Weil der Muskel schneller ermüdet als die Sehne", "Weil Sehnen nur nachts heilen"], 1, "Nach harter Belastung baut die Sehne zunächst mehr Kollagen ab als auf. Erst danach überwiegt der Aufbau (Magnusson 2010)."], ["Welche Behandlung ist beim akuten Außenbandriss am Sprunggelenk laut Cochrane-Review überlegen?", ["Gips für 6 Wochen", "Funktionell mit Orthese", "Operation bei jedem Grad III", "Bettruhe und Hochlagern für 2 Wochen"], 1, "Funktionelle Behandlung mit Orthese führt zu schnellerer Rückkehr und besserer Funktion als die Ruhigstellung (Kerkhoffs 2002)."], ["Welcher Faktor verlängert die Knochenheilung deutlich?", ["Kindesalter", "Rauchen", "Frühe Bewegung angrenzender Gelenke", "Gute Durchblutung"], 1, "Rauchen verschlechtert die Durchblutung und erhöht das Risiko für verzögerte Heilung und Pseudarthrose. Kinder heilen dagegen schneller."]], "info": {"mechano": {"t": "Mechanotransduktion", "x": ["So nennt man den Weg, auf dem Zellen eine mechanische Last in ein biochemisches Signal übersetzen. Fibroblasten und Tenozyten spüren Zug und Verformung über ihre Zellmembran und das Zellskelett.", "Die Antwort darauf: mehr Kollagen, und die Fasern lagern sich in Zugrichtung an. Das ist die biologische Grundlage dafür, dass dosierte Belastung in der Heilung wirkt wie ein Medikament."], "q": "Khan und Scott, Br J Sports Med 2009"}, "kallus": {"t": "Kallus und Knochenheilung", "x": ["Der weiche Kallus besteht aus Bindegewebe und Knorpel und überbrückt den Bruchspalt, ist aber noch nicht tragfähig. Er verknöchert zum harten Kallus aus Geflechtknochen. Im Remodelling wird daraus wieder normaler Lamellenknochen.", "Abgrenzung: Diese Kallusbildung heißt sekundäre Knochenheilung. Bei sehr stabiler Versorgung, etwa mit einer Platte unter Kompression, heilt der Knochen direkt ohne sichtbaren Kallus (primäre Heilung). Im Röntgen sieht man dann keinen Kallus, das ist kein schlechtes Zeichen."]}, "bandgrad": {"t": "Gradeinteilung der Bandverletzung", "x": ["Grad I: Zerrung, Fasern überdehnt, Band stabil.", "Grad II: Teilriss, leichte bis mäßige Aufklappbarkeit mit noch spürbarem Anschlag.", "Grad III: kompletter Riss, deutliche Instabilität ohne festen Anschlag. Am Sprunggelenk sind dann oft mehrere Bänder betroffen. Die Einteilung erfolgt klinisch über Schwellung, Hämatom und Stabilitätstests."]}, "ligamentisierung": {"t": "Ligamentisierung", "x": ["Das Sehnentransplantat beim Kreuzbandersatz ist anfangs totes Gewebe ohne eigene Blutversorgung. Es wird erst abgebaut, dann von Gefäßen und Zellen neu besiedelt und schließlich zu einem bandähnlichen Gewebe umgebaut.", "Während dieses Umbaus verliert es zunächst Festigkeit, deshalb die schwache Phase einige Wochen nach der OP. Bis das Transplantat ausgereift ist, vergeht etwa ein Jahr oder mehr, und es erreicht nie ganz die Eigenschaften eines natürlichen Kreuzbands."]}, "pseudarthrose": {"t": "Pseudarthrose", "x": ["Ein Bruch, der nicht knöchern zusammenwächst. Es bleibt ein Spalt mit Bindegewebe, manchmal ein falsches Gelenk mit Beweglichkeit. Nach gängiger Definition spricht man von verzögerter Heilung nach 4–6 Monaten, von Pseudarthrose ab etwa 6 Monaten ohne Durchbau.", "Hinweise im Verlauf: anhaltender Belastungsschmerz oder Druckschmerz am Bruch, obwohl die Heilzeit vorbei ist. Dann an den Arzt zurückmelden."]}, "jones": {"t": "Basis Metatarsale V: drei Zonen", "x": ["Zone 1: Abrissbruch an der Tuberositas, heilt meist gut mit kurzer Schonung.", "Zone 2: Übergang von Metaphyse zu Diaphyse, die eigentliche Jones-Fraktur. Hier liegt eine Wasserscheide der Blutversorgung, deshalb heilt sie schlecht und wird bei Sportlern oft operiert.", "Zone 3: proximaler Schaft, meist Ermüdungsbruch, ebenfalls langsam."]}, "grindem": {"t": "Grindem 2016", "x": ["106 Sportler aus Pivot-Sportarten nach VKB-Plastik, 2 Jahre beobachtet. Wer vor der Rückkehr die Kriterien nicht erfüllte, verletzte sich in 38 % der Fälle erneut am Knie, wer alle erfüllte, in rund 5 %.", "Rückkehr in Sport mit Springen und Drehen ging mit etwa vierfachem Risiko einher. Das Bestehen der Kriterien senkte das Risiko einer neuen Knieverletzung um 84 %, daher auch der Titel der Studie."], "q": "Grindem H et al., Br J Sports Med 2016"}, "magnusson": {"t": "Kollagenbilanz nach Belastung", "x": ["Nach harter Belastung steigt in der Sehne die Kollagenbildung auf das 2–3-Fache, mit Gipfel nach etwa 24 Stunden. Der Abbau setzt aber früher ein und steigt stärker.", "Daraus ergibt sich zuerst ein Nettoverlust und erst danach ein Aufbau, der bis etwa 72 Stunden anhalten kann. Wer die Sehne in der Verlustphase erneut hart belastet, riskiert, dass sie sich unter dem Strich abbaut."], "q": "Magnusson, Langberg, Kjaer, Nat Rev Rheumatol 2010"}, "rtskriterien": {"t": "Rückkehrkriterien", "x": ["Meist ein Bündel aus Kraftmessung, Sprungtests und Fragebogen. Verglichen wird mit der gesunden Seite als Limb Symmetry Index: Wert der betroffenen Seite geteilt durch die gesunde, mal 100. Beim Kreuzband gelten Quadrizepskraft und einbeinige Hop-Tests von mindestens 90 % als übliche Grenze.", "Vorsicht: Hat auch die gesunde Seite in der Reha abgebaut, sieht der Index besser aus, als es ist. Deshalb möglichst Ausgangswerte vor der OP oder Normwerte mit heranziehen."]}}}, {"id": "w47-kn11", "titel": "Habituelle Patellaluxation", "art": "kb", "kb": "KN11", "min": 11, "abschnitte": [{"t": "Wie oft springt sie wieder raus?", "b": [{"bars": [["Konservativ nach Erstluxation", 45, "39–50 % Reluxation"], ["Nach Operation bei Erstluxation", 15, "0–31 %"], ["Nach MPFL-Ersatz bei Rezidiv", 5, "etwa 0–9 % nach 5 Jahren"]], "p": ["Zahlen aus der [[DGU-Leitlinie Patellaluxation|dgull]] (2021). Mit jedem zusätzlichen anatomischen Risikofaktor steigt das Risiko einer erneuten Luxation."]}]}, {"t": "1. Was ist das eigentlich?", "b": [{"p": ["Bei der habituellen Patellaluxation springt die Kniescheibe ohne Unfall immer wieder nach außen. Die Leitlinie fasst den Begriff eng: Die Patella luxiert unwillkürlich bei jedem Bewegungszyklus, meist bei Beugung, und springt bei Streckung zurück. Bleibt sie dauerhaft draußen, heißt das permanente Luxation.", "Im Praxisalltag steht „habituell“ oft auch für wiederholte Luxationen bei einer ungünstigen Anatomie, ohne dass die Patella bei jeder Beugung herausspringt. Für die Behandlung lohnt es sich, genau nachzufragen: Springt sie bei jeder Beugung raus oder nur ab und zu?", "Betroffen sind vor allem Kinder und Jugendliche. Die Hauptzeit liegt zwischen 10 und 20 Jahren, die echte habituelle Form fällt oft schon im Grundschulalter auf."]}, {"l": ["Trochleadysplasie: Die Gleitrinne ist flach oder sogar vorgewölbt (Dejour Typ A–D).", "[[Patella alta|patellaalta]]: Die Kniescheibe steht hoch und findet erst spät in die Rinne.", "Großer [[TT-TG-Abstand|ttg]]: Die Tuberositas tibiae liegt weit lateral, der Zug geht nach außen.", "Genu valgum, vermehrte femorale Antetorsion, tibiale Außentorsion.", "Hyperlaxität und schwacher M. vastus medialis.", "Bei Kindern oft ein verkürzter Quadrizeps oder ein straffer lateraler Zügel, der die Patella bei Beugung nach außen zieht."], "merk": "Bei der habituellen Luxation ist nicht der Unfall das Problem, sondern die Anatomie. Ohne Korrektur der Anatomie bleibt die Instabilität meist bestehen."}, {"fig": [{"src": "fortbildung/bilder/2026-W47/kn11-mpfl.webp", "t": "Rechtes Knie von vorne-innen, Haut entfernt.", "c": "1 MPFL (mediales patellofemorales Ligament), 2 M. vastus medialis obliquus, 3 Patella, 4 Lig. patellae, 5 laterales Retinakulum. Medial liegt im Bild rechts. MPFL und VMO halten die Patella nach medial, das MPFL reißt bei der Luxation fast immer."}]}]}, {"t": "2. Formen und Verlauf", "b": [{"tab": [["Erstluxation", "Meist Drehung bei gebeugtem Knie, MPFL reißt. Konservativ 39–50 % Reluxation."], ["Rezidivierende Luxation", "Wiederholte Luxationen, oft mit anatomischen Risikofaktoren. Häufigste OP-Indikation."], ["Habituelle Luxation", "Luxation bei jeder Beugung (selten bei Streckung), ohne Unfall. Oft wenig Schmerz."], ["Permanente Luxation", "Patella steht nie in der Rinne. Meist angeboren, früh operativ."]], "p": ["Die Leitlinie unterscheidet außerdem objektive Instabilität (mindestens eine Luxation plus ein anatomischer Risikofaktor), [[potenzielle Instabilität|potinstab]] und patellofemorales Schmerzsyndrom (Einteilung nach Dejour)."]}]}, {"t": "3. Befund und Abgrenzung", "b": [{"l": ["J-Sign: Die Patella rutscht bei der Streckung am Ende sichtbar nach lateral, wie ein umgedrehtes J.", "Apprehension-Test nach Fairbank: Bei Druck nach lateral spannt der Patient an oder hält das Bein fest.", "Patella-Glide in Quadranten: Wie weit lässt sich die Kniescheibe nach lateral schieben? Mehr als 2 Quadranten spricht für eine mediale Insuffizienz.", "[[Beighton-Score|beighton]] für Hypermobilität, Beinachse im Stand, Rotation der Hüfte in Bauchlage.", "Bei Kindern: Beugung mit fixierter Patella testen. Lässt sich das Knie nur beugen, wenn die Patella nach außen ausweicht, spricht das für einen verkürzten Quadrizeps."]}, {"tab": [["Patellofemorales Schmerzsyndrom", "Schmerz vorn beim Treppensteigen, keine Luxation, Apprehension negativ"], ["Plica-Syndrom", "Schnappen medial, Schmerz, Patella bleibt in der Rinne"], ["Meniskusläsion", "Blockade, Gelenkspaltschmerz, McMurray positiv"], ["VKB-Ruptur", "Giving way bei Drehung, Lachman positiv, Patella stabil"], ["Osteochondrales Fragment nach Luxation", "Blockade, großer Erguss, muss ärztlich abgeklärt werden"]], "merk": "Nach jeder Luxation mit großem Erguss oder Blockade an ein Knorpel-Knochen-Fragment denken. Das ist eine absolute OP-Indikation."}]}, {"t": "4. Bildgebung", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W47/kn11-mrt.webp", "t": "MRT axial (T2 fettgesättigt), rechtes Knie.", "c": "Der Pfeil zeigt auf die flache Gleitrinne (Trochleadysplasie). Die Patella steht oben links nach lateral subluxiert, außerhalb der Rinne. Vorne ist oben, lateral links."}, {"src": "fortbildung/bilder/2026-W47/kn11-roe.webp", "t": "Röntgen seitlich, rechtes Knie.", "c": "Der Pfeil zeigt auf die hochstehende Patella (Patella alta). Das Lig. patellae ist deutlich länger als die Patella selbst. Vorne ist rechts."}, {"src": "fortbildung/bilder/2026-W47/kn11-axial.webp", "t": "Patellofemoralgelenk axial, schematisch.", "c": "1 normale, tiefe Rinne mit zentrierter Patella. 2 flache Rinne, Patella nach lateral luxiert. 3 flache Rinne, Patella noch mittig, aber ohne seitlichen Halt. Lateral liegt links."}]}, {"p": ["KI-erstellte Lehrbilder nach typischen Lehrbuchfällen, geprüft, keine echten Aufnahmen."]}, {"p": ["Röntgen: Patella axial und seitlich ([[Crossing Sign|crossing]] als Zeichen der Trochleadysplasie, Patellahöhe). MRT: Knorpel, MPFL, Form der Trochlea, TT-TG-Abstand. Die Leitlinie nennt für eine distale Korrektur einen TT-TG-Abstand über 17 bis 20 mm und rät ab einem Valgus über 10 Grad zu erweiterter Diagnostik."], "merk": "Drei Bildbefunde, die du kennen solltest: flache Trochlea, hohe Patella, großer TT-TG-Abstand. Je mehr davon, desto höher das Reluxationsrisiko."}]}, {"t": "5. Was hilft laut Studienlage?", "b": [{"l": ["Nach Erstluxation ohne Fragment ist die konservative Behandlung Standard: kurz Schiene, dann 4-Punkt-Orthese mit stufenweise freigegebener Beugung, insgesamt etwa 6 Wochen, dazu Teilbelastung und früh isometrisches Quadrizepstraining (DGU 2021).", "Wie lange ruhiggestellt wird, beeinflusst das Reluxationsrisiko nicht (DGU 2021, Evidenz IIb).", "Kein Reha-Protokoll ist nachweislich überlegen. Bewährt sind Kraft- und Koordinationstraining, Hüftkräftigung, Tape oder Bandage (DGU 2021).", "Eine OP senkt das Reluxationsrisiko deutlich, führt aber nicht automatisch zu einem besseren klinischen Ergebnis als konservativ (DGU 2021).", "Bei echter habitueller Luxation reicht Training allein selten. Je nach Ursache wird operiert: [[MPFL-Plastik|mpflplastik]], Versetzung der Tuberositas, [[Trochleaplastik|trochleaplastik]] oder bei Kindern eine Verlängerung des Quadrizeps.", "Zur Reha nach MPFL-Plastik gibt es keinen Konsens zu Ruhigstellung und Belastung (Delphi-Konsens, Hurley 2023). Es gilt das Schema des Operateurs."], "merk": "Konservativ heißt bei Instabilität: Kraft, Kontrolle und Hüfte. Springt die Patella bei jeder Beugung, gehört die Frage nach einer OP auf den Tisch."}]}, {"t": "6. Für den Praxisalltag", "b": [{"l": ["Genau fragen: Springt die Kniescheibe bei jeder Beugung raus oder nur gelegentlich? Seit wann? Gibt es weitere Gelenke, die luxieren?", "Übungen im stabilen Bereich halten. Viele Patienten fühlen sich zwischen 0 und 30° Beugung am unsichersten, weil die Patella dort noch nicht in der Rinne geführt wird.", "Kniekontrolle üben: Knie über dem zweiten Zeh, kein Valgus beim Step-down und bei der Landung.", "Hüftabduktoren und Außenrotatoren kräftigen, sie halten das Knie aus der Valgusstellung.", "Lateral eher lockern (Tractus, lateraler Zügel), medial kräftigen.", "Bei Kindern und Jugendlichen mit Hypermobilität an andere Gelenke denken und die Eltern einbeziehen.", "Nach OP immer den OP-Bericht und das Nachbehandlungsschema anfordern und in der Doku festhalten."]}]}], "quellen": ["DGU-Leitlinie Patellaluxation, AWMF 012-024, S2e, 2021 (gültig bis 10/2026, Überarbeitung angekündigt)", "Hurley ET et al. A modified Delphi consensus statement on patellar instability: part II. Bone Joint J 2023", "Chotel F et al. zur Einteilung der Patellainstabilität bei Kindern (zitiert nach Übersichtsarbeiten zur pädiatrischen Patellainstabilität)", "Dejour H et al. Factors of patellar instability: an anatomic radiographic study. Knee Surg Sports Traumatol Arthrosc 1994"], "fragen": [["Wie definiert die DGU-Leitlinie die habituelle Patellaluxation?", ["Luxation nach einem Sportunfall", "Unwillkürliche Luxation bei jedem Bewegungszyklus", "Patella steht nie in der Rinne", "Luxation nur im Schlaf"], 1, "Habituell heißt laut Leitlinie: Die Patella luxiert bei jedem Bewegungszyklus. Steht sie nie in der Rinne, ist es eine permanente Luxation."], ["Welcher Befund passt zu einer Trochleadysplasie?", ["Tiefe, V-förmige Gleitrinne", "Flache oder vorgewölbte Gleitrinne", "Patella baja", "Verkürztes Innenband"], 1, "Bei der Trochleadysplasie ist die Rinne flach oder vorgewölbt. Die Patella findet dann wenig Halt."], ["Welche Darstellung zeigt eine luxierte Patella bei Trochleadysplasie?", ["1", "2", "3", "Keine"], 1, "In 2 ist die Rinne flach und die Patella nach lateral verschoben. 1 ist normal, 3 hat eine flache Rinne ohne Luxation.", "fortbildung/bilder/2026-W47/kn11-axial.webp"], ["Worauf zeigt der Pfeil?", ["Gelenkerguss im Recessus", "Flache Gleitrinne (Trochleadysplasie)", "Riss des vorderen Kreuzbands", "Bakerzyste"], 1, "Die Rinne ist fast eben statt V-förmig. Die Patella steht deshalb lateral außerhalb der Rinne.", "fortbildung/bilder/2026-W47/kn11-mrt.webp"], ["Welche Struktur ist mit der 1 markiert?", ["Laterales Retinakulum", "Mediales patellofemorales Ligament (MPFL)", "Innenband", "Pes anserinus"], 1, "Das MPFL zieht von der Innenkante der Patella zum medialen Femur. Es ist der wichtigste mediale Halt der Patella.", "fortbildung/bilder/2026-W47/kn11-mpfl.webp"], ["Was zeigt der Pfeil auf dem seitlichen Röntgenbild?", ["Patella baja", "Patella alta", "Osgood-Schlatter", "Patellafraktur"], 1, "Die Patella steht hoch, das Lig. patellae ist deutlich länger als die Patella. Das ist ein Risikofaktor für Luxationen.", "fortbildung/bilder/2026-W47/kn11-roe.webp"], ["Wie hoch ist die Reluxationsrate nach konservativ behandelter Erstluxation laut Leitlinie?", ["Unter 5 %", "Etwa 10 %", "39–50 %", "Über 90 %"], 2, "Die Leitlinie nennt 39–50 %. Mit mehreren anatomischen Risikofaktoren liegt sie höher."], ["Was ist das J-Sign?", ["Schmerz in J-Form um die Patella", "Seitliches Abgleiten der Patella am Ende der Streckung", "Ein Röntgenzeichen der Patella alta", "Hinken mit Außendrehung des Fußes"], 1, "Die Patella gleitet bei der Streckung am Ende nach lateral und beschreibt dabei die Form eines umgedrehten J."], ["Welche Struktur reißt bei einer lateralen Patellaluxation typischerweise?", ["Lig. collaterale laterale", "Mediales patellofemorales Ligament (MPFL)", "Lig. patellae", "Hinteres Kreuzband"], 1, "Das MPFL ist der wichtigste mediale Halt der Patella und reißt bei der Luxation meist."], ["Was ist eine absolute OP-Indikation nach Patellaluxation?", ["Erste Luxation bei einer Jugendlichen", "Osteochondrales Fragment", "Schwellung am ersten Tag", "Positiver Apprehension-Test"], 1, "Ein Knorpel-Knochen-Fragment, eine nicht reponierbare Luxation und eine Luxationsfraktur sind absolute OP-Indikationen."], ["Ab welchem TT-TG-Abstand wird laut Leitlinie eine distale Korrektur erwogen?", ["Über 5 mm", "Über 10 mm", "Über 17 bis 20 mm", "Über 40 mm"], 2, "Die Leitlinie nennt einen TT-TG-Abstand von mehr als 17 (20) mm."], ["Welche Aussage zur Ruhigstellung nach Erstluxation stimmt?", ["Längere Ruhigstellung senkt die Reluxationsrate", "Die Dauer der Ruhigstellung beeinflusst die Reluxation nicht", "Gips für 12 Wochen ist Standard", "Ruhigstellung ist verboten"], 1, "Laut Leitlinie hat die Dauer der Immobilisation keinen Einfluss auf die Reluxation. Empfohlen sind insgesamt etwa 6 Wochen Orthese mit stufenweiser Beugung."], ["Welche Muskelgruppe sollte bei Patellainstabilität neben dem Quadrizeps besonders gekräftigt werden?", ["Wadenmuskulatur", "Hüftabduktoren und -außenrotatoren", "Rückenstrecker", "Zehenbeuger"], 1, "Kräftige Hüftabduktoren und Außenrotatoren verhindern den Valgus und entlasten so die laterale Führung der Patella."], ["Bei einem Kind springt die Patella bei jeder Beugung heraus. Woran denkst du als Ursache zuerst?", ["Verkürzter Quadrizeps oder straffer lateraler Zügel", "Meniskusriss", "Morbus Osgood-Schlatter", "Bakerzyste"], 0, "Bei der habituellen Luxation im Kindesalter zieht oft ein verkürzter Quadrizeps oder ein straffer lateraler Zügel die Patella bei Beugung nach außen."]], "bild": "fortbildung/bilder/2026-W47/kn11-mpfl.webp", "info": {"dgull": {"t": "DGU-Leitlinie Patellaluxation", "x": ["S2e-Leitlinie der Deutschen Gesellschaft für Unfallchirurgie (AWMF 012-024) von 2021. S2e heißt: Die Empfehlungen beruhen auf einer systematischen Auswertung der Studien.", "Die Gültigkeit war bis 10/2026 angegeben, eine Überarbeitung ist angekündigt. Bis dahin bleibt sie die deutsche Referenz, einzelne Empfehlungen sollte man aber mit neueren Arbeiten abgleichen."]}, "patellaalta": {"t": "Patella alta messen", "x": ["Gemessen im seitlichen Röntgen oder MRT, meist mit dem Caton-Deschamps-Index: Abstand vom Unterrand der Gelenkfläche der Patella bis zur Vorderkante des Tibiaplateaus, geteilt durch die Länge der Gelenkfläche. Ab 1,2 gilt die Patella als hochstehend.", "Ebenfalls verbreitet ist der Insall-Salvati-Index (Länge der Patellasehne zur Länge der Patella), auch dort liegt die Grenze bei etwa 1,2."], "q": "Dejour et al., KSSTA 1994"}, "ttg": {"t": "TT-TG-Abstand", "x": ["Abstand zwischen Tuberositas tibiae und dem tiefsten Punkt der Trochlea, gemessen in übereinandergelegten axialen CT- oder MRT-Schichten. Er zeigt, wie weit der Zug der Patellasehne nach lateral versetzt ist.", "In der Originalarbeit von Dejour 1994 galten 20 mm und mehr als krankhaft. Das fand sich bei 56 % der instabilen Knie, aber nur selten bei Gesunden. Im MRT fallen die Werte meist etwas kleiner aus als im CT."], "q": "Dejour et al., KSSTA 1994"}, "potinstab": {"t": "Potenzielle Instabilität", "x": ["Gemeint sind Patienten mit Beschwerden an der Kniescheibe und mindestens einem anatomischen Risikofaktor, die aber noch nie eine echte Luxation hatten.", "Eine Instabilität ist damit nicht bewiesen. Im Vordergrund stehen Training und Belastungssteuerung, nicht die Operation."], "q": "Dejour et al., KSSTA 1994"}, "beighton": {"t": "Beighton-Score", "x": ["9 Punkte aus 5 Tests: Hände flach auf den Boden bei gestreckten Knien (1 Punkt), dazu je Seite Überstreckung von Ellenbogen und Knie über 10°, Daumen an den Unterarm und Kleinfinger im Grundgelenk über 90° nach hinten.", "Grenzen für generalisierte Hypermobilität nach den Kriterien von 2017: vor der Pubertät ab 6 Punkten, bis 50 Jahre ab 5, über 50 ab 4."], "q": "Malfait et al., Am J Med Genet 2017"}, "crossing": {"t": "Crossing Sign und Dejour-Typen", "x": ["Im exakt seitlichen Röntgen kreuzt die Linie des Trochleabodens die Vorderkante der Femurkondylen, die Rinne ist dort also flach. In der Arbeit von Dejour 1994 hatten 96 % der Knie mit Trochleadysplasie dieses Zeichen.", "Typ A: Crossing Sign, Rinne noch angedeutet. Typ B: flache oder vorgewölbte Trochlea mit Sporn. Typ C: Doppelkontur, mediale Facette unterentwickelt. Typ D: alles zusammen mit steiler Stufe. B und D gelten als schwer."]}, "mpflplastik": {"t": "MPFL-Plastik", "x": ["Ersatz des gerissenen medialen patellofemoralen Bandes, meist mit einer körpereigenen Sehne, oft der Gracilissehne. Das Band hält die Patella in den ersten Beugegraden, bis die Rinne die Führung übernimmt.", "Es korrigiert keine Anatomie. Bei ausgeprägter Dysplasie, hoher Patella oder großem TT-TG-Abstand wird es deshalb oft mit knöchernen Eingriffen kombiniert. Bei offenen Wachstumsfugen braucht die Befestigung am Femur Vorsicht, weil sie nahe der Fuge liegt."]}, "trochleaplastik": {"t": "Trochleaplastik", "x": ["Die flache oder vorgewölbte Gleitrinne wird operativ vertieft, damit die Patella wieder geführt wird. Sinnvoll vor allem bei schwerer Dysplasie (Dejour B und D).", "Bei offenen Wachstumsfugen wird sie in der Regel nicht gemacht, weil die Fuge direkt darunter liegt. Die Nachbehandlung richtet sich nach dem Operateur."]}}}, {"id": "w47-qs", "titel": "Querschnitt: was ist je Höhe möglich?", "art": "kb", "kb": "NE06", "min": 14, "bild": "fortbildung/bilder/2026-W47/qs-niveaus.webp", "abschnitte": [{"t": "Wer läuft wieder?", "b": [{"bars": [["AIS A (komplett)", 12, "unter 15 %"], ["AIS B (sensibel inkomplett)", 33, "etwa ein Drittel"], ["AIS C (motorisch inkomplett)", 75, "etwa drei Viertel"], ["AIS D (motorisch inkomplett, kräftiger)", 92, "über 90 %"]], "p": ["Anteil, der später gehen kann, nach dem AIS-Grad in der ersten Woche (SCIRE, Predictors of Walking). Gruppenwerte, kein Versprechen für den Einzelnen."]}]}, {"t": "1. Einteilung: Höhe und AIS", "b": [{"p": ["Zwei Angaben bestimmen fast alles: das [[neurologische Niveau (NLI)|nli]] und der AIS-Grad nach ISNCSCI. Die Höhe sagt, welche Funktion bei motorisch kompletter Lähmung nach etwa einem Jahr erreichbar ist. Der AIS-Grad sagt, wie viel darüber hinaus noch zurückkommen kann.", "Gültig ist weiter die Revision 2019 der International Standards. Das ASIA-Arbeitsblatt von 04/2026 ändert nichts an den Regeln. Untersucht werden je Seite 10 Kennmuskeln, 28 sensible Schlüsselpunkte (leichte Berührung und Nadelstich) und die anorektale Untersuchung."]}, {"tab": [["C5", "Ellenbogenflexoren"], ["C6", "Handgelenksextensoren"], ["C7", "Ellenbogenextensoren"], ["C8", "Fingerflexoren (Mittelfinger, Endglied)"], ["T1", "Fingerabduktoren (kleiner Finger)"], ["L2", "Hüftflexoren"], ["L3", "Knieextensoren"], ["L4", "OSG-Dorsalextensoren"], ["L5", "Großzehenextensoren"], ["S1", "OSG-Plantarflexoren"]], "p": ["Das motorische Niveau ist der tiefste Kennmuskel mit mindestens Kraftgrad 3, wenn alle darüber 5 haben. Wo es keinen Kennmuskel gibt (C1–C4, T2–L1, S2–S5), gilt das sensible Niveau."]}, {"tab": [["AIS A", "Komplett: keine Motorik und keine Sensibilität in S4-5"], ["AIS B", "Sensibel inkomplett: Sensibilität sakral erhalten, keine Motorik mehr als 3 Segmente unter dem motorischen Niveau"], ["AIS C", "Motorisch inkomplett: weniger als die Hälfte der Kennmuskeln unter dem NLI mit Kraftgrad 3 oder mehr"], ["AIS D", "Motorisch inkomplett: mindestens die Hälfte dieser Kennmuskeln mit Kraftgrad 3 oder mehr"], ["AIS E", "Normalbefund nach vorher dokumentierter Lähmung"]], "merk": "Komplett heißt nur eins: keine willkürliche Analkontraktion, kein tiefes anales Druckempfinden und S4-5 überall 0. Alles andere ist inkomplett.", "p": ["Die DMGP empfiehlt für Befundtexte: „Querschnittlähmung C6, AIS B, mit [[Teilerhalt bis C8|zpp]]“. Tetra- und Paraplegie bleiben als beschreibende Wörter im Alltag üblich."]}]}, {"t": "2. Die Schwellen von C4 bis L3", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W47/qs-niveaus.webp", "t": "Rückenmark von hinten mit vier Schlüsselhöhen.", "c": "1 C4: Zwerchfell (C3–C5) arbeitet, meist keine Dauerbeatmung nötig. 2 C6: Handgelenksstrecker, damit Tenodesegriff. 3 Th6: Grenze für autonome Dysreflexie und orthostatische Hypotonie. 4 L3: Quadrizeps, ab hier ist Gehen außer Haus realistisch. Schematisch: Das Rückenmark selbst endet beim Erwachsenen etwa bei LWK 1/2, darunter verlaufen nur noch Nervenwurzeln (Cauda equina)."}]}, {"p": ["KI-erstellte Lehrbilder nach typischen Lehrbuchfällen, geprüft, keine echten Aufnahmen."]}, {"l": ["C4: Über C3 meist lebenslange Beatmung, ab C4 geht es meist ohne. Husten fehlt.", "C5: Hand zum Mund mit Schiene, E-Rollstuhl mit Joystick.", "C6: Tenodesegriff, Rutschbrett-Transfer meist mit Hilfe, Autofahren im umgebauten Van.", "C7: Trizeps. Die Schlüsselhöhe für Selbstständigkeit auf Rollstuhlebene, weil Transfers und Druckentlastung gehen.", "C8–T1: volle Hand, auch Bodentransfer.", "Th6: Darüber droht [[autonome Dysreflexie|dysreflexie]], die Temperaturregelung ist gestört.", "L3: Quadrizeps. Gehen außer Haus wird realistisch, meist mit Unterschenkelorthese und Stöcken."], "merk": "Wer die Schwellen C5, C6, C7, Th6 und L3 kennt, kann bei fast jedem Querschnittpatienten die Ziele einordnen."}]}, {"t": "3. Tetraplegie: was je Höhe drin ist", "b": [{"tab": [["C1–C4", "Komplett abhängig, leitet die Pflege selbst an. E-Rollstuhl mit Kinn-, Kopf- oder [[Saug-Blas-Steuerung|saugblas]], Lifter, Stehtisch. 24 h Hilfe."], ["C5", "Essen mit langer Oppositionsschiene nach Vorbereitung. E-Rollstuhl, Greifreifen mit Noppen nur kurz drinnen. Hilfe 16 h (Expertenwert), real im Median 23 h."], ["C6", "Essen selbstständig außer Schneiden, Oberkörper anziehen selbst. Manueller Rollstuhl in der Ebene. Brett-Transfer meist mit Hilfe. Hilfe 10 h, real 17 h."], ["C7", "Selbstständig mit Hilfsmitteln, Transfers in der Ebene ohne Hilfe, Auto mit Handbedienung. Hilfe 8 h, real 12 h."], ["C8–T1", "Selbstständig, Bodentransfer möglich, wenig Hilfsmittel."]], "p": ["Werte aus der PVA-Leitlinie „Outcomes Following Traumatic SCI“ (1999) und dem ASCIP-Material von Kirshblum (2023), für motorisch komplette Lähmung ein Jahr nach der Verletzung. Die echten Medianwerte liegen bei C5 bis C7 klar über den Expertenwerten, ältere Menschen erreichen weniger."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/qs-tenodese.webp", "t": "Tenodesegriff bei C6.", "c": "Das Handgelenk wird aktiv gestreckt, dadurch spannen sich die gelähmten Fingerbeuger passiv und die Finger schließen sich um den Becher. Beugt er das Handgelenk, öffnet sich die Hand."}]}, {"l": ["Die Höhe aus der Akutphase ist oft nicht die Endhöhe. Bei kompletter Tetraplegie verbesserte sich das motorische Niveau im ersten Jahr bei 42 % um eine Höhe (Marino 2011).", "Wer mit C5 kommt, kann also bei C6-Zielen landen. Ziele deshalb regelmäßig neu prüfen."], "merk": "Bei C6 nie die Fingerbeuger bei gestrecktem Handgelenk dehnen. Eine leichte Verkürzung macht den Tenodesegriff erst kräftig."}]}, {"t": "4. Paraplegie, Transfers und Gehen", "b": [{"tab": [["T2–T9", "Volle Arme, Rumpf je nach Höhe. Aktivrollstuhl selbstständig auch draußen. Stehen im Stehgerät, Gehen nur als Training mit Oberschenkelorthesen (KAFO)."], ["T10–L2", "Bauch und Rumpf stabil. Gehen im Haus mit KAFO und Unterarmstützen möglich, draußen Rollstuhl."], ["L3–S5", "Quadrizeps vorhanden. Gehen außer Haus, meist mit Unterschenkelorthese (AFO) und Stöcken."], ["Konus/Kauda", "Je nach Höhe wie L3–S5. Konus: früh schwere Blasen- und Darmstörung, Mischbild. Kauda: schlaff, oft starker Wurzelschmerz, bessere Erholungschance."]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/qs-transfer.webp", "t": "Rutschbrett-Transfer bei Paraplegie.", "c": "Er stützt sich mit gestreckten Armen ab, hebt das Gesäß an und rutscht über das Brett zur Liege. Der Therapeut sichert am Becken, ohne zu heben. Ab C7 klappt so ein Transfer in der Ebene meist ohne Hilfe."}]}, {"l": ["Faustregel fürs Gehen außer Haus (Hussey und Stauffer): beide Hüftbeuger mindestens 3/5 und ein Knieextensor mindestens 3/5.", "Gehen mit Orthesen kostet pro Strecke mindestens sechsmal so viel Energie wie normales Gehen. Viele mit kompletter thorakaler Lähmung legen das Orthesengehen über die Jahre wieder ab.", "Der Rollstuhl ist deshalb kein Scheitern, sondern meist das effizienteste Fortbewegungsmittel."], "merk": "Bei kompletter thorakaler Lähmung ist Stehen und Orthesengehen Training für Kreislauf, Knochen und Spastik, kein Alltagsziel."}]}, {"t": "5. Syndrome und Prognose", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W47/qs-syndrome.webp", "t": "Drei Rückenmarksyndrome im Querschnitt, vorne ist unten.", "c": "1 Zentrales Rückenmarksyndrom: Schaden um den Zentralkanal, Arme stärker betroffen als Beine. 2 Brown-Séquard: eine Hälfte geschädigt. 3 Anteriores Syndrom: vordere zwei Drittel geschädigt, Hinterstränge erhalten."}]}, {"tab": [["Zentrales Syndrom", "Häufigstes Syndrom, oft Ältere mit Spondylose nach Sturz mit Überstreckung. Erholung erst Beine, dann Blase und Darm, zuletzt die Hand."], ["Brown-Séquard", "Gleiche Seite: Lähmung, Lage- und Vibrationssinn weg. Gegenseite: Schmerz und Temperatur weg. Beste Prognose, 75–90 % gehen bei Entlassung."], ["Anteriores Syndrom", "Motorik und Nadelstich fallen aus, Berührung und Lagesinn bleiben. Schlechteste Prognose, nur 10–20 % Muskelerholung."]]}, {"l": ["AIS A: Im ersten Jahr wird etwa ein Drittel der Tetraplegiker inkomplett, meist nur zu B. Nach fünf Jahren sind 94 % weiter AIS A.", "AIS B: Entscheidend ist der [[Nadelstich|nadelstich]]. Ist er erhalten, gehen später 33–89 %, sonst kaum jemand.", "AIS C: Entscheidend ist das Alter. Unter 50 gehen 71–91 %, darüber 25–42 %.", "Van-Middendorp-Regel: Alter ab 65 gibt −10 Punkte, Kraft Quadrizeps (L3) und Wade (S1) je mal 2, leichte Berührung L3 und S1 je mal 5. Ab 20 Punkten liegt die Chance auf selbstständiges Gehen im Haus bei etwa 90 %. Innerhalb von AIS D trennt sie schlecht.", "Die schnellste Erholung passiert in den ersten drei Monaten, das meiste bis sechs bis neun Monate, Zuwächse bis 12–18 Monate sind möglich."], "merk": "Die S3-Leitlinie (2025) rät von Prognoseaussagen gegenüber Patienten ab. Die Zahlen gehören in die Planung, nicht in Versprechen."}]}, {"t": "6. Komplikationen in jeder Einheit", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W47/qs-dysreflexie.webp", "t": "Autonome Dysreflexie bei hoher Läsion.", "c": "1 Gerötetes, schwitzendes Gesicht oberhalb der Läsion. 2 Blutdruck steigt mehr als 20 mmHg über den Ausgangswert. 3 Läsionshöhe Th6 oder höher. 4 Häufigster Auslöser: volle Blase oder abgeknickter Katheter."}]}, {"l": ["Autonome Dysreflexie ab Th6: plötzlicher Kopfschmerz, Schwitzen und Rötung oberhalb, Gänsehaut unterhalb. Der Ausgangswert liegt oft nur bei etwa 100 mmHg, 130 mmHg können also schon gefährlich sein.", "Sofort: aufsetzen, Beine runter, alles Enge lösen, RR alle 1–2 Minuten, Katheter und Beutel prüfen, dann den Darm. Ab systolisch 150 mmHg oder ohne gefundene Ursache ärztlich (CSCM 2020).", "Auch Gurte eines Gewichtsentlastungssystems, enge Kleidung oder ein eingewachsener Nagel können sie auslösen.", "Orthostatische Hypotonie: Abfall um mindestens 20/10 mmHg in drei Minuten. Langsam aufrichten, nach dem Aufsitzen 30 Sekunden warten, Kipptisch stufenweise.", "Atmung: C3–C5 versorgen das Zwerchfell. Tetraplegiker atmen im Liegen besser als im Sitzen, eine Bauchbinde hilft im Sitzen.", "Schulterschmerz bekommen rund 75 % irgendwann, Spastik haben über 70 %, Schmerzen etwa 70 %.", "Knochen: Abbau etwa 4 % pro Monat im ersten Jahr, Lebenszeitrisiko für Frakturen 25–50 %, meist am Knie. Vorsicht beim Stehen und kräftigen Dehnen.", "[[Heterotope Ossifikation|ho]] meist an der Hüfte, 3–12 Wochen nach dem Trauma. Warmes, geschwollenes Bein oder Hüfte immer ärztlich abklären lassen (auch Thrombose)."], "merk": "Bei jedem Patienten ab Th6 aufwärts gehören Ausgangsblutdruck und Notfallablauf der autonomen Dysreflexie zur Grundausstattung."}]}, {"t": "7. Woran es sich je Höhe zu arbeiten lohnt", "b": [{"p": ["Keine Leitlinie gibt Empfehlungen getrennt nach Höhe. Die Bausteine kommen aus der deutschen S2e-Leitlinie 179-009 (DMGP, gültig bis 2029) und der internationalen Exercise-Guideline (Martin Ginis 2018). Die Zuordnung zu den Höhen ist eine klinische Ableitung."]}, {"tab": [["Kraft und Ausdauer", "Grad A. Fitness: 2x pro Woche 20 min Ausdauer plus 2x 3 Sätze je große Muskelgruppe. Herz und Stoffwechsel: 3x pro Woche 30 min."], ["Gelenkerhalt, Dehnen", "Grad A (Expertenkonsens), keine Standarddosis."], ["Stehen", "Grad B, 30 min 3x pro Woche über 12 Wochen."], ["FES-Cycling", "Grad B gegen Spastik und für Kraft, 30 min 3x pro Woche über 16 Wochen."], ["Gangtraining mit Gewichtsentlastung, Robotik", "Grad B, mindestens 20 Einheiten, 2–3x pro Woche. Manuelles Laufband nicht besser als konventionelle Physio, Robotik verbessert die Gehfunktion, nicht das Tempo."], ["Atemmuskeltraining", "Level 1 für die Atemmuskelfunktion, z. B. 2x täglich über 6 Wochen."], ["Rollstuhl-Skills-Training", "13 RCTs, deutlich bessere Skills, vor allem bei neuen Nutzern."]]}, {"tab": [["C1–C4", "Atmung und Abhusten, Gelenkerhalt, Kopf- und Nackenkontrolle, Stehtisch, passives oder FES-Cycling, Pflege anleiten lernen."], ["C5", "Deltoideus und Bizeps kräftigen, Rumpfbalance, Schienen, E-Rollstuhl. Beugekontraktur im Ellenbogen vorbeugen."], ["C6", "Handgelenksstrecker, Tenodesegriff, Brett-Transfer, Rollstuhl in der Ebene, Sitzbalance."], ["C7–T1", "Trizeps, Latissimus, Pectoralis für Transfers und Druckentlastung, Rampen und Bordsteine, Ausdauer."], ["T2–L2", "Schulterschutz (Rotatorenmanschette, Schulterblatt, Pectoralis dehnen), Handbike oder Armergometer, Rumpf, Stehen, FES."], ["L3–S5, AIS C/D", "Beinkraft, Gangtraining mit vielen Wiederholungen auf dem Boden, Orthesen, Balance und Sturzprävention."]]}, {"l": ["Mit einer Einheit pro Woche ist die Guideline-Dosis nicht zu schaffen. Ziel ist ein Heimprogramm, das der Patient jahrelang selbst trägt.", "Schulter schützen: lange, gleichmäßige Antriebszüge, Transfers auf gleicher Höhe, Außenrotatoren und Schulterblatt kräftigen.", "Messen mit [[SCIM III|scim]], [[WISCI II|wisci]], 10-m-Gehtest und 6-Minuten-Gehtest, Schulter mit WUSPI, Spastik mit MAS.", "Neu: Transkutane Rückenmarkstimulation (ARC-EX) verbesserte bei 72 % chronischer Tetraplegiker Arm- und Handfunktion, FDA-Freigabe 12/2024. In Deutschland keine Regelleistung."], "merk": "Am besten belegt sind die einfachen Dinge: Kraft, Ausdauer, Gelenkerhalt und Stehen. Die eigentliche Arbeit ist ein Programm, das der Patient selbst trägt, und eine Schulter, die Jahrzehnte hält."}]}], "quellen": ["ASIA/ISCoS: International Standards for Neurological Classification of SCI, Revision 2019 (Arbeitsblatt REV 04/2026)", "Kirshblum S: Neurological Assessment und SCI Rehab, ASCIP 2023", "Consortium for Spinal Cord Medicine/PVA: Outcomes Following Traumatic SCI, 1999 und 2. Aufl. 2026", "AWMF S3-Leitlinie 030-070 Diagnostik und Therapie der akuten Querschnittlähmung, 2025", "AWMF S2e-Leitlinie 179-009 Rehabilitation untere Extremität, Steh- und Gehfunktion bei Querschnittlähmung, 2024 (gültig bis 07/2029)", "AWMF S2k-Leitlinie 179-014 Lebenslange Nachsorge bei Querschnittlähmung, 2022", "DMGP: Empfehlungen zur Diagnoseformulierung bei Querschnittlähmung; ParaReg 2023", "Consortium for Spinal Cord Medicine: Autonomic Dysreflexia, CPG 2020", "Martin Ginis KA et al.: Evidence-based scientific exercise guidelines for adults with SCI. Spinal Cord 2018", "van Middendorp JJ et al.: A clinical prediction rule for ambulation outcomes after traumatic SCI. Lancet 2011", "Marino RJ et al.: Upper- and lower-extremity motor recovery after traumatic cervical SCI. Arch Phys Med Rehabil 2011", "Arroyo-Fernández R et al.: Body weight-supported gait training in incomplete SCI, Meta-Analyse. J Clin Med 2024", "Moritz C et al.: Non-invasive spinal cord electrical stimulation for arm and hand function (Up-LIFT). Nat Med 2024", "SCIRE Project: Predictors of Walking, Respiratory Muscle Training, Exercise Guidelines"], "fragen": [["Was macht eine Querschnittlähmung nach ISNCSCI zur kompletten Lähmung (AIS A)?", ["Keine Beinmotorik", "Keine willkürliche Analkontraktion, kein tiefes anales Druckempfinden, S4-5 ohne Sensibilität", "Keine Sensibilität unterhalb des Bauchnabels", "Kraftgrad 0 in allen Kennmuskeln"], 1, "Komplett ist ausschließlich über die sakralen Segmente definiert. Jede erhaltene Funktion in S4-5 macht die Läsion inkomplett."], ["Welcher Kennmuskel gehört zu C6?", ["Ellenbogenflexoren", "Handgelenksextensoren", "Ellenbogenextensoren", "Fingerflexoren"], 1, "C5 Ellenbogenflexoren, C6 Handgelenksextensoren, C7 Ellenbogenextensoren, C8 Fingerflexoren."], ["Was unterscheidet AIS C von AIS D?", ["Ob die Läsion zervikal oder thorakal ist", "Ob mindestens die Hälfte der Kennmuskeln unter dem NLI Kraftgrad 3 oder mehr hat", "Ob der Patient sitzen kann", "Ob Sensibilität sakral erhalten ist"], 1, "Beide sind motorisch inkomplett. Bei D hat mindestens die Hälfte der Kennmuskeln unterhalb des NLI Kraftgrad 3 oder mehr, bei C weniger."], ["Welche Höhe ist mit 4 markiert?", ["Th12", "L3", "S1", "C7"], 1, "L3 versorgt den Quadrizeps. Ab hier wird Gehen außer Haus realistisch.", "fortbildung/bilder/2026-W47/qs-niveaus.webp"], ["Welche Läsionshöhe gilt als Schlüsselhöhe für Selbstständigkeit auf Rollstuhlebene?", ["C5", "C6", "C7", "Th6"], 2, "Mit dem Trizeps (C7) werden Transfers und Druckentlastung selbstständig möglich."], ["Was ist auf dem Bild zu sehen?", ["Aktiver Faustschluss", "Tenodesegriff", "Spastischer Beugetonus", "Krallenhand"], 1, "Das gestreckte Handgelenk zieht die gelähmten Fingerbeuger passiv an, die Finger schließen sich um den Becher.", "fortbildung/bilder/2026-W47/qs-tenodese.webp"], ["Was solltest du bei einem Patienten mit C6-Läsion vermeiden?", ["Kräftigung der Handgelenksstrecker", "Fingerbeuger bei gestrecktem Handgelenk voll dehnen", "Sitzbalance üben", "Rutschbrett-Transfer üben"], 1, "Eine leichte Verkürzung der Fingerbeuger macht den Tenodesegriff kräftiger. Volles Dehnen bei gestrecktem Handgelenk zerstört ihn."], ["Welches Syndrom zeigt die 1?", ["Brown-Séquard", "Anteriores Syndrom", "Zentrales Rückenmarksyndrom", "Konus-Syndrom"], 2, "Der Schaden liegt um den Zentralkanal. Die Arme sind stärker betroffen als die Beine, oft bei Älteren nach Sturz mit Überstreckung.", "fortbildung/bilder/2026-W47/qs-syndrome.webp"], ["Welches Syndrom hat die beste Gehprognose?", ["Anteriores Syndrom", "Brown-Séquard", "Posteriores Syndrom", "Komplette Läsion C5"], 1, "Beim Brown-Séquard gehen 75–90 % bei Reha-Entlassung selbstständig."], ["Welcher Befund verbessert bei AIS B die Gehprognose am deutlichsten?", ["Erhaltener Nadelstich sakral oder in den Beinen", "Junges Alter allein", "Erhaltene Reflexe", "Hohe Läsion"], 0, "Mit erhaltenem Nadelstich gehen später 33–89 %, ohne kaum jemand."], ["Was zeigt die 4 als häufigsten Auslöser?", ["Volle Harnblase", "Volle Gallenblase", "Leistenhernie", "Darmverschluss"], 0, "Volle Blase oder abgeknickter Katheter sind die häufigsten Auslöser der autonomen Dysreflexie, danach der volle Darm.", "fortbildung/bilder/2026-W47/qs-dysreflexie.webp"], ["Patient C6, plötzlich starker Kopfschmerz und Schwitzen im Gesicht. Was tust du zuerst?", ["Hinlegen und Beine hochlagern", "Aufsetzen, Beine runter, Enges lösen, RR messen, Blase prüfen", "Weitertrainieren und beobachten", "Kühlpack in den Nacken"], 1, "Das ist eine autonome Dysreflexie. Aufrecht sitzen senkt den Blutdruck, dann Auslöser suchen. Ab 150 mmHg systolisch oder ohne gefundene Ursache ärztlich."], ["Welche Dosis empfiehlt die SCI-Exercise-Guideline für Herz und Stoffwechsel?", ["1x pro Woche 60 min", "3x pro Woche 30 min moderat bis intensiv", "Täglich 10 min", "2x pro Woche 10 min"], 1, "Für Fitness reichen 2x 20 min plus Kraft 2x 3 Sätze, für die kardiometabolische Gesundheit braucht es 3x 30 min."], ["Was zeigt die Metaanalyse 2024 zum Gangtraining bei AIS C/D?", ["Manuelles Laufband ist allem überlegen", "Gewichtsentlastetes Gangtraining ist insgesamt nicht besser als konventionelle Physio, Robotik verbessert die Gehfunktion", "Robotik macht schneller", "Gangtraining schadet"], 1, "Nur Robotik verbesserte Gehfunktion und Balance, nicht das Tempo. Vieles Gehen auf dem Boden bleibt eine gute Wahl."]], "info": {"nli": {"t": "Neurologisches Niveau (NLI)", "x": ["Das tiefste Segment, in dem auf beiden Seiten die Sensibilität intakt ist und die Kennmuskeln mindestens Kraftgrad 3 erreichen, während alles darüber normal ist.", "Bestimmt werden zuerst vier Einzelwerte: sensibles und motorisches Niveau, jeweils rechts und links. Das NLI ist der höchste dieser vier. Das motorische Niveau einer Seite kann also tiefer liegen, und für die Ziele der Hand lohnt der Blick auf jede Seite einzeln."]}, "zpp": {"t": "Zone des Teilerhalts (ZPP)", "x": ["Segmente unterhalb des sensiblen oder motorischen Niveaus, in denen noch etwas Funktion erhalten ist. Notiert wird das tiefste Segment mit Restfunktion, getrennt für rechts, links, Motorik und Sensibilität.", "Seit der Revision 2019 gilt die ZPP nicht mehr nur bei AIS A. Die motorische wird immer angegeben, wenn die willkürliche Analkontraktion fehlt, also auch bei AIS B und manchen C- und D-Fällen. Die sensible nur, wenn tiefer analer Druck sowie Berührung und Nadelstich in S4-5 fehlen. Sonst steht im Bogen NA."], "q": "ISNCSCI Revision 2019; Spinal Cord 2024 zur ZPP"}, "dysreflexie": {"t": "Autonome Dysreflexie: was dahintersteckt", "x": ["Ein Reiz unterhalb der Läsion, etwa eine volle Blase, löst dort eine ungebremste Sympathikusreaktion aus. Die Gefäße im Bauchraum und in den Beinen ziehen sich zusammen, der Blutdruck steigt.", "Das Gehirn merkt das und will gegensteuern, die Signale kommen aber nicht unter die Läsion. Übrig bleiben Gefäßweitstellung oberhalb (Rötung, Schwitzen, Kopfschmerz) und oft ein langsamer Puls.", "Ab Th6 hängt das große Gefäßgebiet im Bauchraum an der ungebremsten Seite, deshalb gilt diese Grenze."]}, "saugblas": {"t": "Saug-Blas-Steuerung", "x": ["Steuerung über ein Röhrchen am Mund (englisch sip and puff). Kräftiges oder leichtes Pusten und Saugen ergeben unterschiedliche Befehle, etwa vorwärts, rückwärts, links und rechts.", "Gedacht für hohe Tetraplegie, wenn weder Hand noch Kinn einen Joystick sicher bedienen. Oft lassen sich darüber auch Umfeldsteuerung, Telefon oder Computer bedienen."]}, "nadelstich": {"t": "Warum der Nadelstich zählt", "x": ["Spitz-Stumpf-Empfinden läuft über den Tractus spinothalamicus im Vorderseitenstrang. Der liegt nah an den motorischen Bahnen. Ist der Nadelstich unter der Läsion erhalten, sind wahrscheinlich auch motorische Fasern teilweise verschont.", "Leichte Berührung läuft zusätzlich über die Hinterstränge, die weiter hinten liegen. Erhaltene Berührung allein sagt deshalb weniger über die spätere Kraft."]}, "ho": {"t": "Heterotope Ossifikation (HO)", "x": ["Knochenbildung im Weichteilgewebe um ein Gelenk, immer unterhalb der Läsion. Die Angaben zur Häufigkeit nach Querschnitt schwanken stark, zwischen 10 und 78 %.", "Frühe Zeichen sind unspezifisch: Schwellung, Wärme, manchmal leichtes Fieber und vor allem neu abnehmende Beweglichkeit. Schmerz kann fehlen. Früh zeigen Knochenszintigrafie oder Ultraschall die HO, das Röntgen erst Wochen später.", "Früh gegebene NSAR senkten in Studien die Rate. Ein steifes Hüftgelenk stört Sitzen und Transfers, deshalb das Bewegungsausmaß bei jedem Termin vergleichen."], "q": "SCIRE Project, Heterotopic Ossification"}, "scim": {"t": "SCIM III", "x": ["Spinal Cord Independence Measure, speziell für Querschnitt. 19 Aufgaben, Gesamtwert 0–100: Selbstversorgung 0–20, Atmung und Blasen-Darm-Management 0–40, Mobilität 0–40.", "Anders als allgemeine Alltagsskalen erfasst er auch Druckentlastung, Transfers in den Rollstuhl und Fortbewegung im Rollstuhl. Als klinisch relevant gilt eine Änderung um etwa 4 Punkte im Gesamtwert."], "q": "SCIRE Project; Scivoletto et al. 2013 (MCID)"}, "wisci": {"t": "WISCI II", "x": ["Walking Index for Spinal Cord Injury mit 21 Stufen: von 0 (kann nicht stehen oder am begleiteten Gehen teilnehmen) bis 20 (geht 10 m ohne Hilfsmittel, Orthesen und Hilfe).", "Bewertet wird, mit wie viel Hilfe, welchen Orthesen und welchen Gehhilfen jemand 10 m sicher schafft. Viele erreichen schnell die Höchststufe. Für Fortschritte bei guten Gehern taugen 10-m-Gehtest und 6-Minuten-Gehtest besser."], "q": "SCIRE Project, WISCI II"}}}, {"id": "w47-sw", "titel": "Schwindel: einordnen, testen, behandeln", "art": "kb", "kb": "NE07", "min": 14, "bild": "fortbildung/bilder/2026-W47/sw-bogengaenge.webp", "abschnitte": [{"t": "Was steckt hinter dem Schwindel?", "b": [{"bars": [["Funktioneller Schwindel (PPPD)", 17.3, "17,3 %"], ["Lagerungsschwindel (BPPV)", 13.3, "13,3 %"], ["Vestibuläre Migräne", 12.4, "12,4 %"], ["Morbus Menière", 10.1, "10,1 %"], ["Einseitige Vestibulopathie", 9.1, "9,1 %"], ["Beidseitige Vestibulopathie", 6.6, "6,6 %"]], "p": ["Häufigste Diagnosen im Schwindelzentrum der LMU München (n = 37.328). In der Hausarztpraxis macht BPPV bis zu 20 % aus, bei Älteren ist die Ursache oft gar nicht vestibulär, sondern kardiovaskulär."]}]}, {"t": "1. Drei Fragen sortieren fast jeden Schwindel", "b": [{"p": ["Wie lange dauert er? Was löst ihn aus? Gibt es Ohr- oder Neurozeichen? Damit landet ein Patient in einer der Gruppen der Bárány Society: akut (Dauerschwindel über 24 Stunden), episodisch getriggert, episodisch spontan oder chronisch. Jede Gruppe hat ein harmloses und ein gefährliches Paar: Neuritis gegen Schlaganfall, BPPV gegen Läsion der hinteren Schädelgrube, vestibuläre Migräne gegen TIA."]}, {"tab": [["BPPV", "Unter 1 min, bei Lagewechsel (Umdrehen im Bett, Bücken, Hochschauen). Keine Ohrsymptome."], ["Neuritis vestibularis", "Dauerschwindel über Tage, spontan, kein Hörverlust. Früh trainieren."], ["Morbus Menière", "20 min bis 12 h, spontan, mit Hörminderung, Tinnitus, Ohrdruck."], ["Vestibuläre Migräne", "5 min bis 72 h, Migräne in der Vorgeschichte, Kopfschmerz nur bei etwa zwei Dritteln."], ["[[Vestibularisparoxysmie|vparox]]", "Sekunden bis 1 min, bis zu 100-mal am Tag. Ärztlich behandeln."], ["Beidseitige Vestibulopathie", "Dauernd unsicher beim Gehen, schlimmer im Dunkeln, Oszillopsien. Im Sitzen und Liegen beschwerdefrei."], ["PPPD", "Mindestens 3 Monate an den meisten Tagen, schlimmer aufrecht, bei Bewegung und unruhigen Bildern, besser bei Sport oder Ablenkung."], ["Orthostatisch", "Sekunden bis Minuten nach dem Aufstehen. [[Schellong|schellong]]: Abfall über 20/10 mmHg."], ["Zervikogen", "Mit Nackenschmerz und Nackenbewegung. Ausschlussdiagnose ohne verlässlichen Test."]], "merk": "Bei jedem Schwindel die Medikamentenliste anschauen: Blutdrucksenker, Diuretika, Benzodiazepine, Antidepressiva und Opioide können ihn auslösen."}]}, {"t": "2. Warnzeichen: wann die Physio aufhört", "b": [{"l": ["Schwindel kann das einzige Zeichen eines Schlaganfalls sein (DEGAM 2025). Neuer Dauerschwindel über 24 Stunden mit Spontannystagmus oder Gangunfähigkeit wird zuerst ärztlich abgeklärt.", "5 D und 3 N: Dizziness, Diplopie, Dysarthrie, Dysphagie, Drop Attacks; Nystagmus in Ruhe, Nausea, Numbness um Mund oder Nase.", "Schwindel mit plötzlicher Hörminderung und Kopfschmerz, Sehstörung oder Schwäche: [[AICA-Infarkt|aica]] möglich, sofort einweisen.", "Beim Lagerungstest: Downbeat-Nystagmus ohne Latenz, nicht ermüdbar, gleiche Richtung in mehreren Lagen spricht für zentral.", "Dissektion der Halsarterie: unter 55, plötzlicher ungewohnter Kopf- oder Nackenschmerz nach Bagatelltrauma, Horner-Syndrom, neue Neurozeichen. Sofort Notaufnahme."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/sw-kopfimpuls.webp", "t": "Kopfimpulstest.", "c": "Der Patient fixiert die Nase des Therapeuten, der Kopf wird schnell um etwa 15° gedreht. Bei einseitiger Unterfunktion bleiben die Augen nicht auf dem Ziel und es folgt eine Korrektursakkade. Teil des HINTS, den die DEGAM in der Hand geschulter Ärzte sieht."}]}, {"p": ["KI-erstellte Lehrbilder nach typischen Lehrbuchfällen, geprüft, keine echten Aufnahmen."]}, {"tab": [["Eher peripher", "Horizontal-torsionell in eine Richtung, Fixation unterdrückt ihn, Kopfimpulstest pathologisch, Lagenystagmus mit Latenz und ermüdbar."], ["Eher zentral", "Rein vertikal oder richtungswechselnd, nicht durch Fixation unterdrückbar, Kopfimpulstest normal trotz akutem Nystagmus, Skew vorhanden."]], "merk": "Ein normaler Kopfimpulstest bei akutem Dauerschwindel mit Nystagmus ist verdächtig, nicht beruhigend.", "p": ["[[HINTS|hints]] (Kopfimpuls, Nystagmus, Skew) erreichte bei Neuro-Ophthalmologen 100 % Sensitivität, im Cochrane-Review 2023 über 12 Studien 94 % bei niedriger Evidenzsicherheit."]}]}, {"t": "3. Lagerungsschwindel erkennen", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W47/sw-bogengaenge.webp", "t": "Rechtes Labyrinth von lateral.", "c": "1 hinterer Bogengang mit losen Otolithen, 2 horizontaler Bogengang, 3 vorderer Bogengang, 4 Utriculus mit Otolithenmembran, von hier lösen sich die Kristalle. Der hintere Bogengang liegt im Stehen und Liegen am tiefsten, deshalb sammeln sich die Kristalle dort am häufigsten."}]}, {"tab": [["Hinterer Bogengang (80–95 %)", "Dix-Hallpike. Torsionell und aufwärts schlagend zum unten liegenden Ohr, Latenz 5–20 s, unter 60 s, ermüdbar. Betroffen ist das unten liegende Ohr."], ["Horizontal, [[geotrop|geotrop]]", "[[Supine Roll|supineroll]]. Horizontal zum unten liegenden Ohr, etwa 1 min. Betroffen ist die Seite mit dem stärkeren Nystagmus."], ["Horizontal, apogeotrop", "Supine Roll. Horizontal zum oben liegenden Ohr, oft über 1 min. Betroffen ist die Seite mit dem schwächeren Nystagmus."], ["Vorderer Bogengang (1–4 %)", "Dix-Hallpike oder tiefe Kopfhängelage. Vorwiegend abwärts schlagend. Immer gegen zentralen Downbeat abgrenzen."]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/sw-dixhallpike.webp", "t": "Dix-Hallpike rechts.", "c": "Kopf 45° zum Testohr gedreht, dann rasch in Rückenlage, der Kopf hängt 20–30° unter der Horizontalen. Mindestens 30 s halten und die Augen beobachten. Ist der Test negativ, die Gegenseite testen."}]}, {"l": ["Kanalolithiasis: Latenz von Sekunden, unter 1 min, ermüdbar. Kupulolithiasis: praktisch ohne Latenz, über 1 min, nicht ermüdbar.", "Den Test nicht wiederholen, nur um die Ermüdbarkeit zu prüfen.", "Verträgt jemand keine HWS-Extension: Side-lying-Test, Kissen unter die Schultern (Sensitivität 95,5 %) oder Log-Roll statt Kopfdrehung.", "Vorsicht bei zervikaler Stenose, rheumatoider Arthritis, M. Bechterew, Radikulopathie, schwerer Gefäßerkrankung, vertebrobasilärer Insuffizienz.", "39 % der Patienten in Sturzambulanzen haben einen BPPV, ein Viertel davon ohne Schwindelangabe."], "merk": "Latenz, Dauer und Richtung des Nystagmus verraten den Bogengang. Ohne Nystagmus kein sicherer BPPV."}]}, {"t": "4. Manöver, Erfolg und Rückfälle", "b": [{"tab": [["Epley 1", "Sitz, Kopf 45° zur betroffenen Seite."], ["Epley 2", "Rasch in Rückenlage, Kopf hängt 20–30° über das Liegenende, Drehung bleibt. Halten, bis Nystagmus und Schwindel abklingen."], ["Epley 3", "Kopf um 90° zur gesunden Seite drehen, weiter leicht überstreckt. Halten."], ["Epley 4", "Mit dem Körper auf die gesunde Seite rollen, Kopf weitere 90°, Nase schräg zum Boden. Halten, dann seitlich aufsetzen."], ["Semont/SémontPLUS", "Kopf 45° zur gesunden Seite, rasch auf die betroffene Seite legen (bei SémontPLUS 60° und mehr unter die Horizontale), dann in einem Schwung auf die andere Seite."], ["Horizontal geotrop", "[[BBQ-Rotation|bbq]] (90°-Schritte), Gufoni auf die gesunde Seite mit Gesicht zum Boden oder 12 h Seitenlage auf dem gesunden Ohr."], ["Horizontal apogeotrop", "Erst lösen (Kopfschütteln, Mastoidvibration), dann Gufoni-Variante."], ["Vorderer Kanal", "Yacovino: tiefe Kopfhängelage, dann Kinn zur Brust, dann Sitz."]], "p": ["Haltezeiten je Quelle 20–30 s (AAO-HNS) bis 1–2 min oder bis der Nystagmus abgeklungen ist."]}, {"l": ["Epley und Semont sind gleichwertig (Cochrane, OR 4,42 für Beschwerdefreiheit). SémontPLUS war in zwei RCTs schneller (im Median 1 statt 2 Tage). DEGAM: über 90 % primärer Erfolg.", "1–2 Manöver reichen bei 79–93 %. Nach drei erfolglosen Manövern zum Spezialisten.", "[[Brandt-Daroff|brandtdaroff]] ist deutlich schwächer (25 % gegen 80 % nach 7 Tagen) und bei Älteren nicht erste Wahl.", "Nach dem Manöver 60 s gesichert an der Bettkante sitzen lassen: Bei bis zu 10 % kommt es zu einer plötzlichen Sturzattacke.", "Keine Lagerungs- oder Bewegungsregeln danach nötig (AAO-HNS, starke Empfehlung).", "Selbstbehandlung laut DEGAM: Manöver 9-mal am Tag über 3 Tage, Kontrolle nach etwa 14 Tagen.", "Rückfälle: 34 % im ersten Jahr, 53 % nach mehr als zwei Jahren (DEGAM). Restschwindel bis zu 43 %, bei Älteren bleibt oft Unsicherheit."], "merk": "Ein gelöster BPPV ist kein abgeschlossener Fall: Selbstmanöver für den Rückfall und Gleichgewichtstraining für die Restunsicherheit gehören in den Abschluss."}]}, {"t": "5. Vestibuläre Reha richtig dosieren", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W47/sw-blickstabilisation.webp", "t": "Blickstabilisation (VOR x1).", "c": "Sie fixiert den Punkt auf der Karte und dreht den Kopf zügig hin und her, das Ziel muss scharf bleiben. Progression: nahes und fernes Ziel, dann VOR x2 (Karte bewegt sich gegenläufig), unruhiger Hintergrund, im Stand und Gehen."}]}, {"tab": [["Akut/subakut einseitig (z. B. Neuritis)", "Blickstabilisation mindestens 3x täglich, insgesamt mindestens 12 min am Tag."], ["Chronisch einseitig", "3–5x täglich, mindestens 20 min am Tag, 4–6 Wochen. Gleichgewicht mindestens 20 min am Tag."], ["Beidseitig", "3–5x täglich, 20–40 min am Tag, 5–7 Wochen. Gleichgewicht täglich 6–9 Wochen, Sturzprophylaxe lebenslang."]], "p": ["APTA/ANPT-Leitlinie 2022: vestibuläre Physiotherapie bei allen drei Gruppen Evidenzlevel I, Grad A, möglichst angeleitet. Sakkaden- und Folgebewegungen ohne Kopfbewegung zählen nicht als Blickstabilisation."]}, {"l": ["Cochrane 2015 (39 RCTs): Reha senkt den Schwindel deutlich (OR 2,67), Effekte halten 3–12 Monate. Keine Übungsform ist der anderen überlegen.", "Bei Restfunktion [[adaptieren|adaptation]] (VOR-Übungen), ohne Funktion substituieren (Augen, Propriozeption, Strategien).", "Mehr Schwindel und Übelkeit in den ersten 2–5 Wochen ist normal und kein Grund aufzuhören. Vorher sagen.", "Das Alter verschlechtert die Prognose nicht. Angst, Depression, Migräne, Neuropathie und Dauereinnahme von [[Antivertiginosa|antivertiginosa]] schon. DEGAM: sedierende Antivertiginosa höchstens 3 Tage."], "merk": "Die Wirkung kommt aus der Dosis: mehrmals täglich zu Hause. Eine Therapieeinheit pro Woche reicht nur zum Anleiten und Steigern."}]}, {"t": "6. Besondere Gruppen", "b": [{"tab": [["Neuritis", "Früh trainieren: Beginn in den ersten 2 Wochen verbessert den DHI nach 1 und 12 Monaten (Metaanalyse 2024). Bei anhaltenden Beschwerden Reha mindestens 4–6 Wochen (DEGAM)."], ["PPPD", "Aufklärung, langsam steigernde Habituation und visuelle Desensibilisierung, dazu Verhaltenstherapie und ggf. SSRI. Zu schnelles Steigern bremst. Meist 6–9 Monate."], ["Vestibuläre Migräne", "Nutzen laut DEGAM nicht durch RCTs belegt, neuere Metaanalyse positiv, aber sehr uneinheitlich. Vertretbar, Effekt offen."], ["Menière", "Physio außerhalb der Attacken bei bleibendem Defizit."], ["Zervikogen", "Erst alles andere ausschließen. [[SNAGs|snags]]: 6 symptomfreie Wiederholungen, 2–6 Termine über 6 Wochen, Selbst-SNAG täglich 6x (Reid 2014). Keine Manipulation."], ["Ältere und Stürze", "Balance- und Krafttraining senkt Stürze um 23 %. Physio in den ersten 3 Monaten nach Schwindelbeginn senkt Stürze mit Verletzung."]]}, {"merk": "Bei PPPD heißt die Regel: langsam steigern und dranbleiben. Bei Neuritis: früh anfangen."}]}, {"t": "7. Messen und verordnen", "b": [{"tab": [["DHI", "Beeinträchtigung, 0–100. Klinisch relevant: Abnahme um mindestens 18 Punkte."], ["ABC-Skala", "Sicherheit im Alltag, 0–100 %. MCID 10 Punkte, unter 67 % erhöhtes Sturzrisiko."], ["FGA", "Gang, 0–30. MCID 4 Punkte, unter 22 erhöhtes Sturzrisiko."], ["Mini-BESTest", "Gleichgewicht, 0–28. MCID 4 Punkte."], ["VVAS", "Visuell ausgelöster Schwindel, 0–100. MCID 9 Punkte, gut bei PPPD."]], "p": ["Werte über eine Übersichtsquelle belegt, die Originale nennt. DGI-, DVA- und DHI-Schweregrad-Grenzen sind verbreitet, aber hier nicht geprüft."]}, {"l": ["Leitlinie: DEGAM S2k „Schwindel in der Hausarztpraxis“ (AWMF 053-018, Stand 02/2025, Revision 2030). Ärzte sollen BPPV selbst lagern oder an Physiotherapeuten überweisen, die die Manöver beherrschen (starker Konsens).", "Heilmittel: H81.-, H82, R42, R26.0–R26.2 und R29.6 stehen ab dem vollendeten 70. Lebensjahr auf der [[Diagnoseliste|diagnoseliste]] (Gruppen WS, EX, SO3)."], "merk": "Gute Doku bei Schwindel: Dauer, Auslöser, Ohr- und Neurozeichen, Testergebnis mit Seite und Nystagmus, Manöver, DHI zu Beginn und am Ende."}]}], "quellen": ["DEGAM S2k-Leitlinie Schwindel in der Hausarztpraxis, AWMF 053-018, Stand 02/2025 (Revision geplant 02/2030)", "Bhattacharyya N et al.: Clinical Practice Guideline: Benign Paroxysmal Positional Vertigo (Update). AAO-HNS 2017", "Hilton MP, Pinder DK: The Epley manoeuvre for BPPV. Cochrane CD003162, 2014", "Strupp M et al.: SémontPLUS vs. Semont und Epley, RCTs 2021/2023", "Hall CD et al.: Vestibular Rehabilitation for Peripheral Vestibular Hypofunction, Clinical Practice Guideline Update. J Neurol Phys Ther 2022", "McDonnell MN, Hillier SL: Vestibular rehabilitation for unilateral peripheral vestibular dysfunction. Cochrane CD005397, 2015", "Agger-Nielsen S et al.: Early vestibular rehabilitation in vestibular neuritis, Metaanalyse. Front Neurol 2024", "Cochrane 2023: HINTS for acute vestibular syndrome (CD015089)", "Bárány Society: Kriterien BPPV (2015), Menière, vestibuläre Migräne, PPPD (2017), bilaterale Vestibulopathie", "Reid SA et al.: SNAGs und Maitland-Mobilisation bei zervikogenem Schwindel. Man Ther 2014", "Cox J, Frith J: BPPV bei älteren Menschen. Age and Ageing 2025", "Australian Physiotherapy Association: VBI/Dissektion Factsheet 2025", "LMU Klinikum, Deutsches Schwindel- und Gleichgewichtszentrum: Häufigste Diagnosen", "KBV Heilmittel-Diagnoseliste, Stand 01.01.2026"], "fragen": [["Welche drei Fragen sortieren Schwindel am besten?", ["Alter, Geschlecht, Gewicht", "Dauer, Auslöser, Ohr- oder Neurozeichen", "Blutdruck, Puls, Atmung", "Seit wann, wie stark, wo"], 1, "Damit landet der Schwindel in einer der Bárány-Gruppen, und jede Gruppe sagt, welche gefährliche Ursache ausgeschlossen sein muss."], ["Attacken von 2 Stunden mit Ohrdruck, Tinnitus und schwankendem Hören passen am ehesten zu …", ["BPPV", "Morbus Menière", "Neuritis vestibularis", "PPPD"], 1, "Menière: spontane Attacken von 20 min bis 12 h mit Tief- bis Mitteltonschwerhörigkeit, Tinnitus und Ohrdruck."], ["Welcher Befund spricht bei akutem Dauerschwindel für eine zentrale Ursache?", ["Pathologischer Kopfimpulstest", "Normaler Kopfimpulstest bei Spontannystagmus", "Nystagmus wird durch Fixation unterdrückt", "Horizontal-torsioneller Nystagmus in eine Richtung"], 1, "Ein normaler Kopfimpulstest trotz akutem Nystagmus ist verdächtig für einen Schlaganfall."], ["Welcher Test ist auf dem Bild zu sehen?", ["Dix-Hallpike", "Kopfimpulstest", "Romberg", "Cover-Test"], 1, "Schnelle kleine Kopfdrehung, der Patient fixiert die Nase des Therapeuten. Bei Unterfunktion folgt eine Korrektursakkade.", "fortbildung/bilder/2026-W47/sw-kopfimpuls.webp"], ["Was ist mit der 1 markiert?", ["Horizontaler Bogengang", "Hinterer Bogengang mit losen Otolithen", "Schnecke", "Utriculus"], 1, "Der hintere Bogengang liegt am tiefsten. Dort sammeln sich die Kristalle bei 80–95 % aller BPPV.", "fortbildung/bilder/2026-W47/sw-bogengaenge.webp"], ["Wo gehören die Otolithen eigentlich hin?", ["In den hinteren Bogengang", "Auf die Otolithenmembran im Utriculus (4)", "In die Schnecke", "In den Gleichgewichtsnerv"], 1, "Die Kristalle lösen sich vom Utriculus und gelangen in einen Bogengang. Die Manöver bringen sie zurück in den Vorhof.", "fortbildung/bilder/2026-W47/sw-bogengaenge.webp"], ["Welcher Nystagmus passt zum BPPV des hinteren Bogengangs rechts im Dix-Hallpike?", ["Rein horizontal zum oben liegenden Ohr", "Torsionell und aufwärts schlagend zum rechten Ohr, Latenz einige Sekunden, unter 60 s", "Rein abwärts schlagend ohne Latenz", "Kein Nystagmus, nur Übelkeit"], 1, "Latenz, kurze Dauer und Ermüdbarkeit sprechen für Kanalolithiasis im hinteren Bogengang."], ["Wie lange hält man die Testposition beim Dix-Hallpike mindestens?", ["5 Sekunden", "30 Sekunden", "5 Minuten", "So lange, bis der Patient sich aufsetzt"], 1, "Mindestens 30 s, weil die Latenz bis zu einer Minute dauern kann. Negativ: Gegenseite testen.", "fortbildung/bilder/2026-W47/sw-dixhallpike.webp"], ["Supine Roll, geotroper Nystagmus beidseits, links stärker. Welche Seite ist betroffen?", ["Rechts", "Links", "Beide", "Nicht bestimmbar"], 1, "Bei der geotropen Form ist die Seite mit dem stärkeren Nystagmus die betroffene. Bei der apogeotropen ist es umgekehrt."], ["Was gilt nach einem erfolgreichen Befreiungsmanöver?", ["Zwei Nächte aufrecht schlafen", "Keine Lagerungsregeln nötig, aber 60 s gesichert sitzen lassen", "Eine Woche Halskrause", "Kopf nicht nach links drehen"], 1, "Die AAO-HNS rät stark von Einschränkungen ab. Wegen möglicher Sturzattacken den Patienten kurz sichern."], ["Welches Manöver ist beim hinteren Bogengang am schwächsten?", ["Epley", "Semont", "SémontPLUS", "Brandt-Daroff"], 3, "Nach 7 Tagen waren nach Brandt-Daroff 25 %, nach Repositionsmanövern 80 % frei."], ["Was zeigt das Bild?", ["Sakkadentraining ohne Kopfbewegung", "Blickstabilisation (VOR x1)", "Konvergenztraining", "Optokinetische Stimulation"], 1, "Ziel fixieren, Kopf bewegen. Sakkaden ohne Kopfbewegung zählen laut Leitlinie nicht als Blickstabilisation.", "fortbildung/bilder/2026-W47/sw-blickstabilisation.webp"], ["Welche Dosis empfiehlt die APTA-Leitlinie bei chronischer einseitiger Unterfunktion?", ["1x pro Woche in der Praxis", "3–5x täglich, mindestens 20 min am Tag, 4–6 Wochen", "Täglich 5 min über eine Woche", "Nur bei Beschwerden"], 1, "Die Wirkung kommt aus dem täglichen Heimprogramm, die Praxis leitet an und steigert."], ["Wie reagierst du, wenn der Schwindel in den ersten Trainingswochen stärker wird?", ["Sofort abbrechen", "Erklären, dass das in 2–5 Wochen meist abklingt, Dosis anpassen", "Antivertiginosa dauerhaft empfehlen", "Nur noch passiv behandeln"], 1, "Vorübergehend mehr Symptome sind laut Leitlinie normal und allein kein Abbruchgrund."]], "info": {"vparox": {"t": "Vestibularisparoxysmie", "x": ["Ursache ist meist ein Gefäß, das den Hör- und Gleichgewichtsnerv im Kleinhirnbrückenwinkel berührt und reizt, am häufigsten die AICA.", "Kriterien: mindestens 10 spontane Attacken, jeweils unter 1 Minute, beim selben Patienten immer gleich, und Besserung unter Carbamazepin oder Oxcarbazepin. Oft sichert erst dieser Medikamentenversuch die Diagnose.", "Für die Physio heißt das: kurze Spontanattacken ohne Lageauslöser nicht als BPPV behandeln, sondern ärztlich vorstellen."], "q": "Bárány Society, Kriterien Vestibularisparoxysmie"}, "schellong": {"t": "Schellong-Test", "x": ["Einfacher Kreislauftest: erst einige Minuten liegen, dann aufstehen und im Stehen Blutdruck und Puls wiederholt messen, üblich sind 10 Minuten.", "Fällt der Blutdruck, ohne dass der Puls deutlich steigt, spricht das eher für eine neurogene Ursache oder Medikamente. Steigt der Puls stark ohne Blutdruckabfall, denkt man an ein posturales Tachykardiesyndrom (POTS)."]}, "aica": {"t": "AICA-Infarkt", "x": ["Die A. cerebelli inferior anterior versorgt Teile von Kleinhirn und Hirnstamm und gibt meist auch die Arterie zum Innenohr ab. Ein Verschluss kann deshalb Hörsturz und Drehschwindel gleichzeitig auslösen.", "Die Falle: Das Bild wirkt peripher, und der Kopfimpulstest kann pathologisch sein, weil das Innenohr selbst betroffen ist. Neue Hörminderung bei akutem Schwindel ist deshalb ein Warnzeichen und keine Beruhigung."]}, "hints": {"t": "HINTS", "x": ["Drei Tests am Patienten für das akute vestibuläre Syndrom, also nur bei anhaltendem Schwindel mit Nystagmus. Bei Attacken oder Lagerungsschwindel sagt er nichts.", "Zentral verdächtig ist schon ein einziger Befund: normaler Kopfimpulstest, richtungswechselnder Nystagmus oder vertikaler Versatz der Augen beim abwechselnden Abdecken (Skew). Englische Merkhilfe: INFARCT.", "Mit zusätzlichem Hörtest heißt er HINTS plus und erfasst so auch AICA-Infarkte besser."], "q": "Kattah et al., Stroke 2009"}, "supineroll": {"t": "Supine-Roll-Test", "x": ["Test für den horizontalen Bogengang: Rückenlage, Kopf leicht angehoben (etwa 30°), dann den Kopf zügig um 90° zu einer Seite drehen und die Augen beobachten. Zurück zur Mitte, dann zur anderen Seite.", "Ein horizontaler Nystagmus tritt meist auf beiden Seiten auf. Deshalb vergleicht man die Stärke rechts und links und achtet darauf, ob er zum Boden oder zur Decke schlägt."]}, "geotrop": {"t": "Geotrop und apogeotrop", "x": ["Geotrop heißt: Der Nystagmus schlägt zum Boden, also zum jeweils unten liegenden Ohr. Apogeotrop heißt: Er schlägt zur Decke.", "Geotrop spricht für frei bewegliche Kristalle im Bogengang, apogeotrop eher für Kristalle an der Cupula oder im vorderen Kanalabschnitt. Apogeotrope Formen sind hartnäckiger und werden oft erst in eine geotrope Form überführt."]}, "bbq": {"t": "BBQ-Rotation (Lempert)", "x": ["Start in Rückenlage mit dem Kopf zur betroffenen Seite. Dann in 90°-Schritten zur gesunden Seite weiterdrehen: Gesicht nach oben, auf der gesunden Seite liegen, Bauchlage mit Gesicht zum Boden, dann aufsetzen.", "Jede Position halten, bis Schwindel und Nystagmus abgeklungen sind. Wer sich schlecht drehen kann, braucht Hilfe beim Umlagern oder nimmt eine der anderen Varianten."]}, "brandtdaroff": {"t": "Brandt-Daroff-Übungen", "x": ["Selbstübung: auf der Bettkante sitzen, Kopf 45° drehen und sich rasch auf die Seite legen, so dass das Gesicht schräg nach oben schaut. 30 Sekunden bleiben oder bis der Schwindel abklingt, aufsetzen, dann zur anderen Seite.", "Üblich sind 5 Durchgänge, 3-mal täglich über 2 Wochen. Sinnvoll als Heimprogramm, wenn ein Manöver nicht vertragen wird."], "q": "Patienteninformation NHS (United Lincolnshire Hospitals)"}, "adaptation": {"t": "Adaptation, Substitution, Habituation", "x": ["Adaptation: Das Gehirn stellt den vestibulookulären Reflex neu ein. Der Reiz dafür ist ein leicht verwackeltes Bild bei Kopfbewegung, deshalb die VOR-Übungen.", "Substitution: Fehlt die Funktion ganz, übernehmen andere Systeme, etwa vorgezogene Augenbewegungen, das Sehen und die Fußsohlen.", "Habituation: wiederholte, dosierte Konfrontation mit dem auslösenden Reiz, bis er weniger Schwindel macht. Das ist der Weg bei PPPD und bewegungsprovoziertem Schwindel."]}, "antivertiginosa": {"t": "Antivertiginosa", "x": ["Mittel gegen Schwindel und Übelkeit, etwa Dimenhydrinat (Vomex) oder Benzodiazepine. Sie dämpfen die Signale aus dem Gleichgewichtssystem.", "Genau diese Signale braucht das Gehirn aber, um einen Ausfall auszugleichen. Über Tage hinaus genommen, verzögern sie deshalb die Kompensation. In der Reha lohnt die Frage, was der Patient gerade einnimmt."]}, "snags": {"t": "SNAGs", "x": ["Sustained Natural Apophyseal Glides nach Mulligan: Der Therapeut gibt einen gleitenden Druck auf Dornfortsatz oder Wirbelbogen entlang der Facettengelenke, der Patient bewegt dabei aktiv in die eingeschränkte oder auslösende Richtung.", "Bei zervikogenem Schwindel oft auf Höhe C1/C2 mit Rotation. Die Bewegung muss schmerz- und schwindelfrei bleiben, sonst Höhe, Richtung oder Druck ändern. Selbst-SNAGs macht der Patient mit einem Handtuch."]}, "diagnoseliste": {"t": "Heilmittel-Diagnoseliste", "x": ["KBV-Liste für langfristigen Heilmittelbedarf und besonderen Verordnungsbedarf. Verordnungen mit diesen Diagnosen werden bei der Wirtschaftlichkeitsprüfung des Arztes berücksichtigt, belasten also nicht sein übliches Verordnungsvolumen.", "Die geriatrischen Codes gelten nur, wenn der Patient mindestens 70 ist und genau dieser ICD-10-Code auf der Verordnung steht. Bei zögernden Ärzten und älteren Schwindelpatienten kann das ein Argument sein."], "q": "KBV Heilmittel-Diagnoseliste"}}}, {"id": "w47-kopf", "titel": "Kopfschmerzen: einordnen, testen, behandeln", "art": "kb", "kb": "NE11", "min": 14, "bild": "wissen/NE11.webp", "abschnitte": [{"t": "Wie häufig ist Kopfschmerz?", "b": [{"bars": [["Kopfschmerz, Frauen", 57.5, "57,5 %"], ["Kopfschmerz, Männer", 44.4, "44,4 %"], ["Migräne, Frauen", 14.8, "14,8 %"], ["Migräne, Männer", 6.0, "6,0 %"], ["Spannungskopfschmerz, Frauen", 10.3, "10,3 %"], ["Spannungskopfschmerz, Männer", 6.5, "6,5 %"]], "p": ["12-Monats-Häufigkeit in Deutschland, RKI-Studie BURDEN 2020 (n = 5.009). Gezählt sind nur Fälle, die alle Kriterien der ICHD-3 erfüllen. Wer die Kriterien knapp verfehlt, hat einen „wahrscheinlichen“ Spannungskopfschmerz, das sind noch einmal 28 % der Frauen und 22 % der Männer."]}]}, {"t": "1. Was ist das eigentlich?", "b": [{"p": ["Die [[ICHD-3|ichd3]] trennt primäre Kopfschmerzen, die eine eigene Erkrankung sind (Migräne, Spannungskopfschmerz, Cluster), von sekundären, die eine Ursache haben: Blutung, Entzündung, Tumor, Medikamente oder die Halswirbelsäule. Für uns heißt das: Erst klären, ob etwas Ernstes dahintersteckt, dann den Typ bestimmen, denn danach richtet sich die Therapie.", "Warum der Nacken bei fast jedem Kopfschmerz mitredet: Die Fasern aus C1 bis C3 enden im selben Kerngebiet im Hirnstamm wie der N. trigeminus, im [[trigeminozervikalen Komplex|tzk]]. Ein Reiz aus der oberen HWS kann deshalb als Schmerz an Stirn oder Auge ankommen, und umgekehrt sind Nackenmuskeln bei Migräne druckempfindlich, ohne die Ursache zu sein."]}, {"l": ["Spannungskopfschmerz ist der häufigste primäre Kopfschmerz. Er beginnt meist zwischen 25 und 30, gipfelt um 40 und nimmt danach ab.", "Migräne betrifft Frauen etwa 2,5-mal so oft wie Männer.", "Chronischer Spannungskopfschmerz ist selten (in Deutschland etwa 0,5 %), Kopfschmerz durch Medikamentenübergebrauch betrifft 0,7–1 %.", "„Chronisch“ heißt bei Spannungskopfschmerz, Migräne und Übergebrauch gleich: an mindestens 15 Tagen im Monat, über mehr als 3 Monate."], "merk": "Bei Kopfschmerz zuerst sekundäre Ursachen ausschließen, dann den Typ bestimmen. Ohne Kopfschmerzkalender keine saubere Einordnung."}]}, {"t": "2. Die Formen, die in der Praxis ankommen", "b": [{"tab": [["Spannungskopfschmerz", "Beidseitig, drückend wie ein Band, leicht bis mittel, Treppensteigen macht ihn nicht schlimmer. Keine Übelkeit, höchstens Licht- oder Lärmempfindlichkeit. 30 min bis 7 Tage. Episodisch unter 15 Tage im Monat, chronisch ab 15."], ["Migräne ohne Aura", "Mindestens 5 Attacken von 4–72 h. Einseitig, pulsierend, mittel bis stark, Bewegung verstärkt ihn. Dazu Übelkeit oder Licht- und Lärmempfindlichkeit. Chronisch ab 15 Kopfschmerztagen, davon mindestens 8 mit Migränemerkmalen."], ["Migräne mit Aura", "Mindestens 2 Attacken. Vollständig rückläufige Seh-, Gefühls- oder Sprachstörung, die sich über 5 min oder mehr ausbreitet, je Symptom 5–60 min. Kopfschmerz folgt meist innerhalb von 60 min."], ["Zervikogener Kopfschmerz", "Sekundär, ICHD-3 11.2.1. Seitenkonstant, vom Nacken nach vorn ziehend, durch Kopfhaltung oder Druck auf Nackenstrukturen auslösbar, HWS eingeschränkt. Die ICHD-3 verlangt einen Nachweis des Zusammenhangs mit der HWS."], ["[[Medikamentenübergebrauch|moh]]", "Kopfschmerz an mindestens 15 Tagen bei bekanntem Kopfschmerz, plus Akutmittel über mehr als 3 Monate an zu vielen Tagen: Triptane, Opioide, Kombipräparate ab 10 Tagen, einfache Schmerzmittel ab 15 Tagen im Monat."], ["Cluster-Kopfschmerz", "Selten, streng einseitig um das Auge, sehr stark, mit Augentränen oder laufender Nase auf derselben Seite und Unruhe. Gehört in ärztliche Hand."]]}, {"p": ["Die Merkmale von Migräne und Spannungskopfschmerz sind spiegelbildlich: einseitig gegen beidseitig, pulsierend gegen drückend, mittel bis stark gegen leicht bis mittel, durch Bewegung schlimmer gegen egal. Je zwei von vier reichen.", "Prognose beim Spannungskopfschmerz: In einer dänischen Bevölkerungsstudie über 12 Jahre hatten 45 % keine Beschwerden mehr, 16 % waren chronisch. Ungünstig waren ein chronischer Beginn, zusätzliche Migräne und Schlafprobleme (Lyngberg 2005)."], "merk": "Migräne: einseitig, pulsierend, stark, Bewegung verschlimmert. Spannungskopfschmerz: beidseitig, drückend, leicht bis mittel, Bewegung egal."}]}, {"t": "3. Warnzeichen: wann die Physio aufhört", "b": [{"p": ["Nur wenige Kopfschmerzpatienten haben einen sekundären Kopfschmerz, aber die dürfen wir nicht übersehen. Die Liste [[SNNOOP10|snnoop]] (Do et al., Neurology 2019) lässt sich direkt als Fragen im Erstbefund stellen."]}, {"tab": [["Sofort Notaufnahme (112)", "Donnerschlag: stärkster Kopfschmerz des Lebens, in Sekunden bis 1 min voll da. Neurologische Ausfälle oder Bewusstseinsstörung. Fieber mit Nackensteife. Neues Horner-Syndrom, Doppelbilder, Sprach- oder Schluckstörung."], ["Zeitnah ärztlich, vor der Behandlung", "Neuer Kopfschmerz im höheren Alter, deutlich anderes Muster als bisher, stetig zunehmend. Auslösung durch Husten, Niesen, Pressen. Lageabhängig. Schwangerschaft oder Wochenbett. Tumor oder Immunschwäche in der Vorgeschichte. Kopfschmerz nach Unfall. Neues Medikament."], ["Über 50 mit Schläfenschmerz", "Druckschmerz der Kopfhaut, Kauschmerz (Kieferclaudicatio), Sehstörung: an Riesenzellarteriitis denken, am selben Tag ärztlich."]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/kopf-sab-ct.webp", "t": "Natives CT bei Subarachnoidalblutung.", "c": "Der Pfeil zeigt helles, also frisches Blut in den basalen Zisternen um das Mittelhirn. Es bildet ein sternförmiges Muster und läuft in die seitlichen Hirnfurchen aus. Typische Klinik: Donnerschlagkopfschmerz, oft mit Nackensteife und Erbrechen. Das CT ist in den ersten Stunden am empfindlichsten."}]}, {"p": ["KI-erstellte Lehrbilder nach typischen Lehrbuchfällen, geprüft, keine echten Aufnahmen."]}, {"l": ["[[Dissektion der Halsarterien|dissektion]]: plötzlicher, ungewohnter Nacken- oder Kopfschmerz, oft nach kleinem Trauma, dazu Horner-Syndrom, Hirnnervenausfälle, Schwindel oder Gangunsicherheit. Die meisten Schlaganfälle durch Dissektion passieren in der ersten Woche nach Symptombeginn.", "Vor manueller Therapie der HWS empfiehlt das [[IFOMPT-Framework|ifompt]]: Anamnese, Blutdruck, Neurostatus und Untersuchung der Karotis. Positionelle VBI-Tests werden nicht mehr empfohlen, sie sind nicht valide.", "Ist die Gefäßhypothese nicht sicher verworfen: keine endgradige Rotation oder Extension, kein Thrust."], "merk": "Donnerschlag, neue Neurozeichen, Fieber mit Nackensteife: nicht behandeln, sofort Notaufnahme."}]}, {"t": "4. Befund und Abgrenzung", "b": [{"p": ["Am Anfang steht ein Kopfschmerzkalender, den die Migräne-Leitlinie ausdrücklich empfiehlt: Kopfschmerztage, Stärke, Dauer, Begleitsymptome und vor allem die Tage mit Schmerzmitteln. Daraus ergeben sich die Zählkriterien, der Verdacht auf Übergebrauch und der Verlauf. Für die Belastung eignen sich der [[HIT-6|hit6]] (aktuelle Beeinträchtigung) und der [[MIDAS|midas]] (verlorene Tage der letzten 3 Monate)."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/kopf-muskeln.webp", "t": "Muskeln und Nerv bei Kopfschmerz, rechte Seite von hinten-seitlich.", "c": "1 subokzipitale Muskeln (M. rectus capitis posterior major, Mm. obliqui capitis), 2 N. occipitalis major, 3 M. trapezius pars descendens, 4 M. sternocleidomastoideus, 5 M. temporalis. In diesen Muskeln finden sich bei Spannungskopfschmerz gehäuft aktive Triggerpunkte, deren Übertragungsschmerz das typische Muster nachahmt."}]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/kopf-frt.webp", "t": "Flexions-Rotations-Test.", "c": "Rückenlage, die HWS wird passiv voll gebeugt, damit die unteren Segmente gesperrt sind. Dann wird der Kopf zu jeder Seite gedreht, bis Widerstand oder Schmerz kommt. Normal sind etwa 44°. Etwa drei Viertel der Bewegung finden in C1/C2 statt."}]}, {"tab": [["[[Flexions-Rotations-Test|frt]]", "Positiv bei unter 32° oder mehr als 10° weniger als erwartet. Bester Einzeltest für C1/C2 beim zervikogenen Kopfschmerz (Hall 2010: Sensitivität 75 %, Spezifität 92 %)."], ["[[CCFT|ccft]]", "Tiefe Halsbeuger mit Druck-Biofeedback, Stufen 22–30 mmHg je 10 s. Beim zervikogenen Kopfschmerz mehr SCM-Aktivität."], ["Segmentuntersuchung C0–C3", "Schmerzhafte Dysfunktion C0–C4 spricht für zervikogen. Achtung: Anhaltender Druck auf C1/C2 löste auch bei 57 % der Gesunden Kopfschmerz aus (Watson und Drummond 2012). Allein nicht aussagekräftig."], ["Palpation perikranial", "Druckschmerz der Kopf- und Nackenmuskeln ist bei Spannungskopfschmerz und Migräne erhöht. Er unterscheidet die beiden nicht."], ["Kopfvorhaltung", "Bei chronischem Kopfschmerz häufiger als bei Gesunden und bei episodischem. Querschnittsdaten, also keine Ursache belegt."]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/kopf-ccft.webp", "t": "Kraniozervikaler Flexionstest.", "c": "Hakenlage, Luftkissen unter dem Nacken auf 20 mmHg. Die Patientin macht ein kleines Ja-Nicken und hält jede Stufe 10 s, der Therapeut tastet, ob der SCM mitarbeitet. Gewertet wird die höchste Stufe, die sie sauber 10 s halten kann."}]}, {"p": ["Das Muster nach Jull 2007 trennt den zervikogenen Kopfschmerz von Migräne und Spannungskopfschmerz: schmerzhafte Gelenkdysfunktion C0–C4, eingeschränkte Extension und auffälliger CCFT. Zusammen erreichten sie 100 % Sensitivität und 94 % Spezifität, allerdings bei nur 18 Patienten mit zervikogenem Kopfschmerz. Migräne und Spannungskopfschmerz unterschieden sich in der HWS-Untersuchung nicht von Gesunden."], "merk": "Ein einzelner positiver Nackenbefund macht noch keinen zervikogenen Kopfschmerz. Aussagekräftig ist die Kombination aus FRT, Segmentbefund C0–C3, Extension und CCFT."}]}, {"t": "5. Was hilft laut Studienlage?", "b": [{"p": ["Spannungskopfschmerz: Die Leitlinie der DGN und DMKG (AWMF 030/077, Stand 12/2023, gültig bis 12/2028) gibt den höchsten Empfehlungsgrad für kombinierte Physiotherapie, Entspannungsverfahren (PMR, autogenes Training), Biofeedback und multidisziplinäre Programme. Mobilisation, Weichteil- und Triggerpunkttechniken, Übungen für den Nacken, Krafttraining über mindestens 6 Wochen und Ausdauertraining sind ebenfalls empfohlen. Manipulation wirkt beim Spannungskopfschmerz nicht."]}, {"tab": [["Zervikogen: [[Jull 2002|jull2002]]", "200 Patienten, 6 Wochen, 8–12 Behandlungen. Mindestens 50 % weniger Kopfschmerztage: Übungen 76 %, Manipulation 71 %, beides 81 %, Kontrolle 29 %. Wirkung nach 12 Monaten noch da."], ["Zervikogen: Self-SNAG C1/C2", "Hall 2007: 2× täglich zu Hause. FRT sofort +15° statt +5° (Placebo), Kopfschmerzindex nach 12 Monaten 54 % niedriger."], ["Zervikogen: Übersicht", "Manuelle Therapie wirkt kurzfristig (etwa 1 Episode pro Woche weniger als Sham), nach 12 Monaten nicht mehr. Nackentraining senkt die Intensität auch langfristig (Demont 2023)."], ["Spannungskopfschmerz: Training", "Krafttraining als Bestandteil senkte die Frequenz, reines Dehnen erhöhte sie sogar (Tao 2025). Alle Trainingsformen waren in einer Netzwerkanalyse besser als Topiramat, Amitriptylin oder Placebo."], ["Migräne: Ausdauer", "Varkey 2011: 40 min, 3× pro Woche, 3 Monate. So wirksam wie Entspannung und wie Topiramat."], ["Migräne: Kraft", "In der Netzwerkanalyse von Woldeamanuel 2022 lagen Krafttraining (−3,6 Migränetage im Monat) und intensives Ausdauertraining (−3,1) vorn. Evidenz niedrig."]]}, {"p": ["Die Migräne-Leitlinie (AWMF 030/057, überarbeitet 08/2025, gültig bis 08/2028) nennt Ausdauersport, Kraftsport und einen regelmäßigen Tagesrhythmus als wirksam. Entspannung, Biofeedback und Verhaltenstherapie können eine medikamentöse Prophylaxe ersetzen. Physiotherapie oder manuelle Therapie als eigene Empfehlung findet sich in den lesbaren Teilen nicht.", "Akut beim Spannungskopfschmerz: 10%iges Pfefferminzöl auf Stirn und Schläfen, 3× im Abstand von 15 min (Leitlinie)."], "merk": "Manipulation hilft beim zervikogenen Kopfschmerz, beim Spannungskopfschmerz nicht. Lange hält vor allem das, was der Patient selbst trainiert."}]}, {"t": "6. Neu aus der Forschung 2024–2026", "b": [{"l": ["Migräne-Leitlinie neu seit August 2025, die Fassung von 2022 gilt nicht mehr. Die Leitlinie zum Medikamentenübergebrauch (AWMF 030/131) ist nur bis 30.11.2026 verlängert.", "Dosis für Training bei Migräne: Mehrere Dosis-Wirkungs-Analysen kommen auf etwa 3× pro Woche 30–40 min über 8–12 Wochen, Kraft und Ausdauer kombiniert am besten (Xie 2025, Ogrezeanu 2026). Die Evidenz bleibt niedrig.", "[[Schmerzedukation|pne]] zusätzlich zur Physiotherapie senkte die Migränetage um gut 2 pro Monat mehr als Physiotherapie allein (Meise 2023). Multimodal mit manueller Therapie, HWS-Übungen und Edukation war im Verlauf am besten (Tolentino 2025).", "Nackenschmerz bei Migräne ist die Regel: 77 % der Migränepatienten in Kliniken haben ihn, bei chronischer Migräne 87 %, bei Kontrollen 23 % (Al-Khazali 2022). Meist beginnt er mit der Attacke oder bis 2 h davor.", "Viele Patienten bekommen inzwischen [[CGRP-Antikörper oder Gepante|cgrp]]. Die AHS stuft sie seit 2024 als Mittel der ersten Wahl ein. Die Migränetage sinken, Nackenschmerz, Schonverhalten und Dekonditionierung bleiben oft."], "merk": "Nackenschmerz, der mit der Attacke kommt und geht, gehört zur Migräne und ist kein Beweis für einen zervikogenen Kopfschmerz."}]}, {"t": "7. Für den Praxisalltag", "b": [{"l": ["Erstbefund: Warnzeichen abfragen, Kalender mitgeben, HIT-6 erheben, HWS mit FRT, CCFT und Segmenten untersuchen.", "Zervikogen: Mobilisation C0–C3 und BWS, Self-SNAG C1/C2 2× täglich, kraniozervikale Flexion mit Biofeedback, Schulterblatt- und Nackenkraft, z. B. 3 × 10. 6–12 Termine über 4–6 Wochen.", "Spannungskopfschmerz: Weichteiltechniken und Mobilisation, aber nicht allein. Krafttraining Nacken und Schultergürtel über mindestens 6 Wochen, Ausdauer, PMR anleiten.", "Migräne: Ausdauer 3× pro Woche 30–40 min, steigern, Krafttraining dazu. In der Attacke nicht trainieren. Schlaf und regelmäßige Mahlzeiten ansprechen.", "Schmerzmitteltage im Kalender zählen. Ab 10 Tagen (Triptane, Kombipräparate) oder 15 Tagen (einfache Schmerzmittel) im Monat an Übergebrauch denken und ärztlich ansprechen. Den Entzug steuert der Arzt.", "Verordnung: Kopfschmerz hat keine eigene Diagnosegruppe. Meist WS mit HWS-Diagnose (MT möglich) oder CS bei chronischem Schmerz (ohne MT).", "Erfolg messen: Kopfschmerztage pro Monat und HIT-6. Ziel sind mindestens 50 % weniger Kopfschmerztage."], "merk": "Der Kalender ist Diagnose, Warnsystem für Übergebrauch und Verlaufsmessung in einem."}]}], "quellen": ["Headache Classification Committee of the IHS: ICHD-3, Cephalalgia 2018 (ichd-3.org)", "DGN/DMKG: Diagnostik und Therapie des Kopfschmerzes vom Spannungstyp, S1, AWMF 030/077, Stand 19.12.2023, gültig bis 18.12.2028", "DGN/DMKG: Therapie der Migräneattacke und Prophylaxe der Migräne, S1, AWMF 030/057, überarbeitet 08.08.2025, gültig bis 07.08.2028", "DGN/DMKG: Kopfschmerz bei Übergebrauch von Schmerz- oder Migränemitteln, S1, AWMF 030/131, verlängert bis 30.11.2026", "Porst M et al.: Migräne und Spannungskopfschmerz in Deutschland (BURDEN 2020). RKI, Journal of Health Monitoring S6/2020", "Do TP et al.: Red and orange flags for secondary headaches: SNNOOP10 list. Neurology 2019;92:134–144", "Rushton A et al.: International IFOMPT Cervical Framework. JOSPT 2023;53(1):7–22", "Hall TM et al.: The flexion-rotation test in cervicogenic headache. J Headache Pain 2010", "Jull G et al.: Cervical musculoskeletal impairment in frequent intermittent headache. Cephalalgia 2007", "Jull G et al.: A randomized controlled trial of exercise and manipulative therapy for cervicogenic headache. Spine 2002;27:1835–1843", "Hall T et al.: Efficacy of a C1-C2 self-sustained natural apophyseal glide (SNAG) in cervicogenic headache. JOSPT 2007", "Demont A et al.: Manual therapy and exercise for cervicogenic headache, systematic review. PM&R 2023", "Watson DH, Drummond PD: Head pain referral during examination of the neck in migraine and tension-type headache. Headache 2012", "Varkey E et al.: Exercise as migraine prophylaxis. Cephalalgia 2011", "Woldeamanuel GG, Oliveira R: Exercise types for migraine, network meta-analysis. J Headache Pain 2022", "Tao et al.: Exercise components for tension-type headache, component network meta-analysis. Postgrad Med J 2025", "Meise R et al.: Pain neuroscience education plus physiotherapy in migraine, RCT. Cephalalgia 2023", "Al-Khazali HM et al.: Prevalence of neck pain in migraine, meta-analysis. Cephalalgia 2022", "Lyngberg AC et al.: Prognosis of migraine and tension-type headache, 12-year follow-up. Neurology 2005", "Charles AC et al.: Calcitonin gene-related peptide-targeting therapies are a first-line option for the prevention of migraine. AHS Position Statement, Headache 2024"], "info": {"ichd3": {"t": "ICHD-3", "x": ["Internationale Klassifikation der Kopfschmerzerkrankungen, 3. Auflage, 2018 von der International Headache Society. Kapitel 1–4 sind primäre Kopfschmerzen, ab Kapitel 5 sekundäre.", "Jede Diagnose hat Zählkriterien (Zahl der Attacken, Tage im Monat, Dauer) und Merkmalslisten, von denen eine Mindestzahl erfüllt sein muss. Frei einsehbar unter ichd-3.org."], "q": "IHS, Cephalalgia 2018"}, "tzk": {"t": "Trigeminozervikaler Komplex", "x": ["Kerngebiet im unteren Hirnstamm und oberen Halsmark (Nucleus spinalis n. trigemini plus Hinterhorn C1–C3). Hier laufen Afferenzen aus Trigeminus und oberen Zervikalnerven auf dieselben Neurone.", "Folge: Schmerz aus Gelenken C0–C3, oberen Nackenmuskeln oder der Bandscheibe C2/3 kann in Stirn, Schläfe oder Auge projiziert werden. Das ist die Grundlage des zervikogenen Kopfschmerzes."], "q": "Bogduk, Curr Pain Headache Rep 2001"}, "moh": {"t": "Kopfschmerz bei Medikamentenübergebrauch", "x": ["ICHD-3 8.2: Kopfschmerz an mindestens 15 Tagen im Monat bei vorbestehender Kopfschmerzerkrankung und Übergebrauch über mehr als 3 Monate.", "Grenzen: Triptane, Ergotamin, Opioide, Kombinationspräparate ab 10 Tagen, einfache Analgetika (ASS, Ibuprofen, Paracetamol) ab 15 Tagen im Monat. Nach Entzug bessern sich etwa 50–70 % innerhalb von 6–12 Monaten, Rückfälle sind im ersten Jahr am häufigsten."], "q": "ICHD-3; AWMF 030/131"}, "snnoop": {"t": "SNNOOP10", "x": ["Checkliste mit 15 Warnzeichen für sekundären Kopfschmerz: Systemische Zeichen und Fieber, Neoplasie, Neurodefizit, plötzlicher Beginn, Beginn nach 65, Musterwechsel oder neuer Kopfschmerz, lageabhängig, ausgelöst durch Husten, Niesen oder Anstrengung, Papillenödem, progredient oder atypisch, Schwangerschaft, schmerzhaftes Auge mit autonomen Zeichen, nach Trauma, Immunschwäche, Schmerzmittelübergebrauch oder neues Medikament.", "Prospektiv validiert ist die Liste nicht, sie ist eine Expertenzusammenstellung."], "q": "Do et al., Neurology 2019"}, "dissektion": {"t": "Dissektion der Halsarterien", "x": ["Einriss der Gefäßwand der A. carotis interna oder A. vertebralis. Karotis: Kopf-, Gesichts- oder Halsschmerz, Horner-Syndrom (hängendes Lid, enge Pupille), Hirnnervenausfälle. Vertebralis: Nackenschmerz, Hinterkopfschmerz, Schwindel, Hirnstammzeichen.", "Häufigster Auslöser ist ein kürzliches Trauma, auch ein kleines. Spontane Dissektionen haben oft keinen Risikofaktor."], "q": "IFOMPT Cervical Framework 2020/2023"}, "ifompt": {"t": "IFOMPT-Framework", "x": ["Internationales Konsenspapier zur Untersuchung der HWS auf Gefäßerkrankungen vor manueller Behandlung, zuletzt 2020 überarbeitet, 2023 im JOSPT erschienen.", "Kern: Gefäßursache als Hypothese im Clinical Reasoning prüfen. Anamnese, Blutdruck, Hirnnerven und Neurostatus, Karotis tasten und abhören. Positionelle Provokationstests werden nicht empfohlen."], "q": "Rushton et al., JOSPT 2023"}, "hit6": {"t": "HIT-6", "x": ["Headache Impact Test, 6 Fragen zur Beeinträchtigung durch Kopfschmerz in den letzten 4 Wochen. Antworten nie 6, selten 8, manchmal 10, sehr oft 11, immer 13 Punkte, Summe 36–78.", "Auswertung: bis 49 kaum, 50–55 etwas, 56–59 deutlich, ab 60 schwer beeinträchtigt."], "q": "Houts et al., Qual Life Res 2021"}, "midas": {"t": "MIDAS", "x": ["Migraine Disability Assessment: 5 Fragen zu verlorenen Tagen in Arbeit, Haushalt und Freizeit in den letzten 3 Monaten, auch Tage mit halber Leistung zählen.", "Grad I 0–5, II 6–10, III 11–20, IV ab 21 Punkte. Als bedeutsame Änderung gelten bei Ausgangswerten von 6–20 etwa 4 Punkte, über 20 etwa 30 %."], "q": "Ruscheweyh et al., Cephalalgia 2024"}, "frt": {"t": "Flexions-Rotations-Test", "x": ["Rückenlage, HWS passiv maximal flektiert, dann Rotation zu beiden Seiten bis Widerstand oder Schmerz. Normal etwa 44° pro Seite.", "Positiv bei unter 32° oder über 10° Abweichung. Hall 2010: Sensitivität 75 %, Spezifität 92 %, LR+ 9,4. Ogince 2007: 91 % und 90 %. Interrater-ICC 0,93 bei Erfahrenen. Unvollständige Flexion kann falsch-negative Ergebnisse bringen."], "q": "Hall et al. 2010; Ogince et al. 2007"}, "ccft": {"t": "Kraniozervikaler Flexionstest", "x": ["Hakenlage, Druck-Biofeedback unter dem Nacken auf 20 mmHg. Fünf Stufen 22, 24, 26, 28, 30 mmHg, jede 10 s halten, ohne dass SCM oder Skalenen übernehmen.", "Aktivierungswert ist die höchste Stufe, die 10 s gelingt. Performance-Index: Wiederholungen dieser Stufe, bis 10 × 10 s. Reliabilität bei Patienten ICC 0,63–0,86."], "q": "Jull, O'Leary, Falla, JMPT 2008"}, "jull2002": {"t": "Jull 2002", "x": ["Multizentrische RCT mit 200 Patienten mit zervikogenem Kopfschmerz: Manipulativtherapie, spezifische Übungen (tiefe Halsbeuger, Schulterblatt, 2× täglich), Kombination oder Kontrolle, 6 Wochen.", "Beide Therapien senkten Frequenz und Intensität bis 12 Monate. Die Kombination war nicht signifikant besser, half aber 10 % mehr Patienten."], "q": "Jull et al., Spine 2002"}, "pne": {"t": "Schmerzedukation (PNE)", "x": ["Pain Neuroscience Education erklärt, wie Schmerz im Nervensystem entsteht und verstärkt wird, mit dem Ziel, Angst und Schonverhalten zu senken.", "In der RCT von Meise 2023 (82 Patienten mit Migräne) sanken die Migränetage nur in der Gruppe mit zusätzlicher Edukation deutlich, Unterschied 2,06 Tage im Monat. Nebenwirkungen gab es keine."], "q": "Meise et al., Cephalalgia 2023"}, "cgrp": {"t": "CGRP-Antikörper und Gepante", "x": ["CGRP ist ein Botenstoff, der in der Migräneattacke ausgeschüttet wird. Antikörper (Erenumab, Fremanezumab, Galcanezumab, Eptinezumab) werden alle 1–3 Monate gespritzt, Gepante (Rimegepant, Atogepant) als Tablette genommen.", "Erfolg heißt: mindestens 50 % weniger Migränetage bei episodischer, 30 % bei chronischer Migräne. Der Kalender, den die Physio mitführt, zeigt das direkt."], "q": "AWMF 030/057, 2025"}}, "fragen": [["Beidseitiger, drückender Kopfschmerz, leicht bis mittel, Treppensteigen ändert nichts, keine Übelkeit. Was passt am besten?", ["Migräne ohne Aura", "Cluster-Kopfschmerz", "Zervikogener Kopfschmerz", "Spannungskopfschmerz"], 3, "Beidseitig, drückend, leicht bis mittel und nicht durch Aktivität verstärkt sind die vier Merkmale des Spannungskopfschmerzes. Übelkeit gehört nicht dazu."], ["Ab wann spricht die ICHD-3 bei Spannungskopfschmerz von chronisch?", ["Ab 8 Tagen im Monat über 1 Monat", "Ab 15 Tagen im Monat über mehr als 3 Monate", "Ab 10 Tagen im Monat über 6 Wochen", "Ab 20 Tagen im Monat über 1 Jahr"], 1, "Für Spannungskopfschmerz, Migräne und Übergebrauch gilt gleich: mindestens 15 Tage im Monat, länger als 3 Monate."], ["Eine Patientin nimmt an 12 Tagen im Monat ein Kombinationspräparat (ASS, Paracetamol, Koffein). Was folgt daraus?", ["Übergebrauch möglich, die Grenze für Kombipräparate liegt bei 10 Tagen", "Unbedenklich, die Grenze liegt bei 20 Tagen", "Nur Triptane können Übergebrauch auslösen", "Unbedenklich, solange sie keine Opioide nimmt"], 0, "Für Triptane, Opioide und Kombinationspräparate liegt die Grenze bei 10 Tagen, für einfache Schmerzmittel bei 15 Tagen im Monat. Ärztlich ansprechen."], ["Welcher Befund verlangt sofort die Notaufnahme?", ["Kopfschmerz seit 10 Jahren, immer gleich", "Nackenschmerz mit Kopfschmerz nach langer Bildschirmarbeit", "Stärkster Kopfschmerz des Lebens, innerhalb einer Minute voll da", "Kopfschmerz, der bei Ablenkung besser wird"], 2, "Donnerschlagkopfschmerz kann eine Subarachnoidalblutung oder Dissektion sein. Keine Behandlung, sofort 112 bzw. Notaufnahme."], ["Was zeigt der gelbe Pfeil in diesem nativen CT?", ["Normale Hirnhäute", "Verkalkte Zirbeldrüse", "Hirnödem nach Infarkt", "Frisches Blut in den basalen Zisternen (Subarachnoidalblutung)"], 3, "Frisches Blut ist im CT hell. In den basalen Zisternen bildet es das typische sternförmige Muster der Subarachnoidalblutung.", "fortbildung/bilder/2026-W47/kopf-sab-ct.webp"], ["Was empfiehlt das IFOMPT-Framework vor manueller Therapie der HWS?", ["Anamnese, Blutdruck, Neurostatus und Untersuchung der Karotis", "Positionellen VBI-Test im Sitzen", "Röntgen der HWS bei jedem Patienten", "Probe-Manipulation mit wenig Kraft"], 0, "Positionelle Provokationstests gelten als nicht valide. Empfohlen wird ein Clinical Reasoning mit Anamnese, Blutdruck, Neurostatus und Karotis."], ["Flexions-Rotations-Test: Ab welchem Wert gilt er als positiv?", ["Unter 60°", "Unter 32° oder mehr als 10° unter dem erwarteten Wert", "Unter 15°", "Bei jedem Schmerz, unabhängig vom Winkel"], 1, "Normal sind etwa 44° pro Seite. Unter 32° oder eine Abweichung über 10° spricht für eine Dysfunktion C1/C2."], ["Warum wird beim Flexions-Rotations-Test die HWS vorher voll gebeugt?", ["Damit die Patientin entspannt", "Damit die A. vertebralis entlastet ist", "Damit die unteren Segmente gesperrt sind und die Rotation vor allem aus C1/C2 kommt", "Damit der Test schmerzfrei bleibt"], 2, "In voller Flexion sind die mittleren und unteren Segmente verriegelt. Etwa drei Viertel der Rotation finden dann in C1/C2 statt."], ["Welche Struktur ist im Bild mit der 2 markiert?", ["M. temporalis", "M. sternocleidomastoideus", "A. vertebralis", "N. occipitalis major"], 3, "Der N. occipitalis major tritt zwischen den subokzipitalen Muskeln hervor und zieht über den Hinterkopf. Er stammt aus C2.", "fortbildung/bilder/2026-W47/kopf-muskeln.webp"], ["Druck auf C1/C2 löst den bekannten Kopfschmerz aus. Wie ist das zu werten?", ["Allein wenig aussagekräftig, er trat auch bei 57 % der Gesunden auf", "Beweist einen zervikogenen Kopfschmerz", "Schließt Migräne aus", "Ist ein Warnzeichen für Dissektion"], 0, "Watson und Drummond 2012 fanden die Reproduktion bei fast allen Migräne- und Spannungskopfschmerzpatienten und bei 57 % der Gesunden. Erst die Kombination mit FRT, Extension und CCFT trägt."], ["Was gilt laut DGN-Leitlinie für Manipulation beim Spannungskopfschmerz?", ["Höchster Empfehlungsgrad", "Nur bei chronischem Verlauf empfohlen", "Nicht wirksam", "Nur in Kombination mit Dry Needling empfohlen"], 2, "Mobilisation und Weichteiltechniken sind empfohlen, Manipulation wirkt beim Spannungskopfschmerz nicht. Beim zervikogenen Kopfschmerz sieht das anders aus (Jull 2002)."], ["Welche Dosis Ausdauertraining war bei Migräne in der Studie von Varkey 2011 so wirksam wie Topiramat?", ["10 min täglich", "40 min, 3× pro Woche über 3 Monate", "90 min, 1× pro Woche", "20 min, 2× pro Woche über 4 Wochen"], 1, "40 min an 3 Tagen pro Woche über 3 Monate senkten die Attacken so stark wie Entspannung und Topiramat."], ["Ein Migränepatient hat in jeder Attacke Nackenschmerzen, die mit dem Kopfschmerz kommen und gehen. Was folgt daraus?", ["Es ist sicher ein zervikogener Kopfschmerz", "Er muss sofort ins MRT", "Es spricht für eine Dissektion", "Nackenschmerz gehört bei den meisten Migränepatienten zur Attacke"], 3, "Etwa 77 % der Migränepatienten haben Nackenschmerzen, meist zeitgleich mit der Attacke. Das ist Teil der Migräne, kein Beweis für eine HWS-Ursache."], ["Welche Trainingskomponente erhöhte in der Netzwerkanalyse von Tao 2025 beim Spannungskopfschmerz sogar die Kopfschmerzfrequenz?", ["Reines Dehnen", "Krafttraining", "Ausdauertraining", "Entspannung"], 0, "Krafttraining als Bestandteil senkte die Frequenz, Dehnen allein erhöhte sie. Also Kraft einbauen und Dehnen nicht als einziges Programm geben."]]}], "anatomie": [{"id": "w47-ana-knie", "titel": "Kniegelenk", "art": "ana", "min": 12, "abschnitte": [{"t": "1. Aufbau im Überblick", "b": [{"p": ["Das größte Gelenk des Körpers besteht aus zwei Teilgelenken in einer gemeinsamen Kapsel: dem Femorotibialgelenk und dem Femoropatellargelenk. Das [[proximale Tibiofibulargelenk|tibfib]] ist ein eigenes Gelenk mit eigener Kapsel."]}, {"tab": [["Gelenktyp", "Bikondyläres Gelenk, funktionell Drehscharniergelenk (Trochoginglymus)"], ["Freiheitsgrade", "2: Flexion/Extension, Rotation (nur in Beugung)"], ["Gelenkpartner", "Femurkondylen, Tibiaplateau, Patellarückfläche"], ["Inkongruenz", "Konvexe Femurkondylen auf flachem Tibiaplateau, ausgeglichen durch die Menisken"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-knie-schnitt.webp", "t": "Rechtes Knie im Längsschnitt, Blick von medial.", "c": "1 Femoropatellargelenk, 2 Femorotibialgelenk mit Meniskus, 3 Hoffa-Fettkörper, 4 Recessus suprapatellaris. Vorne liegt im Bild rechts."}]}]}, {"t": "2. Menisken", "b": [{"tab": [["Meniscus medialis", "C-förmig, größer, mit Innenband und Kapsel verwachsen, dadurch weniger beweglich und häufiger verletzt"], ["Meniscus lateralis", "Fast ringförmig, kleiner, nicht mit dem Außenband verbunden, beweglicher"], ["Versorgung", "Nur das äußere Drittel ist durchblutet ([[rote Zone|rotezone]]), innen ernährt Synovia. Deshalb heilen Risse innen schlecht"], ["Aufgaben", "Kongruenz verbessern, Last verteilen, Stoß dämpfen, Gelenk stabilisieren"]], "merk": "Innenmeniskus: fixiert und häufiger verletzt. Außenmeniskus: beweglich und seltener betroffen."}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-knie-menisken.webp", "t": "Rechtes Tibiaplateau von oben.", "c": "1 Meniscus medialis (offenes C), 2 Meniscus lateralis (fast ein Ring), 3 vorderes Kreuzband, 4 hinteres Kreuzband, 5 rote Zone (äußeres Drittel, durchblutet), 6 weiße Zone (inneres Drittel, ohne Gefäße). Vorne liegt unten, medial rechts."}]}]}, {"t": "3. Bänder", "b": [{"tab": [["[[Vorderes Kreuzband (VKB)|vkbbuendel]]", "Von der Area intercondylaris anterior der Tibia nach hinten-oben-lateral zur Innenseite des lateralen Femurkondylus. Hemmt die vordere Tibiaschublade und Innenrotation"], ["Hinteres Kreuzband (HKB)", "Von der Area intercondylaris posterior nach vorne-oben-medial zur Innenseite des medialen Femurkondylus. Kräftigstes Band, hemmt die hintere Schublade"], ["[[Innenband (MCL)|mcl]]", "Breit, flach, mit Kapsel und Innenmeniskus verwachsen. Hemmt Valgus und Außenrotation"], ["Außenband (LCL)", "Rundlich, vom lateralen Epicondylus zum Fibulaköpfchen, nicht mit dem Meniskus verbunden. Hemmt Varus"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-knie-baender.webp", "t": "Rechtes Knie von vorne, Patella nach unten geklappt.", "c": "1 vorderes Kreuzband, 2 hinteres Kreuzband, 3 Innenband, 4 Verwachsung von Innenband und Innenmeniskus, 5 Außenband zum Fibulaköpfchen, ohne Verbindung zum Außenmeniskus. Medial liegt im Bild rechts."}]}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."], "merk": "Kollateralbänder sind in Streckung gespannt, in Beugung locker. Deshalb ist Rotation nur im gebeugten Knie möglich."}]}, {"t": "4. Muskeln", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W47/ana-knie-muskeln.webp", "t": "Rechter Oberschenkel von hinten.", "c": "1 M. biceps femoris zum Fibulaköpfchen, 2 M. semitendinosus, 3 M. semimembranosus, 4 Caput mediale des M. gastrocnemius. Medial liegt im Bild links."}]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-knie-muskeln2.webp", "t": "Rechtes Bein, links von vorne, rechts Kniekehle in der Tiefe.", "c": "5 M. quadriceps femoris, 6 M. popliteus, 7 Pes anserinus am Ansatz medial an der Tibia."}]}, {"mus": [{"n": "M. quadriceps femoris", "p": [[24, 37.6]], "b": "ana-knie-muskeln2.webp", "z": "5", "u": "Rectus femoris: Spina iliaca anterior inferior; Vasti: Femurschaft", "a": "Über Patella und Lig. patellae an der Tuberositas tibiae", "i": "N. femoralis (L2–L4)", "f": "Knieextension, Rectus femoris zusätzlich Hüftflexion"}, {"n": "Ischiokrurale Muskeln", "p": [[60.9, 28.1], [37.5, 18.8], [39.1, 42.5]], "z": "1–3", "u": "Tuber ischiadicum (Caput breve des Biceps: Linea aspera)", "a": "Biceps: Caput fibulae; Semitendinosus und Semimembranosus: mediale Tibia", "i": "N. ischiadicus (Tibialis-Anteil, Caput breve: Peroneus-Anteil)", "f": "Knieflexion, Hüftextension; Biceps Außenrotation, mediale Gruppe Innenrotation"}, {"n": "M. popliteus", "p": [[76.8, 53.4]], "b": "ana-knie-muskeln2.webp", "z": "6", "u": "Lateraler Femurkondylus", "a": "Hintere Tibiafläche oberhalb der Linea m. solei", "i": "N. tibialis", "f": "Entriegelt das gestreckte Knie (Innenrotation der Tibia zu Beginn der Beugung)"}, {"n": "Pes anserinus superficialis", "p": [[26.3, 88.1]], "b": "ana-knie-muskeln2.webp", "z": "7", "u": "Sartorius, Gracilis, Semitendinosus", "a": "Medial an der Tuberositas tibiae", "i": "N. femoralis, N. obturatorius, N. tibialis", "f": "Knieflexion, Innenrotation, mediale Stabilität"}, {"n": "M. gastrocnemius", "p": [[38.6, 83.3]], "z": "4", "u": "Femurkondylen dorsal", "a": "Über die Achillessehne am Calcaneus", "i": "N. tibialis (S1–S2)", "f": "Plantarflexion, unterstützt Knieflexion"}]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-knie-pes.webp", "t": "Rechtes Knie von medial.", "c": "1 M. sartorius, 2 M. gracilis, 3 M. semitendinosus (zusammen Pes anserinus superficialis), 4 Bursa anserina, 5 Innenband in der Tiefe. Vorne liegt im Bild rechts."}]}]}, {"t": "5. Biomechanik", "b": [{"l": ["Roll-Gleit-Bewegung: Bei Beugung rollen die Femurkondylen nach dorsal und gleiten gleichzeitig nach ventral, sonst würden sie hinten vom Plateau rollen.", "[[Konkav-Konvex-Regel|konkavkonvex]]: Die konkave Tibia gleitet bei Bewegung der Tibia gleichsinnig. Bei Flexion der Tibia gleitet sie nach dorsal.", "Schlussrotation: In den letzten Grad der Extension rotiert die Tibia etwa 5–10° nach außen und verriegelt das Gelenk. Der M. popliteus entriegelt es wieder.", "Bewegungsausmaß (Neutral-Null): Extension/Flexion 5–10/0/120–150°. Rotation in 90° Flexion: Außenrotation ca. 40°, Innenrotation ca. 10°.", "[[Kapselmuster|kapselmuster]]: Flexion deutlich mehr eingeschränkt als Extension."], "merk": "Für die Mobilisation in Beugung: Tibia nach dorsal gleiten lassen."}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-knie-rollgleit.webp", "t": "Roll-Gleit-Bewegung, Blick von lateral.", "c": "Links Streckung, rechts 90° Beugung. Der grüne Punkt ist der Kontaktpunkt: Er wandert bei Beugung nach hinten. Der Femur rollt nach dorsal und gleitet gleichzeitig nach ventral. Vorne liegt rechts."}]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-knie-schlussrot.webp", "t": "Schlussrotation, rechtes Knie von vorne.", "c": "Der grüne Pfeil zeigt die Außenrotation der Tibia in der Endstreckung, die gestrichelte Linie die Ausgangsstellung. Rot durchscheinend hinten der M. popliteus, der das Knie wieder entriegelt. Lateral liegt im Bild links."}]}]}, {"t": "6. Nerven und Gefäße", "b": [{"tab": [["N. tibialis", "Zieht mittig durch die Kniekehle, versorgt die Wadenmuskulatur"], ["N. fibularis communis", "Läuft lateral um das Fibulaköpfchen und liegt dort direkt unter der Haut: Druckschäden durch Gips, Lagerung oder Fraktur führen zur Fußheberschwäche"], ["A. poplitea", "Liegt am tiefsten in der Kniekehle, direkt auf der Kapsel. Gefährdet bei [[Knieluxation|luxation]]"], ["Sensibilität", "N. saphenus (aus N. femoralis) medial am Knie und Unterschenkel; [[R. infrapatellaris|infrapat]] wird bei Zugängen von medial oft verletzt"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-knie-kniekehle.webp", "t": "Rechte Kniekehle von hinten.", "c": "1 N. tibialis, 2 N. fibularis communis am Fibulaköpfchen, 3 A. poplitea (am tiefsten), 4 V. poplitea. Medial liegt im Bild links."}]}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."], "merk": "Von oberflächlich nach tief: Nerv, Vene, Arterie."}]}, {"t": "7. Klinische Bezüge", "b": [{"l": ["Unhappy Triad: Valgus-Rotations-Trauma mit Riss von VKB, Innenband und Innenmeniskus. Heute weiß man, dass der Außenmeniskus oft häufiger mitbetroffen ist.", "[[Lachman-Test|lachman]] in 20–30° Flexion ist für das VKB genauer als die vordere Schublade in 90°.", "Hintere Schublade und Gravity Sign (Tibia hängt nach hinten durch) sprechen für eine HKB-Läsion.", "[[Bakerzyste|baker]]: Ausstülpung der Bursa zwischen Gastrocnemius medial und Semimembranosus, meist Folge eines Ergusses.", "Pes-anserinus-Bursitis: Druckschmerz medial unterhalb des Gelenkspalts, oft bei Gonarthrose."]}]}], "quellen": ["Schünke M, Schulte E, Schumacher U. Prometheus LernAtlas Allgemeine Anatomie und Bewegungssystem", "Kapandji IA. Funktionelle Anatomie der Gelenke, Band 2", "Benjaminse A et al. Clinical diagnosis of an ACL rupture: a meta-analysis. JOSPT 2006", "Kaltenborn FM. Manuelle Mobilisation der Extremitätengelenke"], "fragen": [["Welcher Meniskus ist häufiger verletzt, und warum?", ["Lateral, weil er größer ist", "Medial, weil er mit Innenband und Kapsel verwachsen und weniger beweglich ist", "Lateral, weil er mit dem Außenband verwachsen ist", "Beide gleich häufig"], 1, "Der Innenmeniskus ist mit Kapsel und Innenband verbunden und kann Belastungen schlechter ausweichen."], ["Welche Struktur zeigt der Pfeil?", ["Hinteres Kreuzband", "Meniscus lateralis", "Vorderes Kreuzband", "Lig. patellae"], 2, "Das vordere Kreuzband zieht von vorne-medial an der Tibia nach hinten-oben-lateral zur Innenseite des lateralen Femurkondylus.", "fortbildung/bilder/2026-W47/ana-knie.webp"], ["Welche Struktur ist mit der 2 markiert?", ["N. tibialis", "N. fibularis communis", "A. poplitea", "Sehne des M. biceps femoris"], 1, "Der N. fibularis communis zieht nach lateral und windet sich um den Hals des Fibulaköpfchens.", "fortbildung/bilder/2026-W47/ana-knie-kniekehle.webp"], ["Welche Zone ist mit der 5 markiert, und was heißt das für einen Riss dort?", ["Weiße Zone, heilt gut", "Rote Zone, heilt eher, weil sie durchblutet ist", "Rote Zone, heilt schlecht, weil sie entzündet ist", "Weiße Zone, wird immer genäht"], 1, "Das äußere Drittel ist durchblutet. Risse dort können heilen und werden eher genäht, Risse in der weißen Zone kaum.", "fortbildung/bilder/2026-W47/ana-knie-menisken.webp"], ["Welcher Meniskus ist mit der 1 markiert?", ["Meniscus lateralis", "Meniscus medialis", "Lig. transversum genus", "Hinteres Kreuzband"], 1, "Das große, offene C auf der medialen Seite ist der Innenmeniskus. Der Außenmeniskus ist fast ringförmig.", "fortbildung/bilder/2026-W47/ana-knie-menisken.webp"], ["Wo setzt das vordere Kreuzband am Femur an?", ["Innenseite des medialen Femurkondylus", "Innenseite des lateralen Femurkondylus", "Epicondylus medialis", "Trochlea femoris"], 1, "VKB: Innenseite des lateralen Kondylus. HKB: Innenseite des medialen Kondylus."], ["Wohin gleitet die Tibia bei Knieflexion (Tibia bewegt sich)?", ["Nach ventral", "Nach dorsal", "Nach medial", "Gar nicht"], 1, "Die konkave Tibia gleitet gleichsinnig zur Bewegung, bei Flexion also nach dorsal."], ["Was passiert bei der Schlussrotation?", ["Innenrotation der Tibia in den letzten Grad der Flexion", "Außenrotation der Tibia in den letzten Grad der Extension", "Außenrotation des Femurs bei Beugung", "Seitneigung der Patella"], 1, "Die Tibia rotiert in der Endstreckung etwa 5–10° nach außen und verriegelt das Gelenk."], ["Welcher Muskel entriegelt das gestreckte Knie?", ["M. sartorius", "M. popliteus", "M. biceps femoris", "M. vastus medialis"], 1, "Der Popliteus rotiert die Tibia zu Beginn der Beugung nach innen und hebt so die Schlussrotation auf."], ["Welcher Nerv ist am Fibulaköpfchen besonders gefährdet?", ["N. tibialis", "N. saphenus", "N. fibularis communis", "N. femoralis"], 2, "Er liegt dort direkt unter der Haut. Eine Schädigung führt zur Fußheberschwäche."], ["Wann sind die Kollateralbänder gespannt?", ["In Beugung", "In Streckung", "Immer gleich", "Nur bei Rotation"], 1, "In Streckung gespannt, in Beugung locker. Deshalb ist Rotation nur im gebeugten Knie möglich."], ["Welche Muskeln bilden den Pes anserinus superficialis?", ["Sartorius, Gracilis, Semitendinosus", "Semimembranosus, Biceps, Popliteus", "Rectus femoris, Vastus medialis, Sartorius", "Gracilis, Adductor magnus, Semimembranosus"], 0, "Merkhilfe „Say Grace before Tea“: Sartorius, Gracilis, Semitendinosus."], ["Welcher Test ist für eine VKB-Ruptur am genauesten?", ["Vordere Schublade in 90°", "Lachman in 20–30° Flexion", "McMurray", "Hintere Schublade"], 1, "Der Lachman-Test hat in Metaanalysen die beste Treffsicherheit für das VKB."]], "info": {"tibfib": {"t": "Proximales Tibiofibulargelenk", "x": ["Ein flaches Gelenk (Articulatio plana) zwischen Fibulaköpfchen und lateralem Tibiakondylus. Es bewegt sich mit dem oberen Sprunggelenk mit: Bei Dorsalextension weicht die Fibula leicht nach oben und außen aus.", "Klinisch wichtig bei lateralem Knieschmerz ohne Befund im Kniegelenk und bei eingeschränkter Dorsalextension. Der N. fibularis communis liegt direkt daneben."]}, "rotezone": {"t": "Drei Zonen des Meniskus", "x": ["Rot-rot: außen, gut durchblutet. Rot-weiß: Übergang, teilweise versorgt. Weiß-weiß: innen, ohne Gefäße.", "Die Zone entscheidet mit über die OP: Risse außen und im Übergang lassen sich oft nähen, Risse innen werden eher teilentfernt. Nach einer Naht ist die Nachbehandlung meist vorsichtiger als nach Teilresektion."]}, "vkbbuendel": {"t": "Zwei Bündel des VKB", "x": ["Das anteromediale Bündel ist vor allem in Beugung gespannt, das posterolaterale vor allem in Streckung. Ein Teil des Bandes ist also in jeder Stellung gespannt.", "Das posterolaterale Bündel trägt besonders zur Rotationsstabilität bei, das spürt man beim Pivot-Shift. Teilrupturen betreffen manchmal nur ein Bündel."]}, "mcl": {"t": "Schichten des Innenbands", "x": ["Oberflächlicher Anteil: lang, vom medialen Epicondylus weit nach distal an die Tibia, unter dem Pes anserinus. Tiefer Anteil: kurz, Teil der Kapsel und fest mit dem Innenmeniskus verbunden.", "Dazu kommt hinten das Lig. popliteum obliquum mit der posteromedialen Kapsel. Isolierte Innenbandrisse heilen meist konservativ gut."]}, "konkavkonvex": {"t": "Offene und geschlossene Kette", "x": ["Bewegt sich die Tibia (offene Kette, z. B. Sitzen am Behandlungstisch), gleitet die konkave Fläche in Bewegungsrichtung.", "Bewegt sich der Femur auf fixierter Tibia (geschlossene Kette, z. B. Kniebeuge), gleitet der konvexe Femur entgegengesetzt zur Bewegung. Für die Mobilisation zählt, welcher Partner bewegt und welcher fixiert wird."], "q": "Kaltenborn, Manuelle Mobilisation"}, "kapselmuster": {"t": "Kapselmuster nach Cyriax", "x": ["Ein gelenktypisches Verhältnis der Bewegungseinschränkung, wenn die ganze Kapsel betroffen ist, etwa bei Arthrose, Arthritis oder nach Ruhigstellung.", "Liegt ein anderes Muster vor, etwa nur Streckung blockiert, spricht das eher für eine lokale Ursache wie einen eingeklemmten Meniskus oder ein freies Gelenkkörperchen."]}, "luxation": {"t": "Knieluxation", "x": ["Riss mehrerer Bänder mit Verlust des Gelenkkontakts, oft hochenergetisch. Viele springen von selbst zurück, das Knie ist dann stark geschwollen und grob instabil.", "Die A. poplitea kann auch bei tastbaren Fußpulsen verletzt sein. Ein Knöchel-Arm-Index von 0,9 oder weniger oder Zeichen einer Durchblutungsstörung erfordern sofort Gefäßchirurgie. Häufigste Nervenverletzung ist der N. fibularis."]}, "infrapat": {"t": "R. infrapatellaris", "x": ["Hautast des N. saphenus, der unterhalb der Patella von medial nach lateral zieht und die Haut vorne unter der Kniescheibe versorgt.", "Nach Knie-OP oder Arthroskopie ist ein tauber Fleck lateral unter der Patella deshalb häufig. Selten entsteht ein schmerzhaftes Neurom, das als Knieschmerz fehlgedeutet wird."]}, "lachman": {"t": "Lachman-Test", "x": ["Knie in 20–30° Beugung, Femur fixieren, Tibia nach vorn ziehen. Beurteilt werden Verschiebeweg und Anschlag: Weich oder fehlend spricht für einen Riss.", "Metaanalyse: Sensitivität 85 %, Spezifität 94 %. Die vordere Schublade ist bei chronischer Ruptur ähnlich gut, im akuten Fall schlecht. Der Pivot-Shift ist sehr spezifisch (98 %), aber wenig sensitiv (24 %)."], "q": "Benjaminse A et al., JOSPT 2006"}, "baker": {"t": "Bakerzyste und Thrombose", "x": ["Platzt die Zyste, läuft Flüssigkeit in die Wade. Das macht plötzliche Wadenschmerzen und Schwellung und sieht aus wie eine tiefe Beinvenenthrombose.", "Deshalb Wadenschwellung nicht vorschnell der Zyste zuschreiben: Eine Thrombose muss ärztlich ausgeschlossen werden, meist per Ultraschall. Behandelt wird vor allem die Ursache des Ergusses."]}}}, {"id": "w47-ana-huefte", "titel": "Hüftgelenk", "art": "ana", "min": 12, "abschnitte": [{"t": "1. Aufbau im Überblick", "b": [{"p": ["Das Hüftgelenk ist ein Kugelgelenk mit tiefer Pfanne. Die Pfanne umfasst den Kopf über den Äquator hinaus, deshalb spricht man auch vom Nussgelenk. Das macht es sehr stabil, aber weniger beweglich als die Schulter."]}, {"tab": [["Gelenkpartner", "Femurkopf und Acetabulum aus Os ilium, Os ischii und Os pubis (Y-Fuge)"], ["Gelenkfläche der Pfanne", "Nur die hufeisenförmige Facies lunata ist knorpelüberzogen. Die Fossa acetabuli in der Mitte trägt Fettgewebe"], ["Labrum acetabulare", "Faserknorpellippe am Pfannenrand, vertieft die Pfanne und dichtet das Gelenk ab"], ["[[CCD-Winkel|ccd]]", "Erwachsene etwa 125–130°, Neugeborene um 150°. Unter 120° Coxa vara, über 140° Coxa valga"], ["[[Antetorsion|antetorsion]]", "Schenkelhals beim Erwachsenen etwa 12–15° nach vorne gedreht"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hue-schnitt.webp", "t": "Rechtes Hüftgelenk im Frontalschnitt, Blick von vorne.", "c": "1 Labrum acetabulare, 2 Lig. capitis femoris, 3 Fossa acetabuli mit Fettgewebe, 4 Zona orbicularis, 5 Trochanter major. Lateral liegt im Bild links."}]}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."], "merk": "Knorpel trägt nur die Facies lunata. Die Fossa acetabuli in der Mitte ist mit Fett gefüllt."}]}, {"t": "2. Kapsel und Bänder", "b": [{"tab": [["Lig. iliofemorale", "Von der Spina iliaca anterior inferior Y-förmig zur Linea intertrochanterica. Stärkstes Band des Körpers, hemmt die Extension"], ["Lig. pubofemorale", "Vom oberen Schambeinast zur Kapsel, hemmt Abduktion und Außenrotation"], ["Lig. ischiofemorale", "Vom Sitzbein spiralig nach oben-lateral, hemmt Innenrotation und Extension"], ["Zona orbicularis", "Ringförmige Fasern um den Schenkelhals, halten den Kopf in der Pfanne"], ["Lig. capitis femoris", "Von der Fossa acetabuli zur Fovea capitis. Mechanisch kaum wichtig, führt beim Kind ein [[Gefäß zum Kopf|ligcapitis]]"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hue-baender.webp", "t": "Rechtes Hüftgelenk, links von vorne, rechts von hinten.", "c": "1 Lig. iliofemorale (umgedrehtes Y), 2 Lig. pubofemorale, 3 Lig. ischiofemorale."}]}, {"merk": "Alle drei Bänder laufen spiralig um den Schenkelhals. In Extension drehen sie sich zu und spannen, in Flexion werden sie locker."}]}, {"t": "3. Muskeln", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hue-gesaess.webp", "t": "Rechte Gesäßregion von hinten, Gluteus maximus zurückgeklappt.", "c": "1 M. gluteus maximus, 2 M. gluteus medius, 3 M. piriformis, 4 N. ischiadicus unterhalb des Piriformis, 5 Trochanter major. Medial liegt im Bild links."}]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hue-muskeln2.webp", "t": "Rechtes Becken und Oberschenkel von vorne, tiefe Schicht.", "c": "6 M. iliopsoas unter dem Leistenband, 7 Adduktoren (M. adductor longus). Lateral liegt im Bild links."}]}, {"mus": [{"n": "M. iliopsoas", "p": [[41.2, 45.3]], "b": "ana-hue-muskeln2.webp", "z": "6", "u": "Psoas major: Wirbelkörper und Querfortsätze Th12–L4; Iliacus: Fossa iliaca", "a": "Trochanter minor", "i": "Plexus lumbalis und N. femoralis (L1–L4)", "f": "Stärkster Hüftbeuger, stabilisiert die LWS"}, {"n": "M. gluteus maximus", "p": [[83.9, 21.9]], "z": "1", "u": "Dorsale Darmbeinschaufel, Kreuzbein, Lig. sacrotuberale", "a": "Tuberositas glutea und Tractus iliotibialis", "i": "N. gluteus inferior (L5–S2)", "f": "Extension und Außenrotation, Aufrichten aus der Hocke"}, {"n": "M. gluteus medius", "p": [[40.2, 25.3]], "z": "2", "u": "Außenfläche der Darmbeinschaufel", "a": "Trochanter major", "i": "N. gluteus superior (L4–S1)", "f": "Abduktion, hält das Becken im Einbeinstand waagerecht"}, {"n": "M. piriformis", "p": [[32.8, 48.1]], "z": "3", "u": "Vorderfläche des Kreuzbeins", "a": "Spitze des Trochanter major", "i": "Direkte Äste des Plexus sacralis (L5–S2)", "f": "Außenrotation. In starker Beugung kehrt sich die Rotationswirkung um"}, {"n": "Adduktoren", "p": [[55, 61.7]], "b": "ana-hue-muskeln2.webp", "z": "7", "u": "Schambein und Sitzbeinast", "a": "Linea aspera, Adductor magnus zusätzlich Tuberculum adductorium", "i": "N. obturatorius (L2–L4), Adductor magnus anteilig N. tibialis", "f": "Adduktion, Beckenstabilität im Stand"}]}, {"merk": "Der N. ischiadicus verlässt das Becken meist unterhalb des Piriformis. Bei einem Teil der Menschen zieht er [[ganz oder teilweise durch den Muskel|ischiadicusvar]]."}]}, {"t": "4. Biomechanik", "b": [{"l": ["Im Einbeinstand halten Gluteus medius und minimus das Becken waagerecht. Auf den Hüftkopf wirkt dabei etwa das [[Zwei- bis Dreifache des Körpergewichts|hueftlast]].", "Trendelenburg-Zeichen: Sind die Abduktoren des Standbeins schwach, sinkt das Becken zur Spielbeinseite ab. [[Duchenne-Hinken|duchenne]]: Der Oberkörper neigt sich zur Standbeinseite und entlastet so die Abduktoren.", "Konvex-Konkav-Regel: Der konvexe Femurkopf gleitet gegensinnig zur Bewegung des Beins. Bei Flexion gleitet er nach dorsal, bei Abduktion nach kaudal.", "Bewegungsausmaß (Neutral-Null): Extension/Flexion 10–20/0/120–140°, Abduktion/Adduktion 30–45/0/20–30°, Außen-/Innenrotation 40–50/0/30–40°.", "Kapselmuster: Innenrotation am stärksten eingeschränkt, dann Flexion und Abduktion. Bei Coxarthrose ist die Innenrotation oft das erste Zeichen."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hue-trendelenburg.webp", "t": "Einbeinstand rechts, Ansicht von hinten.", "c": "Links normal: Der rechte Gluteus medius hält das Becken waagerecht. Rechts Trendelenburg-Zeichen: Der Muskel ist schwach, das Becken sinkt zur Seite des angehobenen Beins ab."}]}, {"merk": "Trendelenburg: Becken sinkt zur Spielbeinseite. Schwach ist der Gluteus medius des Standbeins."}]}, {"t": "5. Nerven und Gefäße", "b": [{"tab": [["N. femoralis", "Zieht lateral der A. femoralis unter dem Leistenband zum Oberschenkel, versorgt Iliopsoas, Quadrizeps und Sartorius"], ["N. ischiadicus", "Verlässt das Becken unter dem Piriformis (Foramen infrapiriforme) und zieht zwischen Trochanter major und Sitzbeinhöcker nach unten"], ["N. gluteus superior", "Tritt oberhalb des Piriformis aus und versorgt Gluteus medius, minimus und Tensor fasciae latae. Schaden führt zum Trendelenburg-Zeichen"], ["N. obturatorius", "Durch das Foramen obturatum zu den Adduktoren. Reizung kann Schmerzen an der Knieinnenseite machen"], ["A. circumflexa femoris medialis", "Wichtigstes Gefäß für den Femurkopf. Bei Schenkelhalsfrakturen gefährdet, daher Risiko einer [[Hüftkopfnekrose|nekrose]]"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hue-leiste.webp", "t": "Rechte Leiste von vorne (Trigonum femorale).", "c": "1 Leistenband, 2 N. femoralis, 3 A. femoralis, 4 V. femoralis. Lateral liegt im Bild links."}]}, {"merk": "Unter dem Leistenband von lateral nach medial: Nerv, Arterie, Vene."}]}, {"t": "6. Klinische Bezüge", "b": [{"l": ["Femoroacetabuläres Impingement: Beim Cam-Typ stößt eine Vorwölbung am Kopf-Hals-Übergang an die Pfanne, beim Pincer-Typ überdacht die Pfanne den Kopf zu stark. Typisch ist Leistenschmerz bei Flexion, Adduktion und Innenrotation ([[FADIR-Test|fadir]]).", "Coxarthrose: Leistenschmerz, Anlaufschmerz, eingeschränkte Innenrotation. Schmerz kann bis ins Knie ausstrahlen.", "Gluteale Tendinopathie (Greater Trochanteric Pain Syndrome): Schmerz lateral am Trochanter, schlimmer beim Liegen auf der Seite und bei Adduktion. Die Sehnen von Gluteus medius und minimus sind meist die Quelle, weniger die Bursa.", "Schenkelhalsfraktur: Bein verkürzt und außenrotiert. Je weiter verschoben, desto höher das Nekroserisiko.", "[[Epiphysiolysis capitis femoris|ecf]]: Abrutschen der Kopfepiphyse bei Jugendlichen um 10–15 Jahre, oft mit Knieschmerz. Drehmann-Zeichen: Bei Beugung weicht das Bein in Außenrotation aus."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hue-fai.webp", "t": "Femoroacetabuläres Impingement, Schema von vorne.", "c": "Links Cam-Typ: Vorwölbung am Kopf-Hals-Übergang (Pfeil). Rechts Pincer-Typ: Die Pfanne überdacht den Kopf zu weit (Pfeil)."}]}, {"merk": "Hüftschmerz zeigt sich oft in der Leiste oder im Knie. Bei Knieschmerz ohne Kniebefund die Hüfte untersuchen."}]}], "quellen": ["Schünke M, Schulte E, Schumacher U. Prometheus LernAtlas Allgemeine Anatomie und Bewegungssystem", "Kapandji IA. Funktionelle Anatomie der Gelenke, Band 2", "Kaltenborn FM. Manuelle Mobilisation der Extremitätengelenke", "Griffin DR et al. The Warwick Agreement on femoroacetabular impingement syndrome. Br J Sports Med 2016", "Grimaldi A et al. Gluteal tendinopathy: a review of mechanisms, assessment and management. Sports Med 2015"], "fragen": [["Welches Band ist das stärkste des Körpers und hemmt die Extension der Hüfte?", ["Lig. pubofemorale", "Lig. ischiofemorale", "Lig. iliofemorale", "Lig. capitis femoris"], 2, "Das Y-förmige Lig. iliofemorale spannt sich in Extension und hält uns im Stand ohne Muskelarbeit vorne."], ["Welche Struktur ist mit der 1 markiert?", ["Lig. capitis femoris", "Labrum acetabulare", "Zona orbicularis", "Fossa acetabuli"], 1, "Das Labrum sitzt als Faserknorpellippe am Pfannenrand und vertieft die Pfanne.", "fortbildung/bilder/2026-W47/ana-hue-schnitt.webp"], ["Welche Struktur ist mit der 4 markiert?", ["M. piriformis", "M. quadratus femoris", "N. ischiadicus", "N. gluteus superior"], 2, "Der N. ischiadicus tritt unter dem Piriformis aus dem Becken und zieht nach unten zur Oberschenkelrückseite.", "fortbildung/bilder/2026-W47/ana-hue-gesaess.webp"], ["Was zeigt das Trendelenburg-Zeichen?", ["Becken sinkt zur Standbeinseite", "Becken sinkt zur Spielbeinseite", "Oberkörper neigt zur Spielbeinseite", "Bein dreht beim Gehen nach innen"], 1, "Sind die Abduktoren des Standbeins zu schwach, sinkt das Becken auf der Seite des angehobenen Beins ab."], ["Welcher Nerv versorgt den M. gluteus medius?", ["N. gluteus inferior", "N. gluteus superior", "N. femoralis", "N. obturatorius"], 1, "Der N. gluteus superior verlässt das Becken oberhalb des Piriformis und versorgt Gluteus medius, minimus und Tensor fasciae latae."], ["Wie lautet das Kapselmuster der Hüfte?", ["Extension am stärksten eingeschränkt", "Innenrotation am stärksten, dann Flexion und Abduktion", "Außenrotation vor Abduktion", "Adduktion vor Flexion"], 1, "Bei der Hüfte ist die Innenrotation zuerst und am stärksten eingeschränkt."], ["Wohin gleitet der Femurkopf bei Flexion der Hüfte?", ["Nach ventral", "Nach dorsal", "Nach kranial", "Nach medial"], 1, "Der konvexe Kopf gleitet gegensinnig: Das Bein geht nach vorne oben, der Kopf gleitet nach dorsal."], ["Welche Struktur liegt unter dem Leistenband am weitesten lateral?", ["V. femoralis", "A. femoralis", "N. femoralis", "Lymphknoten"], 2, "Von lateral nach medial: Nerv, Arterie, Vene.", "fortbildung/bilder/2026-W47/ana-hue-leiste.webp"], ["Welches Gefäß versorgt beim Erwachsenen hauptsächlich den Femurkopf?", ["A. lig. capitis femoris", "A. circumflexa femoris medialis", "A. glutea inferior", "A. profunda femoris direkt"], 1, "Die Äste der A. circumflexa femoris medialis laufen am Schenkelhals entlang und reißen bei Frakturen leicht."], ["Was ist beim Cam-Typ des femoroacetabulären Impingements verändert?", ["Die Pfanne ist zu tief", "Der Kopf-Hals-Übergang hat eine Vorwölbung", "Das Labrum fehlt", "Der CCD-Winkel ist über 140°"], 1, "Beim Cam-Typ stößt eine knöcherne Vorwölbung am Kopf-Hals-Übergang bei Beugung und Innenrotation an den Pfannenrand.", "fortbildung/bilder/2026-W47/ana-hue-fai.webp"], ["Wie groß ist der CCD-Winkel beim Erwachsenen etwa?", ["Etwa 100°", "Etwa 125–130°", "Etwa 150°", "Etwa 170°"], 1, "Beim Neugeborenen liegt er um 150° und flacht bis ins Erwachsenenalter auf etwa 125–130° ab."]], "info": {"ccd": {"t": "CCD-Winkel", "x": ["Centrum-Collum-Diaphysen-Winkel: der Winkel zwischen Schenkelhalsachse und Femurschaft in der Frontalebene.", "Bei einer Coxa vara ist der Hebelarm der Abduktoren länger, der Schenkelhals aber stärker auf Biegung belastet. Bei einer Coxa valga ist der Hebelarm kürzer, die Abduktoren müssen mehr Kraft aufbringen, und der Kopf wird weniger überdacht. Die Coxa valga findet sich häufig bei Hüftdysplasie."]}, "antetorsion": {"t": "Antetorsion", "x": ["Verdrehung des Schenkelhalses gegenüber der Kniegelenksachse nach vorn. Beim Kind ist sie deutlich größer und nimmt im Wachstum ab.", "Mehr Antetorsion bedeutet mehr Innenrotation und weniger Außenrotation in der Hüfte, bei Kindern oft mit Innenrotationsgang. Klinisch schätzbar mit dem Craig-Test: In Bauchlage und 90° Knieflexion das Bein drehen, bis der Trochanter major am weitesten lateral tastbar ist. Der Winkel des Unterschenkels zur Senkrechten entspricht etwa der Antetorsion."]}, "ligcapitis": {"t": "A. ligamenti capitis femoris", "x": ["Ein kleiner Ast, meist aus der A. obturatoria, der im Band zur Fovea capitis zieht.", "Beim Kind versorgt er einen Teil des Kopfes mit. Beim Erwachsenen reicht er für den Kopf nicht aus. Deshalb schützt er nach einer Schenkelhalsfraktur nicht vor einer Nekrose, dafür ist die A. circumflexa femoris medialis entscheidend."]}, "ischiadicusvar": {"t": "Varianten des N. ischiadicus", "x": ["Eine Metaanalyse mit über 7000 Beinen fand den Normalverlauf, einen ungeteilten Nerv unter dem Piriformis, in etwa 85 %. Häufigste Variante mit knapp 10 %: Der Nerv teilt sich schon im Becken, der fibulare Anteil zieht durch den Piriformis, der tibiale darunter.", "Ob solche Varianten ein Piriformis-Syndrom begünstigen, ist nicht sicher belegt."], "q": "Tomaszewski KA et al., J Orthop Res 2016"}, "hueftlast": {"t": "Last auf dem Hüftkopf", "x": ["Gemessen mit Hüftprothesen, die Kräfte per Funk senden: beim Gehen im Mittel etwa 238 % des Körpergewichts, beim Treppensteigen etwa 251 % aufwärts und 260 % abwärts.", "Der Grund ist der Hebel: Das Körpergewicht greift weit medial an, die Abduktoren setzen nah am Drehpunkt an. Sie müssen daher ein Mehrfaches ziehen, und beide Kräfte addieren sich im Gelenk."], "q": "Bergmann G et al., J Biomech 2001"}, "duchenne": {"t": "Duchenne oder Trendelenburg", "x": ["Beim Duchenne-Hinken verlagert der Patient den Schwerpunkt über das Hüftgelenk. Der Hebel des Körpergewichts wird kürzer, die Abduktoren müssen weniger ziehen und die Gelenkkraft sinkt.", "Es ist also oft ein Ausweichen und nicht nur ein Zeichen von Schwäche. Typisch bei Coxarthrose, wo das Hinken Schmerz spart. Ein Gehstock in der Gegenhand hat einen ähnlichen Entlastungseffekt."]}, "nekrose": {"t": "Hüftkopfnekrose", "x": ["Absterben von Knochen im Femurkopf, weil die Blutversorgung ausfällt. Neben Frakturen und Luxationen gelten Kortison in hoher Dosis und viel Alkohol als wichtige Risikofaktoren.", "Frühes Zeichen ist Leistenschmerz, auch in Ruhe und nachts, mit schmerzhafter Innenrotation. Das Röntgenbild ist anfangs unauffällig, das MRT zeigt die Nekrose früh. Bei passender Vorgeschichte ärztlich abklären lassen, bevor der Kopf einbricht."]}, "fadir": {"t": "FADIR-Test", "x": ["Rückenlage, Hüfte in 90° Flexion, dann Adduktion und Innenrotation. Positiv bei dem bekannten Leistenschmerz.", "Metaanalyse: Sensitivität 99 %, Spezifität 5 %. Ein negativer Test macht ein Impingement oder eine Labrumläsion unwahrscheinlich, ein positiver beweist wenig. Die Diagnose stützt sich auf Beschwerden, Befund und Bildgebung zusammen."], "q": "Reiman MP et al., Br J Sports Med 2015"}, "ecf": {"t": "Epiphysiolysis capitis femoris", "x": ["Betroffen sind vor allem übergewichtige Jungen im Wachstumsschub. Warnzeichen: Hinken, Leisten-, Oberschenkel- oder Knieschmerz, eingeschränkte Innenrotation, positives Drehmann-Zeichen.", "Verdacht heißt: nicht belasten, keine Übungen, noch am selben Tag ärztlich vorstellen. Kann das Kind nicht mehr auftreten, gilt die Form als instabil mit hohem Nekroserisiko. Oft ist auch die Gegenseite betroffen."]}}}, {"id": "w47-ana-schulter", "titel": "Schultergelenk", "art": "ana", "min": 12, "abschnitte": [{"t": "1. Aufbau im Überblick", "b": [{"p": ["Die Schulter ist das beweglichste Gelenk des Körpers. Dafür ist sie knöchern kaum gesichert: Die Pfanne deckt nur etwa ein Viertel bis ein Drittel des Kopfes ab. Die Stabilität kommt vor allem von Labrum, Kapsel und Muskeln."]}, {"tab": [["Glenohumeralgelenk", "Kugelgelenk zwischen Humeruskopf und Cavitas glenoidalis"], ["Acromioclaviculargelenk", "Zwischen Schlüsselbein und Akromion, oft mit Discus. Häufig betroffen bei Sturz auf die Schulter"], ["Sternoclaviculargelenk", "Einzige knöcherne Verbindung des Arms zum Rumpf, mit Discus"], ["Skapulothorakale Gleitschicht", "Kein echtes Gelenk: Das Schulterblatt gleitet auf dem Brustkorb"], ["[[Subakromialer Nebenraum|subakromial]]", "Raum unter dem Schulterdach mit Bursa subacromialis und Supraspinatussehne"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-sch-aufbau.webp", "t": "Rechter Schultergürtel von vorne.", "c": "1 Glenohumeralgelenk, 2 AC-Gelenk, 3 SC-Gelenk, 4 Proc. coracoideus, 5 Akromion. Lateral liegt im Bild links."}]}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."], "merk": "Fünf Gelenke arbeiten zusammen. Ist eines eingeschränkt, müssen die anderen mehr leisten."}]}, {"t": "2. Kapsel und Bänder", "b": [{"tab": [["Labrum glenoidale", "Faserknorpelring am Pfannenrand, vergrößert und vertieft die Pfanne. Oben entspringt die lange Bizepssehne"], ["[[Ligg. glenohumeralia|ighl]]", "Verstärkungen der vorderen Kapsel (superius, medium, inferius). Das untere ist der wichtigste vordere Stabilisator in Abduktion und Außenrotation"], ["Recessus axillaris", "Schlaffe Kapseltasche unten. Sie entfaltet sich bei Elevation und verklebt bei der Frozen Shoulder"], ["[[Lig. coracohumerale|chl]]", "Vom Coracoid zu den Tubercula, hemmt Außenrotation bei hängendem Arm"], ["Lig. coracoacromiale", "Bildet mit Akromion und Coracoid das Schulterdach (Fornix humeri)"], ["Lig. coracoclaviculare", "Hält das Schlüsselbein am Coracoid. Bei schwerer AC-Sprengung mit gerissen"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-sch-glenoid.webp", "t": "Rechte Gelenkpfanne von lateral, Humeruskopf entfernt.", "c": "1 Labrum glenoidale, 2 lange Bizepssehne am Ursprung, 3 Lig. glenohumerale inferius, 4 Recessus axillaris, 5 Lig. coracoacromiale. Vorne liegt im Bild rechts."}]}, {"merk": "Die Schulter ist vor allem muskulär gesichert. Kapsel und Bänder spannen sich erst in Endstellungen."}]}, {"t": "3. Muskeln", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W47/ana-sch-rm.webp", "t": "Rotatorenmanschette rechts, links von hinten, rechts von vorne.", "c": "1 M. supraspinatus, 2 M. infraspinatus, 3 M. teres minor, 4 M. subscapularis, 5 lange Bizepssehne im Sulcus intertubercularis."}]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-sch-muskeln2.webp", "t": "Rechte Schulter und Brustkorb von der Seite.", "c": "6 M. deltoideus, 7 Zacken des M. serratus anterior. Vorne liegt im Bild links."}]}, {"mus": [{"n": "M. supraspinatus", "p": [[21.6, 28.9]], "z": "1", "u": "Fossa supraspinata", "a": "Oberer Teil des Tuberculum majus", "i": "N. suprascapularis (C5–C6)", "f": "Startet die Abduktion, zentriert den Humeruskopf in der Pfanne"}, {"n": "M. infraspinatus", "p": [[20.9, 45.6]], "z": "2", "u": "Fossa infraspinata", "a": "Mittlerer Teil des Tuberculum majus", "i": "N. suprascapularis (C5–C6)", "f": "Außenrotation, drückt den Kopf nach kaudal"}, {"n": "M. teres minor", "p": [[24.5, 55.8]], "z": "3", "u": "Lateraler Rand des Schulterblatts", "a": "Unterer Teil des Tuberculum majus", "i": "N. axillaris (C5–C6)", "f": "Außenrotation"}, {"n": "M. subscapularis", "p": [[82, 45]], "z": "4", "u": "Fossa subscapularis", "a": "Tuberculum minus", "i": "Nn. subscapulares (C5–C7)", "f": "Innenrotation, vorderer Stabilisator"}, {"n": "M. deltoideus", "p": [[44, 22.3]], "b": "ana-sch-muskeln2.webp", "z": "6", "u": "Laterales Drittel der Clavicula, Akromion, Spina scapulae", "a": "Tuberositas deltoidea", "i": "N. axillaris (C5–C6)", "f": "Abduktion. Vorderer Teil Flexion und Innenrotation, hinterer Teil Extension und Außenrotation"}, {"n": "M. serratus anterior", "p": [[59.5, 69]], "b": "ana-sch-muskeln2.webp", "z": "7", "u": "Rippen 1–9", "a": "Margo medialis des Schulterblatts", "i": "N. thoracicus longus (C5–C7)", "f": "Zieht das Schulterblatt nach vorne und dreht es nach oben. Ausfall: Scapula alata"}]}, {"merk": "SITS: Supraspinatus, Infraspinatus, Teres minor setzen am Tuberculum majus an, Subscapularis am Tuberculum minus."}]}, {"t": "4. Biomechanik", "b": [{"l": ["Skapulohumeraler Rhythmus: Bei voller Elevation kommen etwa 120° aus dem Schultergelenk und 60° aus der Drehung des Schulterblatts, also grob 2 : 1. Der Anteil schwankt je nach Phase und Person.", "Damit das Tuberculum majus bei Abduktion nicht unter das Schulterdach stößt, rotiert der Humerus dabei nach außen.", "Kräftepaar: Der Deltoideus zieht den Kopf nach kranial, die Rotatorenmanschette hält ihn unten und zentriert. Fällt die Manschette aus, wandert der Kopf nach oben.", "[[Konvex-Konkav-Regel|konvexkonkav]]: Der Humeruskopf gleitet gegensinnig. Bei Abduktion gleitet er nach kaudal, bei Außenrotation nach ventral, bei Innenrotation nach dorsal.", "Bewegungsausmaß (Neutral-Null): Extension/Flexion 40–50/0/150–170°, Abduktion/Adduktion 180/0/20–40°, Außen-/Innenrotation 40–60/0/95° bei hängendem Arm.", "[[Kapselmuster|kapselmuster]]: Außenrotation am stärksten eingeschränkt, dann Abduktion, dann Innenrotation."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-sch-rhythmus.webp", "t": "Skapulohumeraler Rhythmus, rechte Schulter von hinten.", "c": "Links Arm hängend. Rechts volle Elevation: Das Schulterblatt dreht nach oben (grüner Pfeil), der untere Winkel wandert nach lateral. Gestrichelt die Ausgangslage."}]}, {"merk": "Kapselmuster Schulter: Außenrotation vor Abduktion vor Innenrotation."}]}, {"t": "5. Nerven und Gefäße", "b": [{"tab": [["N. axillaris", "Läuft mit der A. circumflexa humeri posterior durch die laterale Achsellücke um den Humerushals. Versorgt Deltoideus und Teres minor und die Haut über dem Deltamuskel. Gefährdet bei Luxation und Humeruskopffraktur"], ["N. suprascapularis", "Zieht durch die Incisura scapulae unter dem Lig. transversum scapulae superius zum Supraspinatus, dann um die Spina zum Infraspinatus. [[Engstelle an der Spina|spinoglenoidal]] betrifft nur den Infraspinatus"], ["N. thoracicus longus", "Läuft außen auf dem Serratus anterior. Schaden führt zur [[Scapula alata|alata]]"], ["Plexus brachialis", "Zieht unter dem Schlüsselbein und hinter dem Pectoralis minor in die Achsel, zusammen mit der A. axillaris"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-sch-nerven.webp", "t": "Rechtes Schulterblatt von hinten mit Nerven.", "c": "1 N. suprascapularis an der Incisura scapulae, 2 Lig. transversum scapulae superius, 3 N. axillaris in der lateralen Achsellücke, 4 A. circumflexa humeri posterior. Lateral liegt im Bild rechts."}]}, {"merk": "Nach einer Luxation immer Sensibilität über dem Deltamuskel prüfen: Das ist das Areal des N. axillaris."}]}, {"t": "6. Klinische Bezüge", "b": [{"l": ["Subakromiales Schmerzsyndrom: Schmerz bei Elevation zwischen etwa 60 und 120° (painful arc). Heute sieht man es weniger als mechanisches Einklemmen, sondern als belastungsabhängiges Sehnenproblem. Die subakromiale Dekompression bringt [[keinen klinisch relevanten Vorteil|csaw]], weder gegenüber einer Schein-OP noch gegenüber Übungstherapie.", "Rotatorenmanschettenruptur: Meist ist der Supraspinatus betroffen. Bei Älteren oft ohne Trauma und auch ohne Beschwerden.", "Luxation: Über 90 Prozent nach vorne-unten. Folgeschäden sind die [[Bankart-Läsion|bankart]] am vorderen-unteren Labrum und die Hill-Sachs-Delle hinten am Kopf.", "Frozen Shoulder: Verdickte, verklebte Kapsel, vor allem im Rotatorenintervall und Recessus axillaris. Typisch ist die stark eingeschränkte Außenrotation.", "AC-Gelenk-Sprengung: Sturz auf die Schulter. Je nach Grad reißen AC- und coracoclaviculäre Bänder, das Schlüsselbein steht dann hoch (Klaviertastenphänomen)."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-sch-subakromial.webp", "t": "Subakromialer Raum, rechte Schulter von vorne-lateral.", "c": "1 Akromion, 2 Lig. coracoacromiale, 3 Bursa subacromialis, 4 Supraspinatussehne, 5 Tuberculum majus."}]}, {"merk": "Painful arc zwischen 60 und 120° spricht für den subakromialen Raum, Schmerz erst endgradig eher für das AC-Gelenk."}]}], "quellen": ["Schünke M, Schulte E, Schumacher U. Prometheus LernAtlas Allgemeine Anatomie und Bewegungssystem", "Kapandji IA. Funktionelle Anatomie der Gelenke, Band 1", "Kaltenborn FM. Manuelle Mobilisation der Extremitätengelenke", "Beard DJ et al. Arthroscopic subacromial decompression for subacromial shoulder pain (CSAW). Lancet 2018", "Lewis J. Rotator cuff related shoulder pain. Man Ther 2016"], "fragen": [["Welcher Muskel setzt am Tuberculum minus an?", ["M. supraspinatus", "M. infraspinatus", "M. subscapularis", "M. teres minor"], 2, "Der Subscapularis ist der einzige Innenrotator der Manschette und setzt vorne am Tuberculum minus an."], ["Welche Struktur ist mit der 1 markiert?", ["M. infraspinatus", "M. supraspinatus", "M. teres minor", "M. trapezius"], 1, "Der Supraspinatus liegt oberhalb der Spina scapulae und zieht unter dem Schulterdach zum oberen Tuberculum majus.", "fortbildung/bilder/2026-W47/ana-sch-rm.webp"], ["Wie lautet das Kapselmuster der Schulter?", ["Innenrotation vor Abduktion vor Außenrotation", "Außenrotation vor Abduktion vor Innenrotation", "Flexion vor Extension", "Abduktion vor Flexion vor Außenrotation"], 1, "Die Außenrotation ist zuerst und am stärksten eingeschränkt, typisch bei der Frozen Shoulder."], ["Wohin gleitet der Humeruskopf bei Abduktion?", ["Nach kranial", "Nach kaudal", "Nach ventral", "Nach dorsal"], 1, "Der konvexe Kopf gleitet gegensinnig: Arm nach oben, Kopf nach unten."], ["Welcher Nerv läuft durch die laterale Achsellücke?", ["N. suprascapularis", "N. radialis", "N. axillaris", "N. thoracicus longus"], 2, "Der N. axillaris zieht mit der A. circumflexa humeri posterior durch die laterale Achsellücke um den Humerushals.", "fortbildung/bilder/2026-W47/ana-sch-nerven.webp"], ["Welche Struktur ist mit der 4 markiert?", ["Lig. glenohumerale superius", "Recessus axillaris", "Labrum glenoidale", "Lange Bizepssehne"], 1, "Die schlaffe untere Kapseltasche entfaltet sich bei Elevation. Bei der Frozen Shoulder verklebt sie.", "fortbildung/bilder/2026-W47/ana-sch-glenoid.webp"], ["Ein Patient hat eine abstehende Scapula alata. Welcher Nerv ist am wahrscheinlichsten betroffen?", ["N. accessorius", "N. thoracicus longus", "N. dorsalis scapulae", "N. axillaris"], 1, "Der N. thoracicus longus versorgt den Serratus anterior, der das Schulterblatt am Brustkorb hält."], ["Wie verteilt sich die volle Elevation grob zwischen Schultergelenk und Schulterblatt?", ["1 : 1", "2 : 1", "3 : 1", "1 : 2"], 1, "Etwa 120° kommen aus dem Glenohumeralgelenk und 60° aus der Drehung des Schulterblatts."], ["In welche Richtung luxiert die Schulter am häufigsten?", ["Nach hinten", "Nach oben", "Nach vorne-unten", "Nach innen"], 2, "Über 90 Prozent der Luxationen gehen nach vorne-unten, oft mit Bankart-Läsion und Hill-Sachs-Delle."], ["Welche Struktur ist mit der 3 markiert?", ["Supraspinatussehne", "Bursa subacromialis", "Lig. coracoacromiale", "AC-Gelenk"], 1, "Die Bursa subacromialis liegt zwischen Schulterdach und Supraspinatussehne und lässt die Sehne gleiten.", "fortbildung/bilder/2026-W47/ana-sch-subakromial.webp"], ["Was zeigte die CSAW-Studie 2018 zur subakromialen Dekompression?", ["Deutlich besser als Übungen", "Nicht besser als eine Schein-Operation", "Nur bei Jüngeren wirksam", "Besser als jede andere Behandlung"], 1, "Die Dekompression war einer reinen Arthroskopie ohne Knochenabtragung nicht überlegen."]], "info": {"subakromial": {"t": "Subakromialer Raum", "x": ["Kein Gelenk, sondern ein Gleitraum zwischen Schulterdach und Humeruskopf. Die Bursa subacromialis liegt über der Supraspinatussehne und lässt sie unter dem Dach gleiten.", "Im Röntgen misst man den Abstand zwischen Akromion und Humeruskopf. Ist er deutlich verkleinert, steht der Kopf hoch, meist bei großer Rotatorenmanschettenruptur."]}, "ighl": {"t": "Unteres glenohumerales Band", "x": ["Ein Komplex aus vorderem Bündel, hinterem Bündel und dem Recessus axillaris dazwischen. Wie eine Hängematte trägt er den Kopf von unten.", "In Abduktion und Außenrotation spannt sich das vordere Bündel und hält den Kopf vorne. Genau hier reißt es bei der vorderen Luxation, oft zusammen mit dem Labrum. Das obere Band hemmt dagegen vor allem bei hängendem Arm."]}, "chl": {"t": "Lig. coracohumerale", "x": ["Liegt im Rotatorenintervall, dem Spalt zwischen Supraspinatus und Subscapularis, zusammen mit dem oberen glenohumeralen Band.", "Bei der Frozen Shoulder ist es oft verdickt und verkürzt. Das erklärt, warum die Außenrotation bei hängendem Arm so früh und so stark eingeschränkt ist."]}, "konvexkonkav": {"t": "Regel und Wirklichkeit", "x": ["In Messungen folgt der Humeruskopf der Regel nicht immer. Spannt sich die Kapsel auf einer Seite, schiebt sie den Kopf zur Gegenseite.", "Bei Frozen Shoulder brachte in einer kleinen Studie mit 20 Patienten ein Gleiten nach dorsal im Mittel 31° mehr Außenrotation, ein Gleiten nach ventral nur 3°. Die Regel ist also ein Ausgangspunkt, die Richtung prüft man am Befund."], "q": "Johnson AJ et al., JOSPT 2007"}, "kapselmuster": {"t": "Kapselmuster nach Cyriax", "x": ["Ein gelenktypisches Verhältnis der Bewegungseinschränkung, wenn die ganze Kapsel betroffen ist, etwa bei Frozen Shoulder, Arthrose oder nach Ruhigstellung.", "Ist nur eine Richtung eingeschränkt, etwa allein die Innenrotation, spricht das eher für eine lokale Ursache wie eine verkürzte hintere Kapsel oder ein Sehnenproblem."]}, "alata": {"t": "Scapula alata", "x": ["Medial abstehender Rand bei Serratusschwäche (N. thoracicus longus): Das Schulterblatt steht medial ab und wandert nach oben-medial. Gut sichtbar beim Wandliegestütz.", "Lateral abstehend bei Trapeziusschwäche (N. accessorius), oft nach Eingriffen am seitlichen Hals. Dann hängt die Schulter, und die Abduktion fällt schwer."]}, "spinoglenoidal": {"t": "Incisura spinoglenoidalis", "x": ["Am Hals der Spina zieht der Nerv durch eine zweite Engstelle zum Infraspinatus. Der Supraspinatus ist dann schon versorgt und bleibt intakt.", "Ursachen sind Zug bei Überkopfsport, etwa Volleyball, und Zysten, die von einem Labrumriss ausgehen. Zeichen: Atrophie in der Fossa infraspinata und schwache Außenrotation, oft ohne viel Schmerz."]}, "csaw": {"t": "Studien zur Dekompression", "x": ["CSAW (Großbritannien, 313 Patienten): Dekompression, reine Arthroskopie ohne Dekompression oder keine Behandlung. Nach 6 Monaten kein Unterschied zwischen Dekompression und Schein-OP. Beide OP-Gruppen lagen nur knapp und klinisch nicht relevant vor der Gruppe ohne Behandlung.", "FIMPACT (Finnland, 210 Patienten) verglich zusätzlich mit Übungstherapie. Nach 2 Jahren lag die Dekompression nur unterhalb der klinisch relevanten Schwelle vorn."], "q": "Beard DJ et al., Lancet 2018; Paavola M et al., BMJ 2018"}, "bankart": {"t": "Bankart und Hill-Sachs", "x": ["Bankart-Läsion: Abriss des vorderen-unteren Labrums samt Kapsel-Band-Ansatz vom Pfannenrand, manchmal mit Knochenstück (knöcherner Bankart).", "Hill-Sachs-Delle: Impression hinten-oben am Humeruskopf, entstanden beim Anschlagen an den Pfannenrand. Beide fördern weitere Luxationen, besonders bei jungen, sportlichen Patienten. Große knöcherne Defekte sprechen eher für eine Operation."]}}}, {"id": "w47-ana-lws", "titel": "Lendenwirbelsäule", "art": "ana", "min": 12, "abschnitte": [{"t": "1. Aufbau im Überblick", "b": [{"p": ["Die LWS besteht aus fünf Wirbeln mit den größten Wirbelkörpern der Wirbelsäule. Sie trägt das meiste Gewicht und bildet eine Lordose. Funktionelle Einheit ist das Bewegungssegment: zwei Wirbel, die Bandscheibe dazwischen, die beiden Facettengelenke, Bänder und segmentale Muskeln."]}, {"tab": [["Wirbelkörper", "Groß und nierenförmig, nach unten zunehmend breiter"], ["Proc. costalis", "Der lange „Querfortsatz“ der LWS ist eigentlich ein Rippenrest"], ["Facettengelenke", "Gelenkflächen fast sagittal ausgerichtet. Das erlaubt viel Flexion und Extension, aber kaum Rotation. Bei L5/S1 stehen sie frontaler"], ["Proc. spinosus", "Kurz, kräftig und waagerecht. Gut tastbar, die [[Linie über die Beckenkämme|tuffier]] trifft etwa L4"], ["Foramen vertebrale", "Dreieckig. Das [[Rückenmark endet|conus]] meist auf Höhe L1/L2, darunter liegt die Cauda equina"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-lws-wirbel.webp", "t": "Lendenwirbel von oben.", "c": "1 Wirbelkörper, 2 Pediculus, 3 Proc. costalis, 4 Proc. articularis superior mit Gelenkfläche, 5 Proc. spinosus, 6 Foramen vertebrale. Vorne liegt im Bild unten."}]}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."], "merk": "Sagittal stehende Facetten in der LWS: viel Beugen und Strecken, wenig Rotation."}]}, {"t": "2. Bandscheibe und Bänder", "b": [{"tab": [["Nucleus pulposus", "Gallertkern mit viel Wasser, verteilt den Druck gleichmäßig auf den Faserring. Verliert mit dem Alter Wasser"], ["Anulus fibrosus", "Faserring aus schräg gekreuzten Lamellen. Nur das äußere Drittel ist [[innerviert|sinuvertebral]] und kann schmerzen"], ["Ernährung", "Ohne eigene Gefäße, über Diffusion aus den [[Endplatten|endplatte]]. Wechsel von Be- und Entlastung hilft"], ["Lig. longitudinale anterius", "Breit, vorne an den Wirbelkörpern, hemmt die Extension"], ["Lig. longitudinale posterius", "Hinten im Wirbelkanal, wird in der LWS nach unten schmaler. Deshalb treten Vorfälle meist seitlich davon (posterolateral) aus"], ["Lig. flavum", "Gelb und elastisch zwischen den Wirbelbögen, hemmt die Flexion. Verdickt kann es den Kanal einengen"], ["Ligg. interspinalia und supraspinale", "Zwischen und über den Dornfortsätzen, hemmen die Flexion"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-lws-segment.webp", "t": "Bewegungssegment im Längsschnitt, Blick von der Seite.", "c": "1 Nucleus pulposus, 2 Anulus fibrosus, 3 Lig. longitudinale anterius, 4 Lig. longitudinale posterius, 5 Lig. flavum, 6 Lig. interspinale. Vorne liegt im Bild links."}]}, {"merk": "Das hintere Längsband deckt in der LWS nur die Mitte ab. Vorfälle gehen deshalb meist posterolateral."}]}, {"t": "3. Muskeln", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W47/ana-lws-quer.webp", "t": "Querschnitt auf Höhe L3, Blick von oben.", "c": "1 M. multifidus, 2 M. erector spinae, 3 M. quadratus lumborum, 4 M. psoas major, 5 Fascia thoracolumbalis. Vorne liegt im Bild oben."}]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-lws-muskeln2.webp", "t": "Rumpf von rechts, Bauchwand gefenstert.", "c": "6 M. transversus abdominis mit queren Fasern, 7 Fascia thoracolumbalis. Vorne liegt im Bild links."}]}, {"mus": [{"n": "M. multifidus", "p": [[40.9, 59.4]], "z": "1", "u": "Kreuzbein, Processus mammillares der LWS", "a": "Dornfortsätze 2–4 Segmente höher", "i": "Rr. dorsales der Spinalnerven, segmental", "f": "Segmentale Stabilität und Extension. Bei Rückenschmerz oft verkleinert und verfettet"}, {"n": "M. erector spinae", "p": [[26.9, 68.8]], "z": "2", "u": "Kreuzbein, Darmbeinkamm, Dornfortsätze der LWS", "a": "Rippen, Querfortsätze, bis zum Hinterhaupt", "i": "Rr. dorsales der Spinalnerven", "f": "Extension, Lateralflexion. Bremst die Flexion beim Vorbeugen"}, {"n": "M. quadratus lumborum", "p": [[17.7, 46.2]], "z": "3", "u": "Darmbeinkamm, Lig. iliolumbale", "a": "12. Rippe, Proc. costales L1–L4", "i": "N. subcostalis und Plexus lumbalis (Th12–L4)", "f": "Lateralflexion, hebt das Becken einseitig, fixiert die 12. Rippe"}, {"n": "M. psoas major", "p": [[28.9, 29.1]], "z": "4", "u": "Wirbelkörper und Proc. costales Th12–L4", "a": "Trochanter minor (mit dem Iliacus)", "i": "Plexus lumbalis (L1–L3)", "f": "Hüftflexion. Zieht bei fixiertem Bein die LWS in die Lordose"}, {"n": "M. transversus abdominis", "p": [[47.2, 56.9]], "b": "ana-lws-muskeln2.webp", "z": "6", "u": "Rippen 7–12 innen, Fascia thoracolumbalis, Darmbeinkamm, Leistenband", "a": "Rektusscheide und Linea alba", "i": "Nn. intercostales Th7–Th12, N. iliohypogastricus, N. ilioinguinalis", "f": "Bauchpresse, spannt die Fascia thoracolumbalis"}]}, {"merk": "Der Multifidus liegt direkt am Wirbelbogen und arbeitet segmental. Der Erector spinae liegt lateral davon und bewegt die ganze Wirbelsäule."}]}, {"t": "4. Biomechanik", "b": [{"p": ["Druck in der Bandscheibe L4/5, gemessen von [[Wilke und Kollegen 1999|wilke]] mit einem Sensor im Nucleus. Der Balken zeigt den Druck im Verhältnis zum größten gemessenen Wert, rechts steht der Druck in Megapascal."]}, {"bars": [["Rückenlage", 4, "0,10 MPa"], ["Seitenlage", 5, "0,12 MPa"], ["Sitzen entspannt", 20, "0,46 MPa"], ["Stehen entspannt", 22, "0,50 MPa"], ["Vorgebeugt stehen", 48, "1,10 MPa"], ["20 kg heben mit gebeugten Knien", 74, "1,70 MPa"], ["20 kg heben mit rundem Rücken", 100, "2,30 MPa"]]}, {"l": ["Entspanntes Sitzen belastet die Bandscheibe nach diesen Messungen nicht mehr als Stehen. Das widerspricht den älteren Werten von Nachemson aus den 1960ern.", "Bei Flexion verschiebt sich der Nucleus nach hinten und die Facettengelenke öffnen sich. Bei Extension wandert der Nucleus nach vorne und die Facetten schließen.", "Der größte Teil der Bewegung findet in L4/5 und L5/S1 statt.", "[[Gekoppelte Bewegungen|kopplung]] von Lateralflexion und Rotation sind in der LWS uneinheitlich. Studien finden kein festes Muster.", "Bewegungsausmaß der gesamten LWS ungefähr: Flexion 40–60°, Extension 20–35°, Lateralflexion je 20–30°, Rotation je 5–10°."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-lws-flexext.webp", "t": "Bewegungssegment in Flexion und Extension, Blick von der Seite.", "c": "Links Flexion: Facetten öffnen sich, der Nucleus wandert nach dorsal (Pfeil). Rechts Extension: Facetten schließen sich, der Nucleus wandert nach ventral. Vorne liegt im Bild links."}]}, {"merk": "Flexion: Nucleus nach hinten, Facetten auf. Extension: Nucleus nach vorne, Facetten zu."}]}, {"t": "5. Nerven", "b": [{"p": ["In der LWS tritt jede Nervenwurzel unter dem gleichnamigen Wirbel aus: L4 im Foramen L4/5. Ein typischer posterolateraler Vorfall L4/5 trifft aber meist die Wurzel L5, die dort im Kanal nach unten zieht. Ein [[weit lateraler Vorfall|lateral]] im Foramen trifft die austretende Wurzel L4."]}, {"tab": [["L3", "Kennmuskel Quadrizeps, Reflex PSR (mit L4), Haut Oberschenkel vorne bis Knie"], ["L4", "Kennmuskel Tibialis anterior, Reflex PSR, Haut Unterschenkel innen bis Innenknöchel"], ["L5", "Kennmuskel Extensor hallucis longus, Haut Unterschenkel außen und Fußrücken bis zur Großzehe"], ["S1", "Kennmuskeln Wade und Peronäen, Reflex ASR, Haut lateraler Fußrand und Kleinzehe"], ["[[Cauda-equina-Syndrom|cauda]]", "Reithosenanästhesie, Blasen- oder Mastdarmstörung, beidseitige Ausfälle: sofort in die Klinik"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-lws-prolaps.webp", "t": "Posterolateraler Bandscheibenvorfall, Blick von oben.", "c": "1 Vorfall des Nucleus durch den Faserring, 2 bedrängte Nervenwurzel, 3 Duralsack mit Cauda equina, 4 Facettengelenk. Vorne liegt im Bild unten."}]}, {"merk": "Posterolateraler Vorfall L4/5 trifft meist L5, L5/S1 meist S1."}]}, {"t": "6. Klinische Bezüge", "b": [{"l": ["Spondylolyse: Ermüdungsbruch in der Pars interarticularis, meist L5, häufig bei Sportarten mit viel Hohlkreuz. Rutscht der Wirbel nach vorne, ist es eine Spondylolisthese, eingeteilt nach [[Meyerding I–IV|meyerding]].", "Spinalkanalstenose: Bei Älteren durch Bandscheibe, verdicktes Lig. flavum und Facettenarthrose. Typisch ist die [[Claudicatio spinalis|claudicatio]]: Beinschmerz beim Gehen, besser beim Vorbeugen oder Sitzen.", "Facettensyndrom: Lokaler Schmerz, schlimmer bei Extension und Rotation. Es gibt keinen Test, der es sicher nachweist.", "Unspezifischer Rückenschmerz: Bei den meisten lässt sich keine sichere Struktur als Ursache finden. Bildbefunde wie Vorwölbungen sind auch bei Schmerzfreien häufig."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-lws-listhese.webp", "t": "Spondylolisthese L5/S1, Blick von der Seite.", "c": "Der Spalt in der Pars interarticularis (Pfeil) trennt Wirbelkörper und Bogen. Der Wirbelkörper L5 ist auf S1 nach vorne gerutscht. Vorne liegt im Bild links."}]}, {"merk": "Stenose: besser beim Vorbeugen. Bandscheibe: oft schlechter beim Vorbeugen und Sitzen."}]}], "quellen": ["Schünke M, Schulte E, Schumacher U. Prometheus LernAtlas Allgemeine Anatomie und Bewegungssystem", "Wilke HJ et al. New in vivo measurements of pressures in the intervertebral disc in daily life. Spine 1999", "Bogduk N. Clinical and Radiological Anatomy of the Lumbar Spine. 5. Aufl. 2012", "Brinjikji W et al. Systematic literature review of imaging features of spinal degeneration in asymptomatic populations. AJNR 2015", "Nationale VersorgungsLeitlinie Nicht-spezifischer Kreuzschmerz, 2. Aufl. 2017"], "fragen": [["Warum ist Rotation in der LWS kaum möglich?", ["Die Bandscheiben sind zu dünn", "Die Facettengelenke stehen fast sagittal", "Die Rippen blockieren", "Das Lig. flavum hemmt sie"], 1, "Die sagittal ausgerichteten Gelenkflächen stoßen bei Rotation schnell aneinander."], ["Welche Struktur ist mit der 3 markiert?", ["Proc. spinosus", "Pediculus", "Proc. costalis", "Proc. articularis superior"], 2, "Der lange seitliche Fortsatz der LWS ist ein Rippenrest und heißt Proc. costalis.", "fortbildung/bilder/2026-W47/ana-lws-wirbel.webp"], ["Warum treten Bandscheibenvorfälle in der LWS meist posterolateral aus?", ["Weil der Nucleus dort weicher ist", "Weil das hintere Längsband in der LWS nach unten schmaler wird", "Weil das vordere Längsband fehlt", "Weil die Facetten dort Druck ausüben"], 1, "Das Lig. longitudinale posterius deckt nur die Mitte ab. Seitlich davon ist der Faserring schwächer geschützt."], ["Welche Struktur ist mit der 5 markiert?", ["Lig. interspinale", "Lig. flavum", "Lig. longitudinale posterius", "Duralsack"], 1, "Das gelbliche, elastische Lig. flavum verbindet die Wirbelbögen.", "fortbildung/bilder/2026-W47/ana-lws-segment.webp"], ["Welcher Muskel ist mit der 1 markiert?", ["M. erector spinae", "M. quadratus lumborum", "M. multifidus", "M. psoas major"], 2, "Der Multifidus liegt direkt am Wirbelbogen neben dem Dornfortsatz.", "fortbildung/bilder/2026-W47/ana-lws-quer.webp"], ["Wie hoch war laut Wilke 1999 der Druck in der Bandscheibe im entspannten Sitzen verglichen mit dem Stehen?", ["Etwa doppelt so hoch", "Etwa gleich oder etwas niedriger", "Etwa halb so hoch", "Etwa viermal so hoch"], 1, "Entspanntes Sitzen lag mit 0,46 MPa sogar knapp unter dem Stehen mit 0,50 MPa."], ["Wohin wandert der Nucleus pulposus bei Flexion?", ["Nach ventral", "Nach dorsal", "Nach kranial", "Er bleibt in der Mitte"], 1, "Vorne wird die Bandscheibe zusammengedrückt, der Nucleus weicht nach hinten aus."], ["Ein posterolateraler Vorfall L4/5 trifft meist welche Wurzel?", ["L3", "L4", "L5", "S1"], 2, "Die Wurzel L4 ist schon oberhalb ausgetreten. Im Kanal zieht hier L5 nach unten und wird bedrängt."], ["Schwäche der Großzehenhebung und Taubheit am Fußrücken passen zu welcher Wurzel?", ["L3", "L4", "L5", "S1"], 2, "Kennmuskel für L5 ist der Extensor hallucis longus, das Dermatom zieht über den Fußrücken zur Großzehe."], ["Was ist mit dem Pfeil markiert?", ["Bandscheibenvorfall", "Spalt in der Pars interarticularis", "Facettenarthrose", "Wirbelkörperfraktur"], 1, "Der Spalt in der Pars interarticularis (Spondylolyse) erlaubt das Abrutschen des Wirbelkörpers nach vorne.", "fortbildung/bilder/2026-W47/ana-lws-listhese.webp"], ["Welches Zeichen spricht für eine Spinalkanalstenose?", ["Schmerz beim Vorbeugen", "Beinschmerz beim Gehen, besser beim Vorbeugen oder Sitzen", "Nur nächtlicher Schmerz", "Schmerz beim Husten im Liegen"], 1, "In Flexion wird der Kanal weiter, deshalb bessern Vorbeugen und Sitzen die Beschwerden."]], "info": {"tuffier": {"t": "Tuffier-Linie", "x": ["Die Verbindungslinie der Beckenkammhöhen, auch Jacoby-Linie genannt. Sie ist nur ein grober Orientierungspunkt: Je nach Person und Körperbau liegt sie auf unterschiedlicher Höhe, und die getastete Höhe stimmt oft nicht genau mit dem Röntgenbild überein.", "Deshalb die Höhe gegenprüfen, etwa vom Kreuzbein aus nach oben zählen. Die Spinae iliacae posteriores superiores liegen etwa auf Höhe S2."]}, "conus": {"t": "Conus medullaris", "x": ["Das kegelförmige Ende des Rückenmarks liegt beim Erwachsenen meist bei L1/L2, beim Neugeborenen tiefer. Deshalb wird die Lumbalpunktion unterhalb von L3 gemacht.", "Abgrenzung: Ein Konus-Syndrom macht früh und eher symmetrisch Blasen-, Mastdarm- und Sexualstörungen bei wenig Schmerz. Beim Cauda-equina-Syndrom stehen radikuläre Schmerzen und oft seitenungleiche Ausfälle im Vordergrund. Beides ist ein Notfall."]}, "sinuvertebral": {"t": "N. sinuvertebralis", "x": ["Der hintere Anulus und das hintere Längsband werden vom N. sinuvertebralis versorgt, einem rückläufigen Ast aus Spinalnerv und Sympathikus. Die seitlichen und vorderen Anteile bekommen Äste aus dem Grenzstrang.", "In degenerierten Bandscheiben können Nervenfasern und Gefäße entlang von Rissen tiefer in den Anulus einwachsen. Das ist eine Erklärung für diskogenen Schmerz ohne Vorfall."]}, "endplatte": {"t": "Endplatte", "x": ["Dünne Schicht aus hyalinem Knorpel auf der knöchernen Deck- und Grundplatte des Wirbelkörpers. Über sie gelangen Nährstoffe in die Bandscheibe, mit dem Alter verkalkt sie und lässt weniger durch.", "Bricht Bandscheibengewebe durch die Endplatte in den Wirbelkörper, entsteht ein Schmorl-Knötchen. Signalveränderungen des angrenzenden Knochens im MRT heißen Modic-Veränderungen."]}, "wilke": {"t": "Wilke 1999", "x": ["Gemessen wurde bei einer einzigen Person: einem 45-jährigen Mann mit 70 kg und gesunder Bandscheibe L4/5, über etwa 24 Stunden.", "Die Werte sind deshalb gute Anhaltspunkte, aber nicht auf alle übertragbar. Nachemson hatte für Sitzen deutlich höhere Drücke als für Stehen gemessen. Davon stammt die alte Regel, Sitzen sei schlecht für die Bandscheibe, die Wilkes Messung so nicht bestätigt."], "q": "Wilke HJ et al., Spine 1999"}, "kopplung": {"t": "Kopplungsregeln", "x": ["Nach den älteren Regeln von Lovett und Fryette sollen Seitneigung und Rotation in Neutralstellung gegensinnig, in Flexion oder Extension gleichsinnig gekoppelt sein. Darauf bauen manche Mobilisationskonzepte.", "Übersichtsarbeiten finden dafür keine verlässliche Grundlage: Richtung und Ausmaß schwanken zwischen Personen, Segmenten und Ausgangsstellungen. Behandlungsrichtung deshalb nach Befund und Reaktion wählen, nicht nach einer angenommenen Kopplung."], "q": "Legaspi O, Edmond SL, JOSPT 2007; Cook C, JMMT 2003"}, "lateral": {"t": "Weit lateraler Vorfall", "x": ["Der Vorfall liegt im oder außerhalb des Foramens und trifft die dort austretende Wurzel, bei L4/5 also L4. Er ist deutlich seltener als der posterolaterale Vorfall.", "Bei L4 oder L3 passen Schmerz vorne am Oberschenkel, Quadrizepsschwäche und ein abgeschwächter PSR. Der Femoralis-Dehntest in Bauchlage ist dann oft aussagekräftiger als der Lasègue."]}, "cauda": {"t": "Cauda-equina-Syndrom", "x": ["Frühe Zeichen werden leicht übersehen: neu veränderter Harndrang, schwacher Strahl, Gefühl unvollständiger Entleerung, Taubheit am Damm oder Gesäß, Ischias auf beiden Seiten.", "Gezielt nachfragen, auch wenn der Patient es nicht anspricht. Schon bei Verdacht am selben Tag in die Notaufnahme schicken, nicht bis zum nächsten Termin warten. Je früher entlastet wird, desto eher bleibt die Blasenfunktion erhalten."]}, "meyerding": {"t": "Einteilung nach Meyerding", "x": ["Gemessen wird, wie weit der obere Wirbel auf dem unteren nach vorne gerutscht ist, bezogen auf die Tiefe des Wirbelkörpers. Grad I bis 25 %, II bis 50 %, III bis 75 %, IV bis 100 %. Ist der Wirbel ganz abgerutscht, spricht man von Spondyloptose (oft als Grad V geführt).", "Grad I und II werden meist konservativ behandelt. Bei zunehmendem Gleiten oder neurologischen Ausfällen ärztlich vorstellen."]}, "claudicatio": {"t": "Spinal oder vaskulär?", "x": ["Bei der vaskulären Claudicatio reicht kurzes Stehenbleiben, die Fußpulse sind oft schwach, und auch Radfahren macht Beschwerden. Bei der spinalen hilft erst Hinsetzen oder Vorbeugen, Radfahren geht meist gut.", "Typisch spinal ist auch das Einkaufswagen-Zeichen: Mit vorgebeugtem Oberkörper kann der Patient deutlich weiter gehen. Beides kann gleichzeitig vorliegen."]}}}, {"id": "w47-ana-hws", "titel": "Halswirbelsäule", "art": "ana", "min": 12, "abschnitte": [{"t": "1. Aufbau im Überblick", "b": [{"p": ["Die HWS hat sieben Wirbel und zwei funktionell verschiedene Abschnitte. Die obere HWS (Kopfgelenke C0–C2) ist auf Nicken und Drehen spezialisiert. Die untere HWS (C2–C7) macht den Rest der Bewegung und trägt den Kopf."]}, {"tab": [["Atlas (C1)", "Ring ohne Wirbelkörper und ohne Dornfortsatz. Die konkaven oberen Gelenkflächen tragen das Hinterhaupt"], ["Axis (C2)", "Mit dem Dens, um den sich der Atlas dreht. Erster tastbarer großer Dornfortsatz unter dem Hinterhaupt"], ["C3–C6", "Kleine Wirbelkörper mit Processus uncinati (Unkovertebralgelenke), gespaltene Dornfortsätze"], ["[[C7 (Vertebra prominens)|prominens]]", "Langer, nicht gespaltener Dornfortsatz, meist der am besten tastbare"], ["Foramen transversarium", "Loch im Querfortsatz von C1–C6 für die A. vertebralis"], ["Facettengelenke", "Etwa 45° geneigt zwischen frontal und horizontal. Daher sind Lateralflexion und Rotation gekoppelt"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hws-atlas.webp", "t": "Atlas und Axis von oben-hinten.", "c": "1 Dens axis, 2 Lig. transversum atlantis, 3 Lig. alare, 4 obere Gelenkfläche des Atlas, 5 A. vertebralis."}]}, {"p": ["KI-erstellte Lehrbilder nach Atlas-Vorbild, geprüft, keine echten Präparate."], "merk": "C1 nickt, C1/C2 dreht. Etwa die Hälfte der gesamten HWS-Rotation entsteht zwischen Atlas und Axis."}]}, {"t": "2. Bänder und Unkovertebralgelenke", "b": [{"tab": [["Lig. transversum atlantis", "Hält den Dens am vorderen Atlasbogen. [[Lockerung|instabil]] (z. B. bei rheumatoider Arthritis oder Trisomie 21) kann das Rückenmark gefährden"], ["Ligg. alaria", "Von der Densspitze zum Hinterhauptsrand, [[hemmen Rotation und Lateralflexion|alaria]] der Kopfgelenke"], ["Membrana tectoria", "Fortsetzung des hinteren Längsbands bis zum Hinterhaupt"], ["Lig. nuchae", "Kräftige Platte zwischen Hinterhaupt und Dornfortsätzen, Ansatz für Nackenmuskeln"], ["Unkovertebralgelenke", "Seitliche Aufwölbungen am Oberrand der Wirbelkörper C3–C7 führen die Bewegung und schützen die Bandscheibe seitlich. Mit dem Alter bilden sich hier Osteophyten, die das Foramen intervertebrale einengen"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hws-unko.webp", "t": "Halswirbel C5 und C6 von vorne.", "c": "1 Processus uncinatus, 2 Unkovertebralgelenk, 3 Bandscheibe, 4 Foramen transversarium mit A. vertebralis, 5 Foramen intervertebrale mit Nervenwurzel."}]}, {"merk": "Vor Manipulation der oberen HWS: Ligg. alaria und Lig. transversum sind die wichtigsten Stabilisatoren. Bei Rheuma oder nach Trauma vorher abklären."}]}, {"t": "3. Muskeln", "b": [{"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hws-muskeln.webp", "t": "Hals von der rechten Seite.", "c": "1 M. sternocleidomastoideus, 2 M. scalenus anterior, 3 M. scalenus medius, 4 M. levator scapulae, 5 M. trapezius pars descendens, 6 Plexus brachialis in der hinteren Skalenuslücke. Vorne liegt im Bild links."}]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hws-muskeln2.webp", "t": "Links HWS von vorne in der Tiefe, rechts Nacken von hinten in der Tiefe.", "c": "7 M. longus colli, 8 suboccipitale Muskeln (M. rectus capitis posterior major)."}]}, {"mus": [{"n": "M. sternocleidomastoideus", "p": [[35.6, 42.8]], "z": "1", "u": "Manubrium sterni und mediales Drittel der Clavicula", "a": "Proc. mastoideus und Linea nuchae superior", "i": "N. accessorius (XI) und Plexus cervicalis (C2–C3)", "f": "Einseitig: Seitneigung zur gleichen, Rotation zur Gegenseite. Beidseitig: Kopf nach vorne schieben, Hilfsatemmuskel"}, {"n": "Mm. scaleni", "p": [[46.9, 62.5], [54.7, 57.2]], "z": "2–3", "u": "Querfortsätze C2–C7", "a": "Anterior und medius: 1. Rippe; posterior: 2. Rippe", "i": "Rr. ventrales C3–C8", "f": "Heben die oberen Rippen (Atemhilfe), Seitneigung der HWS"}, {"n": "M. longus colli", "p": [[22.4, 45.8]], "b": "ana-hws-muskeln2.webp", "z": "7", "u": "Wirbelkörper und Querfortsätze C3–Th3", "a": "Wirbelkörper und vorderer Atlasbogen", "i": "Rr. ventrales C2–C6", "f": "Tiefer Flexor, stabilisiert die HWS-Lordose. Wird mit dem kraniozervikalen Flexionstest geprüft"}, {"n": "Mm. suboccipitales", "p": [[79.8, 30.5]], "b": "ana-hws-muskeln2.webp", "z": "8", "u": "Rectus capitis posterior major und minor, Obliquus capitis superior und inferior zwischen Atlas, Axis und Hinterhaupt", "a": "Hinterhaupt und Atlas", "i": "N. suboccipitalis (C1)", "f": "Feinsteuerung von Nicken und Drehen der Kopfgelenke, viele Muskelspindeln"}, {"n": "M. trapezius pars descendens", "p": [[83.9, 56.2]], "z": "5", "u": "Hinterhaupt, Lig. nuchae", "a": "Laterales Drittel der Clavicula", "i": "N. accessorius (XI)", "f": "Hebt das Schulterblatt, Extension und Seitneigung der HWS"}, {"n": "M. levator scapulae", "p": [[66.6, 50.6]], "z": "4", "u": "Querfortsätze C1–C4", "a": "Angulus superior des Schulterblatts", "i": "N. dorsalis scapulae (C4–C5)", "f": "Hebt das Schulterblatt und dreht es nach unten"}]}, {"merk": "Plexus brachialis und A. subclavia ziehen durch die [[hintere Skalenuslücke|skalenus]] zwischen Scalenus anterior und medius."}]}, {"t": "4. Biomechanik", "b": [{"l": ["C0/C1: vor allem Nicken, etwa 15–25° Flexion/Extension zusammen.", "C1/C2: etwa 40° [[Rotation zu jeder Seite|frt]], rund die Hälfte der gesamten HWS-Rotation.", "Untere HWS: Lateralflexion und Rotation sind wegen der geneigten Facetten zur gleichen Seite gekoppelt.", "Flexion der HWS weitet die Foramina intervertebralia, Extension mit Seitneigung und Rotation zur gleichen Seite engt sie ein. Darauf beruht der [[Spurling-Test|spurling]].", "Bewegungsausmaß der gesamten HWS ungefähr: Flexion/Extension 35–45/0/60–70°, Lateralflexion je 40–45°, Rotation je 60–80°."]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hws-foramen.webp", "t": "Foramen intervertebrale in Flexion und Extension, Blick von der Seite.", "c": "Links Flexion: Das Foramen ist weit. Rechts Extension: Das Foramen wird enger, die Nervenwurzel (gelb) hat weniger Platz. Vorne liegt im Bild links."}]}, {"merk": "Spurling-Test: Extension, Seitneigung und Rotation zur schmerzhaften Seite plus Druck von oben. Schmerz in den Arm spricht für eine Wurzelreizung."}]}, {"t": "5. Nerven und Gefäße", "b": [{"p": ["Anders als in der LWS tritt in der HWS jede Wurzel über dem gleichnamigen Wirbel aus: C6 im Foramen C5/6. Weil es acht zervikale Wurzeln, aber nur sieben Halswirbel gibt, tritt C8 zwischen C7 und Th1 aus."]}, {"tab": [["C5", "Kennmuskel Deltoideus, Reflex BSR (mit C6), Haut lateral am Oberarm"], ["C6", "Kennmuskel Bizeps und Handgelenksextensoren, Reflex BRR, Haut Daumen und radialer Unterarm"], ["C7", "Kennmuskel Trizeps, Reflex TSR, Haut Mittelfinger"], ["C8", "Kennmuskeln lange Fingerbeuger, Haut Klein- und Ringfinger"], ["A. vertebralis", "Zieht durch die Foramina transversaria C6–C1, dann hinter der Massa lateralis des Atlas zum Hinterhaupt. Bei Schwindel, Doppelbildern, Sprech- oder Schluckstörungen nach Kopfbewegung an eine [[Durchblutungsstörung|vertebralis]] denken"]]}, {"fig": [{"src": "fortbildung/bilder/2026-W47/ana-hws-wurzel.webp", "t": "Halswirbelsäule von der Seite mit Nervenwurzeln.", "c": "Die Wurzeln treten über dem gleichnamigen Wirbel aus: C6 zwischen C5 und C6, C8 zwischen C7 und Th1 (grüne Markierungen). Vorne liegt im Bild links."}]}, {"merk": "HWS: Wurzel tritt über dem gleichnamigen Wirbel aus. LWS: unter dem gleichnamigen Wirbel."}]}, {"t": "6. Klinische Bezüge", "b": [{"l": ["Zervikale Radikulopathie: Am häufigsten sind C6 und C7 betroffen, meist durch Bandscheibe oder Osteophyten der Unkovertebralgelenke. Ein Cluster aus Spurling, Distraktionstest, ULTT A und Rotation unter 60° erhöht die Wahrscheinlichkeit ([[Wainner 2003|wainner]]).", "Zervikale Myelopathie: Einengung des Rückenmarks bei Älteren. Ungeschickte Hände, unsicherer Gang, positives [[Hoffmann-Zeichen|hoffmann]]. Gehört in ärztliche Abklärung.", "Schleudertrauma (WAD): Meist gute Prognose. Kanadische HWS-Regel zur Entscheidung über Röntgen nach Unfall.", "Thoracic Outlet Syndrome: Enge für Plexus und Gefäße zwischen den Skalenusmuskeln, unter der Clavicula oder hinter dem Pectoralis minor.", "Vor Manipulation und endgradigen Techniken Warnzeichen für Gefäß- und Instabilitätsprobleme abfragen (IFOMPT-Rahmen 2020)."]}, {"merk": "Ungeschickte Hände und unsicherer Gang bei Nackenschmerz an eine Myelopathie denken und ärztlich abklären lassen."}]}], "quellen": ["Schünke M, Schulte E, Schumacher U. Prometheus LernAtlas Allgemeine Anatomie und Bewegungssystem", "Kapandji IA. Funktionelle Anatomie der Gelenke, Band 3", "Wainner RS et al. Reliability and diagnostic accuracy of the clinical examination for cervical radiculopathy. Spine 2003", "Rushton A et al. International Framework for Examination of the Cervical Region (IFOMPT) 2020", "Jull G et al. The craniocervical flexion test. J Manipulative Physiol Ther 2008"], "fragen": [["Wo entsteht etwa die Hälfte der HWS-Rotation?", ["C0/C1", "C1/C2", "C5/C6", "C7/Th1"], 1, "Der Atlas dreht sich um den Dens des Axis, etwa 40° zu jeder Seite."], ["Welche Struktur ist mit der 2 markiert?", ["Lig. alare", "Membrana tectoria", "Lig. transversum atlantis", "Lig. nuchae"], 2, "Das Lig. transversum spannt sich hinter dem Dens zwischen den Massae laterales und hält ihn am vorderen Atlasbogen.", "fortbildung/bilder/2026-W47/ana-hws-atlas.webp"], ["Welche Wurzel tritt im Foramen C5/C6 aus?", ["C5", "C6", "C7", "C4"], 1, "In der HWS tritt die Wurzel über dem gleichnamigen Wirbel aus, C6 also zwischen C5 und C6."], ["Schwäche des Trizeps und abgeschwächter TSR passen zu welcher Wurzel?", ["C5", "C6", "C7", "C8"], 2, "Der Trizeps ist Kennmuskel für C7, der Trizepssehnenreflex gehört zu C7."], ["Wodurch zieht der Plexus brachialis am Hals?", ["Vordere Skalenuslücke", "Hintere Skalenuslücke zwischen Scalenus anterior und medius", "Durch das Foramen transversarium", "Unter dem Sternocleidomastoideus durch die Clavicula"], 1, "Plexus und A. subclavia ziehen durch die hintere Skalenuslücke, die V. subclavia vor dem Scalenus anterior.", "fortbildung/bilder/2026-W47/ana-hws-muskeln.webp"], ["Was macht der M. sternocleidomastoideus bei einseitiger Kontraktion?", ["Seitneigung und Rotation zur gleichen Seite", "Seitneigung zur gleichen, Rotation zur Gegenseite", "Nur Flexion", "Rotation zur gleichen Seite und Extension"], 1, "Er neigt zur eigenen Seite und dreht das Gesicht zur Gegenseite."], ["Was ist mit der 1 markiert?", ["Foramen transversarium", "Processus uncinatus", "Gelenkfortsatz", "Querfortsatz"], 1, "Die seitliche Aufwölbung am Oberrand des Wirbelkörpers ist der Processus uncinatus. Mit dem Wirbel darüber bildet er das Unkovertebralgelenk.", "fortbildung/bilder/2026-W47/ana-hws-unko.webp"], ["Welche Bewegung engt das Foramen intervertebrale ein?", ["Flexion", "Extension mit Seitneigung und Rotation zur gleichen Seite", "Traktion", "Rotation zur Gegenseite in Flexion"], 1, "Darauf beruht der Spurling-Test."], ["Welcher Befund passt am ehesten zu einer zervikalen Myelopathie?", ["Einseitiger Armschmerz mit Dermatom", "Ungeschickte Hände, unsicherer Gang, Hoffmann-Zeichen", "Lokaler Nackenschmerz nach Zugluft", "Kopfschmerz beim Bücken"], 1, "Druck auf das Rückenmark führt zu Zeichen des ersten Motoneurons und zu Gang- und Feinmotorikstörungen."], ["Welcher Muskel wird mit dem kraniozervikalen Flexionstest geprüft?", ["M. sternocleidomastoideus", "M. longus colli", "M. trapezius", "M. scalenus anterior"], 1, "Der Test prüft die tiefen Halsbeuger, vor allem Longus colli und Longus capitis."], ["Wie viele zervikale Nervenwurzeln gibt es?", ["Sieben", "Acht", "Sechs", "Neun"], 1, "Acht Wurzeln bei sieben Wirbeln. C8 tritt zwischen C7 und Th1 aus."]], "info": {"prominens": {"t": "C6, C7 oder Th1?", "x": ["Der größte Dornfortsatz ist nicht immer C7, manchmal ist Th1 genauso deutlich. Zur Kontrolle zwei Finger auf benachbarte Dornfortsätze legen.", "Bei Extension der HWS gleitet der Dornfortsatz von C6 unter dem Finger nach vorne weg, C7 bleibt tastbar. Bei Rotation des Kopfes bewegt sich C7 deutlich mit, Th1 kaum."]}, "instabil": {"t": "Atlantoaxiale Instabilität", "x": ["Der Abstand zwischen vorderem Atlasbogen und Dens liegt im Röntgen beim Erwachsenen normal bei höchstens 3 mm, bei Kindern bei höchstens 5 mm.", "Hinweise: Gefühl, den Kopf nicht halten zu können, Kopf wird mit den Händen gestützt, Kribbeln in Händen oder Füßen auf beiden Seiten, elektrisierendes Gefühl bei Kopfbeugung.", "Dann keine Mobilisation oder Manipulation der oberen HWS und ärztlich abklären lassen, bei neurologischen Zeichen sofort."]}, "alaria": {"t": "Test der Ligg. alaria", "x": ["Die Bänder koppeln Kopf und Axis: Neigt sich der Kopf zur Seite, wird C2 sofort mitgedreht.", "Im Test tastet man den Dornfortsatz von C2 und neigt die Kopfgelenke passiv zur Seite. Er muss sich sofort mitbewegen. Bewegt er sich verzögert oder gar nicht und ist die Seitneigung weich und vergrößert, spricht das für eine Lockerung des Bandes."]}, "skalenus": {"t": "Vordere und hintere Skalenuslücke", "x": ["Hintere Lücke: zwischen Scalenus anterior und medius, über der ersten Rippe. Hier ziehen Plexus brachialis und A. subclavia durch.", "Vordere Lücke: vor dem Scalenus anterior, zum Sternocleidomastoideus hin. Hier läuft die V. subclavia. Der N. phrenicus liegt vorne auf dem Scalenus anterior.", "Ein verdickter Scalenus oder eine Halsrippe kann die hintere Lücke einengen und ein Thoracic Outlet Syndrome auslösen."]}, "frt": {"t": "Flexions-Rotations-Test", "x": ["Die HWS wird in Rückenlage voll gebeugt. Das sperrt die unteren Segmente, die Rotation kommt dann vor allem aus C1/C2. Normal sind etwa 44° zu jeder Seite.", "Positiv bei fester Begrenzung mit Schmerz und einer Rotation von höchstens 32° oder mehr als 10° unter dem Normalwert. Gebraucht wird der Test vor allem beim zervikogenen Kopfschmerz."], "q": "Ogince M et al., Man Ther 2007; Hall TM et al., JMPT 2008"}, "spurling": {"t": "Spurling-Test", "x": ["In der Studie von Wainner lag die Sensitivität bei 50 %, die Spezifität bei 86 %. Ein positiver Test spricht also eher für eine Radikulopathie, ein negativer schließt sie nicht aus.", "Positiv ist er nur, wenn der bekannte Armschmerz kommt. Nackenschmerz allein zählt nicht. Bei deutlicher Ausstrahlung vorsichtig dosieren und sofort abbrechen."], "q": "Wainner RS et al., Spine 2003"}, "vertebralis": {"t": "Vaskuläre Warnzeichen", "x": ["Merkhilfe 5 D und 3 N: Dizziness (Schwindel), Diplopie, Dysarthrie, Dysphagie, Drop Attacks, dazu Nystagmus, Nausea, Numbness (Taubheit, etwa im Gesicht).", "Treten sie auf, Behandlung abbrechen, nicht weiter testen und ärztlich abklären lassen. Neuer, ungewohnter Kopf- oder Nackenschmerz zusammen mit solchen Zeichen kann eine Dissektion oder ein Schlaganfall sein: Notruf 112.", "Lagerungstests der A. vertebralis gelten als unzuverlässig, die Anamnese zählt mehr."], "q": "IFOMPT-Rahmen 2020"}, "wainner": {"t": "Cluster nach Wainner", "x": ["Vier Befunde: ULTT A löst den bekannten Armschmerz aus, Rotation zur betroffenen Seite unter 60°, Distraktion lindert den Armschmerz, Spurling positiv.", "Drei von vier positiv: positive Likelihood Ratio 6,1. Alle vier positiv: 30,3, aber mit sehr breitem Vertrauensbereich, weil die Studie klein war. Ein einzelner negativer Test schließt eine Radikulopathie nicht aus."], "q": "Wainner RS et al., Spine 2003"}, "hoffmann": {"t": "Hoffmann-Zeichen", "x": ["Endglied des Mittelfingers schnell nach palmar schnippen. Positiv ist eine Beugung von Daumen und Zeigefinger. Es weist auf eine Störung der oberen Motoneurone hin.", "Cluster nach Cook 2010: Gangstörung, Hoffmann, umgekehrter Radiusperiostreflex, Babinski, Alter über 45. Drei von fünf positiv sprechen stark für eine Myelopathie (LR+ 30,9). Ist höchstens einer positiv, spricht das eher dagegen (LR− 0,18)."], "q": "Cook C et al., JMMT 2010"}}}]});
